window.PK=window.PK||{};window.PK.peptides=[{"slug":"bpc-157","name":"BPC-157","synonyme":["Composto di Protezione Corporea 157","PL 14736"],"kategorie":"Regeneration","studienlage":"frühe klinische Studien","kurz":"Un peptide sintetico studiato principalmente in modelli preclinici di rigenerazione dei tessuti.","kurz_en":"Un peptide sintetico studiato principalmente in modelli preclinici di rigenerazione dei tessuti.","beschreibung":"BPC-157 è un pentadecapeptide sintetico la cui sequenza è derivata da una proteina protettiva trovata nel succo gastrico umano. È tra i peptidi più studiati nella ricerca sulla rigenerazione dei tessuti, con una vasta base di studi sugli animali e un numero limitato di piccoli studi umani. Le aree di focus della ricerca includono tendini, legamenti, rivestimento gastrointestinale e guarigione delle ferite.","beschreibung_en":"BPC-157 è un pentadecapeptide sintetico la cui sequenza è derivata da una proteina protettiva trovata nel succo gastrico umano. È tra i peptidi più studiati nella ricerca sulla rigenerazione dei tessuti, con una vasta base di studi sugli animali e un numero limitato di piccoli studi umani. Le aree di focus della ricerca includono tendini, legamenti, rivestimento gastrointestinale e guarigione delle ferite.","mechanismus":"Nei modelli preclinici, BPC-157 è stato descritto come coinvolto nell'angiogenesi attraverso la via VEGFR2-AKT-eNOS, supportando la formazione di nuovi vasi sanguigni nel tessuto lesionato. Altri meccanismi studiati includono la sovraregolazione dei recettori dell'ormone della crescita, la modulazione delle citochine infiammatorie e il supporto della migrazione cellulare attraverso la via FAK-paxillina. I meccanismi esatti negli esseri umani non sono ancora pienamente stabiliti.","mechanismus_en":"Nei modelli preclinici, BPC-157 è stato descritto come coinvolto nell'angiogenesi attraverso la via VEGFR2-AKT-eNOS, supportando la formazione di nuovi vasi sanguigni nel tessuto lesionato. Altri meccanismi studiati includono la sovraregolazione dei recettori dell'ormone della crescita, la modulazione delle citochine infiammatorie e il supporto della migrazione cellulare attraverso la via FAK-paxillina. I meccanismi esatti negli esseri umani non sono ancora pienamente stabiliti.","evidenz":[{"art":"preclinico","kurz":"Una revisione sistematica del 2025 ha valutato la letteratura dal 1993 al 2024 e ha incluso 35 studi preclinici sugli animali su lesioni muscolari, tendinee, legamentose e ossee, che hanno descritto in gran parte risultati di guarigione positivi.","kurz_en":"Una revisione sistematica del 2025 ha valutato la letteratura dal 1993 al 2024 e ha incluso 35 studi preclinici sugli animali su lesioni muscolari, tendinee, legamentose e ossee, che hanno descritto in gran parte risultati di guarigione positivi.","quelle":"Vasireddi et al. 2025, HSS Journal, PMID 40756949"},{"art":"clinico","kurz":"La stessa revisione ha identificato una serie di casi clinici retrospettivi in cui 7 su 12 pazienti hanno riferito sollievo dal dolore durato più di sei mesi dopo iniezioni intra-articolari al ginocchio.","kurz_en":"La stessa revisione ha identificato una serie di casi clinici retrospettivi in cui 7 su 12 pazienti hanno riferito sollievo dal dolore durato più di sei mesi dopo iniezioni intra-articolari al ginocchio.","quelle":"Vasireddi et al. 2025, HSS Journal, PMID 40756949"},{"art":"clinico","kurz":"Una revisione retrospettiva di 16 pazienti con dolore al ginocchio ha descritto un miglioramento significativo in 14 di loro durante un periodo di follow-up di sei a dodici mesi. Non c'era un gruppo di controllo.","kurz_en":"Una revisione retrospettiva di 16 pazienti con dolore al ginocchio ha descritto un miglioramento significativo in 14 di loro durante un periodo di follow-up di sei a dodici mesi. Non c'era un gruppo di controllo.","quelle":"Lee & Padgett 2021, Altern Ther Health Med, PMID 34324435"}],"sicherheit":["I dati di sicurezza umani controllati con placebo rimangono in gran parte assenti, la maggior parte delle dichiarazioni di sicurezza sono tratte da modelli animali.","A livello meccanicistico, si discute che le stesse vie che guidano l'angiogenesi e la proliferazione cellulare durante la guarigione potrebbero teoricamente anche supportare la crescita tumorale esistente. Un legame causale negli esseri umani non è stato stabilito.","Gli studi umani piccoli disponibili non hanno riportato eventi avversi gravi.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"sicherheit_en":["I dati di sicurezza umani controllati con placebo rimangono in gran parte assenti, la maggior parte delle dichiarazioni di sicurezza sono tratte da modelli animali.","A livello meccanicistico, si discute che le stesse vie che guidano l'angiogenesi e la proliferazione cellulare durante la guarigione potrebbero teoricamente anche supportare la crescita tumorale esistente. Un legame causale negli esseri umani non è stato stabilito.","Gli studi umani piccoli disponibili non hanno riportato eventi avversi gravi.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"BPC-157 non è autorizzato come farmaco in Germania, nell’UE o negli Stati Uniti e non è classificato come prodotto alimentare. È venduto esclusivamente come sostanza chimica per la ricerca.","rechtsstatus_en":"BPC-157 non è autorizzato come farmaco in Germania, nell’UE o negli Stati Uniti e non è classificato come prodotto alimentare. È venduto esclusivamente come sostanza chimica per la ricerca.","typischeMg":[],"faq":[{"q":"BPC-157 è un farmaco approvato?","a":"No. BPC-157 non è approvato come farmaco nell'UE o negli Stati Uniti. Viene venduto commercialmente solo come prodotto chimico per uso di laboratorio, non per uso umano.","q_en":"BPC-157 è un farmaco approvato?","a_en":"No. BPC-157 non è approvato come farmaco nell'UE o negli Stati Uniti. Viene venduto commercialmente solo come prodotto chimico per uso di laboratorio, non per uso umano."},{"q":"Da dove proviene la sequenza BPC-157?","a":"Deriva da una proteina protettiva trovata nel succo gastrico umano, che è anche l'origine del nome Body Protection Compound.","q_en":"Da dove proviene la sequenza BPC-157?","a_en":"Deriva da una proteina protettiva trovata nel succo gastrico umano, che è anche l'origine del nome Body Protection Compound."},{"q":"Ci sono studi sull'uomo su BPC-157?","a":"Ci sono alcuni piccoli studi e serie di casi con limitazioni metodologiche, ma nessun trial randomizzato con placebo. La maggior parte delle evidenze proviene da modelli animali.","q_en":"Ci sono studi sull'uomo su BPC-157?","a_en":"Ci sono alcuni piccoli studi e serie di casi con limitazioni metodologiche, ma nessun trial randomizzato con placebo. La maggior parte delle evidenze proviene da modelli animali."}],"seo":{"title":"BPC-157: profilo di ricerca ed evidenze","title_en":"BPC-157: profilo di ricerca ed evidenze","description":"Panoramica BPC-157: origine, meccanismo, evidenze e profilo di sicurezza, presentati in modo fattuale per il contesto di ricerca.","description_en":"Panoramica BPC-157: origine, meccanismo, evidenze e profilo di sicurezza, presentati in modo fattuale per il contesto di ricerca."},"demo":false,"steckbrief":{"cas":"137525-51-0","molekulargewicht":"1419,5 g/mol","aminosaeuren":15,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":15,"quellen":["PubChem CID 9941957","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, standard commerciale)"},"verwandt":["tb-500","ghk-cu","thymosin-alpha-1","pentadeca-arginate"]},{"slug":"pentadeca-arginate","name":"Pentadeca Arginate (PDA)","synonyme":["PDA","Sale di arginina di BPC-157"],"kategorie":"Regeneration","studienlage":"präklinisch","kurz":"Un pentadecapeptide che condivide la sequenza di amminoacidi di BPC-157, offerto come sale di arginina per migliorata solubilità e stabilità.","kurz_en":"Un pentadecapeptide che condivide la sequenza di amminoacidi di BPC-157, offerto come sale di arginina per migliorata solubilità e stabilità.","beschreibung":"Pentadeca Arginate, spesso abbreviato PDA, porta la stessa sequenza di 15 amminoacidi del noto peptide BPC-157. La differenza risiede nel controione: invece di un sale di acetato, la sequenza è legata all'arginina, che i fornitori descrivono come migliorando la solubilità e la stabilità di conservazione. Studi indipendenti che esaminano questa specifica forma di sale non sono ancora disponibili.","beschreibung_en":"Pentadeca Arginate, spesso abbreviato PDA, porta la stessa sequenza di 15 amminoacidi del noto peptide BPC-157. La differenza risiede nel controione: invece di un sale di acetato, la sequenza è legata all'arginina, che i fornitori descrivono come migliorando la solubilità e la stabilità di conservazione. Studi indipendenti che esaminano questa specifica forma di sale non sono ancora disponibili.","mechanismus":"Poiché la sequenza di amminoacidi è identica a BPC-157, i meccanismi descritti nei modelli preclinici si basano sulla stessa struttura sottostante, inclusa la partecipazione all'angiogenesi attraverso la via VEGFR2-AKT-eNOS e la modulazione dei processi infiammatori. Non è stato studiato indipendentemente se il legame con l'arginina modifichi, acceleri o rallenti questi effetti. I meccanismi esatti negli esseri umani rimangono irrisolti anche per la sequenza genitore stessa.","mechanismus_en":"Poiché la sequenza di amminoacidi è identica a BPC-157, i meccanismi descritti nei modelli preclinici si basano sulla stessa struttura sottostante, inclusa la partecipazione all'angiogenesi attraverso la via VEGFR2-AKT-eNOS e la modulazione dei processi infiammatori. Non è stato studiato indipendentemente se il legame con l'arginina modifichi, acceleri o rallenti questi effetti. I meccanismi esatti negli esseri umani rimangono irrisolti anche per la sequenza genitore stessa.","evidenz":[{"art":"preclinico","kurz":"Poiché Pentadeca Arginate condivide la sua sequenza con BPC-157, le evidenze disponibili si basano su studi della sequenza genitore. Una revisione sistematica del 2025 ha valutato 35 studi preclinici su lesioni muscolari, tendinee, legamenti e ossee, che hanno descritto in gran parte risultati di guarigione positivi.","kurz_en":"Poiché Pentadeca Arginate condivide la sua sequenza con BPC-157, le evidenze disponibili si basano su studi della sequenza genitore. Una revisione sistematica del 2025 ha valutato 35 studi preclinici su lesioni muscolari, tendinee, legamenti e ossee, che hanno descritto in gran parte risultati di guarigione positivi.","quelle":"Vasireddi et al. 2025, HSS Journal, PMID 40756949"},{"art":"preclinico","kurz":"Uno studio cellulare ha descritto l'attivazione e la sovraregolazione del VEGFR2, un recettore chiave nella formazione dei vasi sanguigni, per la stessa sequenza, accompagnata da un aumento della formazione di tubuli endoteliali nel modello di laboratorio.","kurz_en":"Uno studio cellulare ha descritto l'attivazione e la sovraregolazione del VEGFR2, un recettore chiave nella formazione dei vasi sanguigni, per la stessa sequenza, accompagnata da un aumento della formazione di tubuli endoteliali nel modello di laboratorio.","quelle":"Hsieh et al. 2016, Journal of Molecular Medicine, PMID 27847966"}],"sicherheit":["Non esistono dati di sicurezza indipendenti per la forma di sale dell'arginina stessa, una ricerca bibliografica mirata non ha restituito risultati.","I dati umani controllati con placebo sono in gran parte assenti per la sequenza sottostante, la maggior parte delle dichiarazioni di sicurezza sono tratte da modelli animali.","A livello meccanicistico, si discute che le stesse vie che guidano l'angiogenesi e la proliferazione cellulare durante la guarigione potrebbero teoricamente anche supportare la crescita tumorale esistente. Un legame causale negli esseri umani non è stato stabilito.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"sicherheit_en":["Non esistono dati di sicurezza indipendenti per la forma di sale dell'arginina stessa, una ricerca bibliografica mirata non ha restituito risultati.","I dati umani controllati con placebo sono in gran parte assenti per la sequenza sottostante, la maggior parte delle dichiarazioni di sicurezza sono tratte da modelli animali.","A livello meccanicistico, si discute che le stesse vie che guidano l'angiogenesi e la proliferazione cellulare durante la guarigione potrebbero teoricamente anche supportare la crescita tumorale esistente. Un legame causale negli esseri umani non è stato stabilito.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Pentadeca Arginate non è autorizzato come farmaco in Germania, nell’UE o negli Stati Uniti e non è classificato come prodotto alimentare. È venduto esclusivamente come sostanza chimica per la ricerca.","rechtsstatus_en":"Pentadeca Arginate non è autorizzato come farmaco in Germania, nell’UE o negli Stati Uniti e non è classificato come prodotto alimentare. È venduto esclusivamente come sostanza chimica per la ricerca.","typischeMg":[],"faq":[{"q":"Pentadeca Arginate è lo stesso di BPC-157?","a":"La sequenza degli amminoacidi è identica. La differenza risiede nel controione: BPC-157 viene solitamente offerto come sale acetato, Pentadeca Arginate come sale di arginina, che i fornitori descrivono come migliorando la solubilità.","q_en":"Pentadeca Arginate è lo stesso di BPC-157?","a_en":"La sequenza degli amminoacidi è identica. La differenza risiede nel controione: BPC-157 viene solitamente offerto come sale acetato, Pentadeca Arginate come sale di arginina, che i fornitori descrivono come migliorando la solubilità."},{"q":"Esistono studi indipendenti sulla forma di sale dell'arginina?","a":"No, una ricerca bibliografica mirata non ha trovato studi indipendenti sulla forma di sale dell'arginina stessa. Le evidenze disponibili si riferiscono alla sequenza genitore di BPC-157.","q_en":"Esistono studi indipendenti sulla forma di sale dell'arginina?","a_en":"No, una ricerca bibliografica mirata non ha trovato studi indipendenti sulla forma di sale dell'arginina stessa. Le evidenze disponibili si riferiscono alla sequenza genitore di BPC-157."},{"q":"Pentadeca Arginate è un farmaco approvato?","a":"No. Non è approvato nell'UE o negli Stati Uniti e viene venduto esclusivamente come prodotto chimico di ricerca per uso di laboratorio.","q_en":"Pentadeca Arginate è un farmaco approvato?","a_en":"No. Non è approvato nell'UE o negli Stati Uniti e viene venduto esclusivamente come prodotto chimico di ricerca per uso di laboratorio."}],"seo":{"title":"Pentadeca Arginate (PDA): Profilo di Ricerca e Evidenze","title_en":"Pentadeca Arginate (PDA): Profilo di Ricerca e Evidenze","description":"Panoramica di Pentadeca Arginate: identità di sequenza con BPC-157, evidenze sulla sequenza genitore e profilo di sicurezza, presentati in modo fattuale per la ricerca.","description_en":"Panoramica di Pentadeca Arginate: identità di sequenza con BPC-157, evidenze sulla sequenza genitore e profilo di sicurezza, presentati in modo fattuale per la ricerca."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":null,"aminosaeuren":15,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":15,"quellen":["chemverify Katalog 14.09.2026 (CAS/Molekulargewicht dort nicht geführt, PubChem: kein Eintrag für Pentadeca Arginate)"]},"verwandt":["bpc-157","tb-500","ghk-cu"]},{"slug":"tb-500","name":"TB-500","synonyme":["Frammento di timosina beta-4","TB4 Frag"],"kategorie":"Regeneration","studienlage":"präklinisch","kurz":"Un frammento sintetico della proteina propria del corpo, la timosina beta-4, studiato in ricerche precliniche sulla migrazione cellulare e la rigenerazione tissutale.","kurz_en":"Un frammento sintetico della proteina propria del corpo, la timosina beta-4, studiato in ricerche precliniche sulla migrazione cellulare e la rigenerazione tissutale.","beschreibung":"TB-500 è la sequenza centrale a sette amminoacidi prodotta sinteticamente della proteina propria del corpo timosina beta-4. La maggior parte dei dati disponibili, inclusi gli studi clinici, si riferiscono alla timosina beta-4 completa a 43 amminoacidi, non al frammento isolato TB-500 stesso. Le aree di studio includono la migrazione cellulare, l'angiogenesi e un possibile ruolo nell'attivazione dei follicoli piliferi.","beschreibung_en":"TB-500 è la sequenza centrale a sette amminoacidi prodotta sinteticamente della proteina propria del corpo timosina beta-4. La maggior parte dei dati disponibili, inclusi gli studi clinici, si riferiscono alla timosina beta-4 completa a 43 amminoacidi, non al frammento isolato TB-500 stesso. Le aree di studio includono la migrazione cellulare, l'angiogenesi e un possibile ruolo nell'attivazione dei follicoli piliferi.","mechanismus":"La sequenza centrale studiata si lega alla G-actina, un elemento costitutivo del citoscheletro, influenzando così il movimento cellulare all'interno del tessuto. Nella proteina completa della timosina beta-4, sono state anche descritte l'implicazione nell'angiogenesi attraverso l'aumento dell'espressione di VEGF e un effetto regolatore dell'infiammazione attraverso la via NF-κB. Se questi meccanismi si trasferiscono pienamente al frammento isolato TB-500 non è stabilito scientificamente.","mechanismus_en":"La sequenza centrale studiata si lega alla G-actina, un elemento costitutivo del citoscheletro, influenzando così il movimento cellulare all'interno del tessuto. Nella proteina completa della timosina beta-4, sono state anche descritte l'implicazione nell'angiogenesi attraverso l'aumento dell'espressione di VEGF e un effetto regolatore dell'infiammazione attraverso la via NF-κB. Se questi meccanismi si trasferiscono pienamente al frammento isolato TB-500 non è stabilito scientificamente.","evidenz":[{"art":"preclinico","kurz":"Uno studio in ratti e topi ha descritto che la sequenza attiva della timosina beta-4, che forma anche TB-500, ha influenzato la migrazione delle cellule staminali all'interno del follicolo pilifero.","kurz_en":"Uno studio in ratti e topi ha descritto che la sequenza attiva della timosina beta-4, che forma anche TB-500, ha influenzato la migrazione delle cellule staminali all'interno del follicolo pilifero.","quelle":"Philp et al. 2004, FASEB Journal, PMID 14657002"},{"art":"clinico","kurz":"Uno studio clinico randomizzato e controllato con placebo in pazienti con secchezza oculare grave ha testato una formulazione in gocce dell'intera proteina della timosina beta-4 e ha descritto miglioramenti nei segni e sintomi rispetto al placebo. Lo studio ha coinvolto la proteina completa, non il frammento TB-500 stesso.","kurz_en":"Uno studio clinico randomizzato e controllato con placebo in pazienti con secchezza oculare grave ha testato una formulazione in gocce dell'intera proteina della timosina beta-4 e ha descritto miglioramenti nei segni e sintomi rispetto al placebo. Lo studio ha coinvolto la proteina completa, non il frammento TB-500 stesso.","quelle":"Sosne et al. 2015, Cornea, PMID 25826322"}],"sicherheit":["Per TB-500 come frammento isolato, non sono disponibili studi di sicurezza umana controllati indipendenti.","Per la proteina completa della timosina beta-4, gli studi clinici hanno descritto principalmente effetti collaterali lievi e transitori.","A livello meccanicistico, si discute un collegamento teorico tra gli effetti promossi dall'angiogenesi e la crescita tumorale esistente, una connessione causale non è stata stabilita.","La timosina beta-4 e i frammenti correlati sono presenti sulla lista proibita dell'Agenzia Mondiale Antidoping."],"sicherheit_en":["Per TB-500 come frammento isolato, non sono disponibili studi di sicurezza umana controllati indipendenti.","Per la proteina completa della timosina beta-4, gli studi clinici hanno descritto principalmente effetti collaterali lievi e transitori.","A livello meccanicistico, si discute un collegamento teorico tra gli effetti promossi dall'angiogenesi e la crescita tumorale esistente, una connessione causale non è stata stabilita.","La timosina beta-4 e i frammenti correlati sono presenti sulla lista proibita dell'Agenzia Mondiale Antidoping."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"TB-500 non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti, ed è venduto esclusivamente come sostanza chimica per la ricerca. La proteina correlata timosina beta-4 non è approvata come farmaco autonomo.","rechtsstatus_en":"TB-500 non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti, ed è venduto esclusivamente come sostanza chimica per la ricerca. La proteina correlata timosina beta-4 non è approvata come farmaco autonomo.","typischeMg":[],"faq":[{"q":"TB-500 è la stessa cosa della timosina beta-4?","a":"No. TB-500 è un frammento sintetico di sette amminoacidi della sequenza completa di 43 amminoacidi della timosina beta-4. La maggior parte dei dati clinici si riferisce alla proteina completa, non al frammento.","q_en":"TB-500 è la stessa cosa della timosina beta-4?","a_en":"No. TB-500 è un frammento sintetico di sette amminoacidi della sequenza completa di 43 amminoacidi della timosina beta-4. La maggior parte dei dati clinici si riferisce alla proteina completa, non al frammento."},{"q":"Ci sono studi clinici su TB-500 stesso?","a":"Non sono disponibili studi umani controllati indipendenti sul frammento isolato TB-500. I dati clinici disponibili provengono dalla proteina completa della timosina beta-4.","q_en":"Ci sono studi clinici su TB-500 stesso?","a_en":"Non sono disponibili studi umani controllati indipendenti sul frammento isolato TB-500. I dati clinici disponibili provengono dalla proteina completa della timosina beta-4."},{"q":"TB-500 è rilevante per le regole antidoping?","a":"La timosina beta-4 e i frammenti correlati sono presenti sulla lista proibita dell'Agenzia Mondiale Antidoping.","q_en":"TB-500 è rilevante per le regole antidoping?","a_en":"La timosina beta-4 e i frammenti correlati sono presenti sulla lista proibita dell'Agenzia Mondiale Antidoping."}],"seo":{"title":"TB-500: profilo di ricerca ed evidenze","title_en":"TB-500: profilo di ricerca ed evidenze","description":"Panoramica TB-500: origine da timosina beta-4, meccanismo, evidenze e profilo di sicurezza, presentati in modo fattuale per il contesto della ricerca.","description_en":"Panoramica TB-500: origine da timosina beta-4, meccanismo, evidenze e profilo di sicurezza, presentati in modo fattuale per il contesto della ricerca."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":"4963 g/mol","aminosaeuren":43,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":43,"quellen":["PubChem CID 45382195","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, standard commerciale)"},"verwandt":["bpc-157","ghk-cu","thymosin-alpha-1","pentadeca-arginate"]},{"slug":"5-amino-1mq","name":"5-Amino-1MQ","synonyme":["5-Amino 1MQ","5A1MQ","Inibitore NNMT"],"kategorie":"Stoffwechsel","studienlage":"präklinisch","kurz":"Una piccola molecola e inibitore selettivo dell'enzima nicotinammide N-metiltransferasi (NNMT), studiata fino ad oggi esclusivamente in modelli animali preclinici relativi al metabolismo dei grassi.","kurz_en":"Una piccola molecola e inibitore selettivo dell'enzima nicotinammide N-metiltransferasi (NNMT), studiata fino ad oggi esclusivamente in modelli animali preclinici relativi al metabolismo dei grassi.","beschreibung":"5-Amino-1MQ non è un peptide ma una piccola molecola, un inibitore selettivo e oralmente biodisponibile della nicotinammide N-metiltransferasi (NNMT). Ha un peso molecolare di 173,21 Da e i lotti di ricerca venduti commercialmente presentano tipicamente una purezza di almeno il 98 per cento. È elencato nella categoria del metabolismo perché la NNMT è coinvolta nel metabolismo energetico nel tessuto adiposo e muscolare. Ad oggi, sono disponibili solo dati preclinici da modelli murini e non sono noti studi umani controllati.","beschreibung_en":"5-Amino-1MQ non è un peptide ma una piccola molecola, un inibitore selettivo e oralmente biodisponibile della nicotinammide N-metiltransferasi (NNMT). Ha un peso molecolare di 173,21 Da e i lotti di ricerca venduti commercialmente presentano tipicamente una purezza di almeno il 98 per cento. È elencato nella categoria del metabolismo perché la NNMT è coinvolta nel metabolismo energetico nel tessuto adiposo e muscolare. Ad oggi, sono disponibili solo dati preclinici da modelli murini e non sono noti studi umani controllati.","mechanismus":"La NNMT trasferisce un gruppo metile dalla S-adenosilmetionina (SAM) alla nicotinammide, un precursore del NAD+, formando 1-metilnicotinammide. Questa reazione consuma sia SAM che la nicotinammide precursore del NAD+. Il 5-Amino-1MQ inibisce selettivamente questo enzima, che ha preservato i livelli intracellulari di NAD+ e SAM nelle cellule adipose e muscolari nei modelli animali. Nella ricerca preclinica, ciò è stato collegato a un aumento della spesa energetica, una riduzione della dimensione degli adipociti e un miglioramento della capacità rigenerativa del tessuto muscolare.","mechanismus_en":"La NNMT trasferisce un gruppo metile dalla S-adenosilmetionina (SAM) alla nicotinammide, un precursore del NAD+, formando 1-metilnicotinammide. Questa reazione consuma sia SAM che la nicotinammide precursore del NAD+. Il 5-Amino-1MQ inibisce selettivamente questo enzima, che ha preservato i livelli intracellulari di NAD+ e SAM nelle cellule adipose e muscolari nei modelli animali. Nella ricerca preclinica, ciò è stato collegato a un aumento della spesa energetica, una riduzione della dimensione degli adipociti e un miglioramento della capacità rigenerativa del tessuto muscolare.","evidenz":[{"art":"preclinico","kurz":"In un modello murino con knockdown genetico della NNMT nel tessuto adiposo, è stata osservata protezione contro l'obesità indotta dalla dieta rispetto agli animali di controllo, insieme a un aumento della spesa energetica.","kurz_en":"In un modello murino con knockdown genetico della NNMT nel tessuto adiposo, è stata osservata protezione contro l'obesità indotta dalla dieta rispetto agli animali di controllo, insieme a un aumento della spesa energetica.","quelle":"Kraus D et al. 2014, Nature 508:258-262, PMID 24717514"},{"art":"preclinico","kurz":"Nei topi obesi indotti dalla dieta, undici giorni di somministrazione di 5-Amino-1MQ hanno ridotto il peso corporeo, la massa grassa e la dimensione degli adipociti rispetto agli animali di controllo, senza alterare l'assunzione di cibo.","kurz_en":"Nei topi obesi indotti dalla dieta, undici giorni di somministrazione di 5-Amino-1MQ hanno ridotto il peso corporeo, la massa grassa e la dimensione degli adipociti rispetto agli animali di controllo, senza alterare l'assunzione di cibo.","quelle":"Neelakantan H et al. 2018, Biochemical Pharmacology, PMID 29155147"},{"art":"preclinico","kurz":"Nei topi invecchiati, un inibitore della NNMT è stato associato alla riattivazione delle cellule staminali muscolari senescenti e a un miglioramento della capacità rigenerativa del muscolo scheletrico dopo lesioni.","kurz_en":"Nei topi invecchiati, un inibitore della NNMT è stato associato alla riattivazione delle cellule staminali muscolari senescenti e a un miglioramento della capacità rigenerativa del muscolo scheletrico dopo lesioni.","quelle":"Neelakantan H et al. 2019, Biochemical Pharmacology 163:481-492, PMID 30753815"},{"art":"preclinico","kurz":"La combinazione di una dieta a calorie ridotte con 5-Amino-1MQ ha normalizzato la percentuale di grasso corporeo e il peso più rapidamente nei topi obesi indotti dalla dieta rispetto al solo cambiamento della dieta, alterando anche la composizione del microbioma intestinale.","kurz_en":"La combinazione di una dieta a calorie ridotte con 5-Amino-1MQ ha normalizzato la percentuale di grasso corporeo e il peso più rapidamente nei topi obesi indotti dalla dieta rispetto al solo cambiamento della dieta, alterando anche la composizione del microbioma intestinale.","quelle":"Scientific Reports 2022, PMID 35013352"}],"sicherheit":["nello studio del 2018 di Neelakantan et al. in topi obesi, l'assunzione di cibo non è cambiata con 5-Amino-1MQ, il che nel modello animale suggerisce una tollerabilità ragionevole durante il periodo dello studio.","Non sono noti studi di sicurezza umana controllati su 5-Amino-1MQ, sono disponibili solo dati da modelli animali.","Non sono stati pubblicati pacchetti tossicologici preclinici standardizzati, come studi di somministrazione ripetuta per più settimane in specie aggiuntive, per 5-Amino-1MQ.","Le interazioni con altre sostanze o integratori non sono state studiate sistematicamente per 5-Amino-1MQ."],"sicherheit_en":["nello studio del 2018 di Neelakantan et al. in topi obesi, l'assunzione di cibo non è cambiata con 5-Amino-1MQ, il che nel modello animale suggerisce una tollerabilità ragionevole durante il periodo dello studio.","Non sono noti studi di sicurezza umana controllati su 5-Amino-1MQ, sono disponibili solo dati da modelli animali.","Non sono stati pubblicati pacchetti tossicologici preclinici standardizzati, come studi di somministrazione ripetuta per più settimane in specie aggiuntive, per 5-Amino-1MQ.","Le interazioni con altre sostanze o integratori non sono state studiate sistematicamente per 5-Amino-1MQ."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"5-Amino-1MQ non è approvato come farmaco nell'UE o negli Stati Uniti ed è venduto esclusivamente come sostanza chimica di ricerca. Non sono note prove di approvazione umana.","rechtsstatus_en":"5-Amino-1MQ non è approvato come farmaco nell'UE o negli Stati Uniti ed è venduto esclusivamente come sostanza chimica di ricerca. Non sono note prove di approvazione umana.","typischeMg":[10,50],"faq":[{"q":"È 5-Amino-1MQ un peptide?","a":"No. 5-Amino-1MQ è una piccola molecola, non un peptide, e non è costituito da una catena di amminoacidi. Viene studiato come inibitore selettivo dell'enzima NNMT ed è elencato qui tra i composti correlati al metabolismo perché agisce su sistemi bersaglio correlati.","q_en":"È 5-Amino-1MQ un peptide?","a_en":"No. 5-Amino-1MQ è una piccola molecola, non un peptide, e non è costituito da una catena di amminoacidi. Viene studiato come inibitore selettivo dell'enzima NNMT ed è elencato qui tra i composti correlati al metabolismo perché agisce su sistemi bersaglio correlati."},{"q":"Ci sono studi sull'uomo su 5-Amino-1MQ?","a":"No, non sono note studi clinici controllati sugli esseri umani a oggi. Tutti i dati pubblicati provengono da ricerche precliniche su topi.","q_en":"Ci sono studi sull'uomo su 5-Amino-1MQ?","a_en":"No, non sono note studi clinici controllati sugli esseri umani a oggi. Tutti i dati pubblicati provengono da ricerche precliniche su topi."},{"q":"Perché viene studiato NNMT nella ricerca?","a":"NNMT è un enzima attivo nel tessuto adiposo e muscolare che scompone la nicotinamide, un precursore del NAD+. Livelli elevati di NNMT sono collegati a una ridotta attività metabolica in modelli preclinici, motivo per cui la sua inibizione viene studiata come approccio di ricerca.","q_en":"Perché viene studiato NNMT nella ricerca?","a_en":"NNMT è un enzima attivo nel tessuto adiposo e muscolare che scompone la nicotinamide, un precursore del NAD+. Livelli elevati di NNMT sono collegati a una ridotta attività metabolica in modelli preclinici, motivo per cui la sua inibizione viene studiata come approccio di ricerca."}],"seo":{"title":"5-Amino-1MQ: Inibitore di NNMT nella Ricerca Preclinica","title_en":"5-Amino-1MQ: Inibitore di NNMT nella Ricerca Preclinica","description":"5-Amino-1MQ in sintesi: meccanismo, stato dello studio preclinico e stato legale dell'inibitore di NNMT, una piccola molecola piuttosto che un peptide.","description_en":"5-Amino-1MQ in sintesi: meccanismo, stato dello studio preclinico e stato legale dell'inibitore di NNMT, una piccola molecola piuttosto che un peptide."},"demo":false,"steckbrief":{"cas":"685079-15-6","molekulargewicht":"159,21 g/mol","aminosaeuren":null,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":null,"quellen":["PubChem CID 950107","chemverify Katalog 14.09.2026","kein Peptid, kleines Molekül ohne Aminosäuresequenz (NNMT-Inhibitor)"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)"},"verwandt":["aod-9604","mots-c","tirzepatid"]},{"slug":"aod-9604","name":"AOD-9604","synonyme":["Farmaco anti-obesità 9604","Tyr-hGH Frag 177-191"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Un frammento peptidico dell'ormone della crescita umano (amminoacidi 177-191) studiato per un effetto di riduzione del grasso senza gli effetti di promozione della crescita dell'ormone completo.","kurz_en":"Un frammento peptidico dell'ormone della crescita umano (amminoacidi 177-191) studiato per un effetto di riduzione del grasso senza gli effetti di promozione della crescita dell'ormone completo.","beschreibung":"AOD-9604 è un frammento sintetico a 16 amminoacidi dell'ormone della crescita umano (sequenza Tyr-hGH177-191), originariamente sviluppato da Metabolic Pharmaceuticals in collaborazione con Monash University per la regolazione del peso. È stato studiato in sei studi umani randomizzati e controllati con placebo con più di 900 partecipanti per i suoi effetti metabolici e la sicurezza. Lo sviluppo clinico come composto per l'obesità è stato interrotto nel 2007 dopo che lo studio più grande non ha raggiunto il suo endpoint di efficacia primario.","beschreibung_en":"AOD-9604 è un frammento sintetico a 16 amminoacidi dell'ormone della crescita umano (sequenza Tyr-hGH177-191), originariamente sviluppato da Metabolic Pharmaceuticals in collaborazione con Monash University per la regolazione del peso. È stato studiato in sei studi umani randomizzati e controllati con placebo con più di 900 partecipanti per i suoi effetti metabolici e la sicurezza. Lo sviluppo clinico come composto per l'obesità è stato interrotto nel 2007 dopo che lo studio più grande non ha raggiunto il suo endpoint di efficacia primario.","mechanismus":"AOD-9604 comprende la regione lipolitica (amminoacidi 177-191) della molecola dell'ormone della crescita, senza la regione di legame al recettore responsabile della crescita e degli effetti metabolici mediati da IGF-1 dell'hGH completo. I modelli preclinici descrivono un'attivazione della lipolisi attraverso il messaggero di diacilglicerol e l'enzima lipasi sensibile all'ormone, mediata tramite il recettore adrenergico beta-3. A differenza dell'hGH completo, AOD-9604 non ha influenzato i livelli di IGF-1 o la sensibilità all'insulina negli studi.","mechanismus_en":"AOD-9604 comprende la regione lipolitica (amminoacidi 177-191) della molecola dell'ormone della crescita, senza la regione di legame al recettore responsabile della crescita e degli effetti metabolici mediati da IGF-1 dell'hGH completo. I modelli preclinici descrivono un'attivazione della lipolisi attraverso il messaggero di diacilglicerol e l'enzima lipasi sensibile all'ormone, mediata tramite il recettore adrenergico beta-3. A differenza dell'hGH completo, AOD-9604 non ha influenzato i livelli di IGF-1 o la sensibilità all'insulina negli studi.","evidenz":[{"art":"preclinico","kurz":"In uno studio preclinico in ratti Zucker obesi, 19 giorni di somministrazione orale di AOD-9604 hanno ridotto l'aumento di peso corporeo di più del 50 per cento rispetto agli animali di controllo.","kurz_en":"In uno studio preclinico in ratti Zucker obesi, 19 giorni di somministrazione orale di AOD-9604 hanno ridotto l'aumento di peso corporeo di più del 50 per cento rispetto agli animali di controllo.","quelle":"Ng FM et al. 2000, Hormone Research 53(6):274-278, PMID 11146367"},{"art":"preclinico","kurz":"Nei topi obesi, l'amministrazione cronica di AOD-9604 aumentò l'ossidazione dei grassi e la sensibilità lipolitica tramite la via del recettore adrenergico beta-3, paragonabile all'hGH completo ma senza influenzare la sensibilità all'insulina.","kurz_en":"Nei topi obesi, l'amministrazione cronica di AOD-9604 aumentò l'ossidazione dei grassi e la sensibilità lipolitica tramite la via del recettore adrenergico beta-3, paragonabile all'hGH completo ma senza influenzare la sensibilità all'insulina.","quelle":"Heffernan M et al. 2001, Endocrinology 142(12):5182-5189, PMID 11673763"},{"art":"clinico","kurz":"In uno studio multicentrico randomizzato, doppio cieco, controllato con placebo su 300 adulti con obesità, il gruppo che ha ricevuto 1 mg per via orale giornaliera ha perso in media 2,8 kg in 12 settimane rispetto a 0,8 kg sotto placebo.","kurz_en":"In uno studio multicentrico randomizzato, doppio cieco, controllato con placebo su 300 adulti con obesità, il gruppo che ha ricevuto 1 mg per via orale giornaliera ha perso in media 2,8 kg in 12 settimane rispetto a 0,8 kg sotto placebo.","quelle":"Herd C et al. 2005, randomisierte Multicenter-Studie (Publikationsnachweis: ResearchGate ID 295313034 / University of Melbourne)"},{"art":"clinico","kurz":"Una revisione della sicurezza attraverso sei studi clinici umani randomizzati, controllati con placebo, non ha riscontrato un aumento dei livelli di IGF-1, nessun evento avverso grave correlato ad AOD-9604 e nessun anticorpo anti-AOD-9604 rilevabile.","kurz_en":"Una revisione della sicurezza attraverso sei studi clinici umani randomizzati, controllati con placebo, non ha riscontrato un aumento dei livelli di IGF-1, nessun evento avverso grave correlato ad AOD-9604 e nessun anticorpo anti-AOD-9604 rilevabile.","quelle":"Stier H et al. 2013, Journal of Endocrinology and Metabolism 3(2), jofem.org"}],"sicherheit":["Attraverso sei studi clinici umani randomizzati, controllati con placebo, non si sono verificati eventi avversi gravi correlati ad AOD-9604 e gli effetti riportati sono stati minori e transitori.","A differenza dell'hGH completo, AOD-9604 non ha aumentato i livelli di IGF-1 o compromesso la tolleranza al glucosio in questi studi.","Nessun anticorpo contro AOD-9604 è stato rilevato negli studi che hanno testato l'immunogenicità.","Lo sviluppo clinico è stato interrotto nel 2007 dopo che lo studio di fase 2b più ampio non ha raggiunto statisticamente il suo endpoint primario di perdita di peso rispetto al placebo, senza segnalazioni di preoccupazioni per la sicurezza come motivo.","Poiché AOD-9604 non è approvato come farmaco da nessuna parte, non esistono informazioni ufficiali per la prescrizione sulla sicurezza a lungo termine."],"sicherheit_en":["Attraverso sei studi clinici umani randomizzati, controllati con placebo, non si sono verificati eventi avversi gravi correlati ad AOD-9604 e gli effetti riportati sono stati minori e transitori.","A differenza dell'hGH completo, AOD-9604 non ha aumentato i livelli di IGF-1 o compromesso la tolleranza al glucosio in questi studi.","Nessun anticorpo contro AOD-9604 è stato rilevato negli studi che hanno testato l'immunogenicità.","Lo sviluppo clinico è stato interrotto nel 2007 dopo che lo studio di fase 2b più ampio non ha raggiunto statisticamente il suo endpoint primario di perdita di peso rispetto al placebo, senza segnalazioni di preoccupazioni per la sicurezza come motivo.","Poiché AOD-9604 non è approvato come farmaco da nessuna parte, non esistono informazioni ufficiali per la prescrizione sulla sicurezza a lungo termine."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"AOD-9604 non è approvato come farmaco nell'UE o negli Stati Uniti. Lo sviluppo clinico come composto per l'obesità è stato interrotto nel 2007 dopo uno studio di fase 2b. La sostanza è venduta esclusivamente come sostanza chimica di ricerca ed è elencata sulla Lista Proibita WADA per lo sport.","rechtsstatus_en":"AOD-9604 non è approvato come farmaco nell'UE o negli Stati Uniti. Lo sviluppo clinico come composto per l'obesità è stato interrotto nel 2007 dopo uno studio di fase 2b. La sostanza è venduta esclusivamente come sostanza chimica di ricerca ed è elencata sulla Lista Proibita WADA per lo sport.","typischeMg":[2,5,10],"faq":[{"q":"AOD-9604 è approvato come farmaco?","a":"No. AOD-9604 è stato studiato in sei studi clinici e lo sviluppo come composto per l'obesità è stato interrotto nel 2007. Attualmente non è un farmaco approvato ed è venduto solo come sostanza chimica di ricerca.","q_en":"AOD-9604 è approvato come farmaco?","a_en":"No. AOD-9604 è stato studiato in sei studi clinici e lo sviluppo come composto per l'obesità è stato interrotto nel 2007. Attualmente non è un farmaco approvato ed è venduto solo come sostanza chimica di ricerca."},{"q":"Come si differenzia AOD-9604 dall'ormone della crescita completo?","a":"AOD-9604 contiene solo la regione lipolitica della molecola di hGH (amminoacidi 177-191), non la regione che innesca gli effetti di crescita mediati da IGF-1. A differenza dell'hGH integro, non ha mostrato alcun effetto su IGF-1 o sulla sensibilità all'insulina negli studi.","q_en":"Come si differenzia AOD-9604 dall'ormone della crescita completo?","a_en":"AOD-9604 contiene solo la regione lipolitica della molecola di hGH (amminoacidi 177-191), non la regione che innesca gli effetti di crescita mediati da IGF-1. A differenza dell'hGH integro, non ha mostrato alcun effetto su IGF-1 o sulla sensibilità all'insulina negli studi."},{"q":"AOD-9604 è consentito nello sport?","a":"No. AOD-9604 è elencato come frammento di ormone della crescita sulla Lista Proibita WADA e non è disponibile un'esenzione per uso terapeutico per esso.","q_en":"AOD-9604 è consentito nello sport?","a_en":"No. AOD-9604 è elencato come frammento di ormone della crescita sulla Lista Proibita WADA e non è disponibile un'esenzione per uso terapeutico per esso."}],"seo":{"title":"AOD-9604: Frammento hGH 177-191 in Ricerca","title_en":"AOD-9604: Frammento hGH 177-191 in Ricerca","description":"AOD-9604 a colpo d'occhio: meccanismo, stato dello studio e profilo di sicurezza del frammento hGH 177-191 studiato in studi clinici sulla regolazione del peso.","description_en":"AOD-9604 a colpo d'occhio: meccanismo, stato dello studio e profilo di sicurezza del frammento hGH 177-191 studiato in studi clinici sulla regolazione del peso."},"demo":false,"steckbrief":{"cas":"221231-10-3","molekulargewicht":"1815,1 g/mol","aminosaeuren":16,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":16,"quellen":["PubChem CID 71300630","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)"},"verwandt":["tesamorelin","mots-c","5-amino-1mq"]},{"slug":"cagrilintid","name":"Cagrilintide","synonyme":["AM833","NN9838"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Un analogo a lunga durata d'azione dell'ormone proprio del corpo amilina, studiato in studi clinici per la regolazione del metabolismo e della sazietà, da solo e in combinazione con semaglutide.","kurz_en":"Un analogo a lunga durata d'azione dell'ormone proprio del corpo amilina, studiato in studi clinici per la regolazione del metabolismo e della sazietà, da solo e in combinazione con semaglutide.","beschreibung":"Cagrilintide è un analogo dell'amilina a lunga durata d'azione sviluppato da Novo Nordisk. Viene studiato sia come sostanza autonoma sia in combinazione fissa con il composto GLP-1 semaglutide, commercializzato con il nome CagriSema, in studi di fase 3. Ad oggi, cagrilintide non è approvato come farmaco autonomo in nessun paese.","beschreibung_en":"Cagrilintide è un analogo dell'amilina a lunga durata d'azione sviluppato da Novo Nordisk. Viene studiato sia come sostanza autonoma sia in combinazione fissa con il composto GLP-1 semaglutide, commercializzato con il nome CagriSema, in studi di fase 3. Ad oggi, cagrilintide non è approvato come farmaco autonomo in nessun paese.","mechanismus":"Cagrilintide si lega ai recettori dell'amilina nel cervello, principalmente i sottotipi AMY1 e AMY3 formati dal recettore della calcitonina insieme alle proteine RAMP accessorie. Ciò è collegato a un rallentamento dello svuotamento gastrico, alla ridotta secrezione di glucagone postprandiale e al segnale di sazietà in regioni cerebrali come l'area postrema. La lipidazione con acidi grassi della molecola estende sostanzialmente la sua durata d'azione rispetto all'ormone naturale amilina, consentendo una somministrazione settimanale nel contesto dello studio.","mechanismus_en":"Cagrilintide si lega ai recettori dell'amilina nel cervello, principalmente i sottotipi AMY1 e AMY3 formati dal recettore della calcitonina insieme alle proteine RAMP accessorie. Ciò è collegato a un rallentamento dello svuotamento gastrico, alla ridotta secrezione di glucagone postprandiale e al segnale di sazietà in regioni cerebrali come l'area postrema. La lipidazione con acidi grassi della molecola estende sostanzialmente la sua durata d'azione rispetto all'ormone naturale amilina, consentendo una somministrazione settimanale nel contesto dello studio.","evidenz":[{"art":"clinico","kurz":"In uno studio randomizzato di fase 2 che ha testato diverse quantità in 706 adulti con sovrappeso o obesità, cagrilintide da solo nell'arco di 26 settimane ha portato a una perdita media di peso corporeo del 10,8 per cento con la quantità più alta testata, rispetto a circa il 3 per cento con il placebo.","kurz_en":"In uno studio randomizzato di fase 2 che ha testato diverse quantità in 706 adulti con sovrappeso o obesità, cagrilintide da solo nell'arco di 26 settimane ha portato a una perdita media di peso corporeo del 10,8 per cento con la quantità più alta testata, rispetto a circa il 3 per cento con il placebo.","quelle":"Lau DCW et al. 2021, The Lancet 398:2160-2172, PMID 34798060"},{"art":"clinico","kurz":"nello studio di fase 3 REDEFINE 1, il braccio con cagrilintide da solo a 2,4 mg settimanali ha raggiunto una perdita di peso corporeo di circa il 11,8 per cento dopo 68 settimane, rispetto al 2,3 per cento sotto placebo.","kurz_en":"nello studio di fase 3 REDEFINE 1, il braccio con cagrilintide da solo a 2,4 mg settimanali ha raggiunto una perdita di peso corporeo di circa il 11,8 per cento dopo 68 settimane, rispetto al 2,3 per cento sotto placebo.","quelle":"Garvey WT et al. 2025, New England Journal of Medicine 393:625-638, PMID 40544433"},{"art":"preclinico","kurz":"In un modello murino di obesità indotta da dieta, l'effetto di riduzione del peso corporeo di cagrilintide dipendeva dai recettori dell'amilina cerebrali AMY1 e AMY3, e l'effetto era assente negli animali con knockout dei recettori.","kurz_en":"In un modello murino di obesità indotta da dieta, l'effetto di riduzione del peso corporeo di cagrilintide dipendeva dai recettori dell'amilina cerebrali AMY1 e AMY3, e l'effetto era assente negli animali con knockout dei recettori.","quelle":"Carvas AO et al. 2025, eBioMedicine, PMID 40609154"},{"art":"preclinico","kurz":"L'ottimizzazione strutturale con lipidazione con acidi grassi ha conferito a cagrilintide un'emivita sostanzialmente più lunga di circa 159 a 195 ore rispetto all'ormone proprio del corpo amilina, consentendo una somministrazione settimanale nel contesto dello studio.","kurz_en":"L'ottimizzazione strutturale con lipidazione con acidi grassi ha conferito a cagrilintide un'emivita sostanzialmente più lunga di circa 159 a 195 ore rispetto all'ormone proprio del corpo amilina, consentendo una somministrazione settimanale nel contesto dello studio.","quelle":"Kruse T et al. 2021, Journal of Medicinal Chemistry 64:11183-11194, PMID 34288673"}],"sicherheit":["nello studio randomizzato di fase 2 con cagrilintide come unica sostanza, gli effetti gastrointestinali si sono verificati nel 41 al 63 per cento dei partecipanti, rispetto al 32 per cento sotto placebo, più comunemente nausea.","nello studio combinato di fase 1b con quantità crescenti di cagrilintide insieme a semaglutide, gli effetti gastrointestinali sono stati descritti come la categoria di evento avverso più frequente, con un profilo di sicurezza complessivamente gestibile.","Come agonista del recettore dell'amilina, è stata descritta una riduzione dello svuotamento gastrico, un meccanismo che contribuisce anche agli effetti gastrointestinali con i composti GLP-1.","Poiché cagrilintide non è approvato come farmaco da solo in nessun luogo, non esistono informazioni ufficiali per la prescrizione sulla sicurezza a lungo termine."],"sicherheit_en":["nello studio randomizzato di fase 2 con cagrilintide come unica sostanza, gli effetti gastrointestinali si sono verificati nel 41 al 63 per cento dei partecipanti, rispetto al 32 per cento sotto placebo, più comunemente nausea.","nello studio combinato di fase 1b con quantità crescenti di cagrilintide insieme a semaglutide, gli effetti gastrointestinali sono stati descritti come la categoria di evento avverso più frequente, con un profilo di sicurezza complessivamente gestibile.","Come agonista del recettore dell'amilina, è stata descritta una riduzione dello svuotamento gastrico, un meccanismo che contribuisce anche agli effetti gastrointestinali con i composti GLP-1.","Poiché cagrilintide non è approvato come farmaco da solo in nessun luogo, non esistono informazioni ufficiali per la prescrizione sulla sicurezza a lungo termine."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Cagrilintide è attualmente in studi di fase 3 sia come sostanza da sola che in combinazione fissa con semaglutide sotto il nome CagriSema, e non è ancora stato approvato come farmaco nell'UE o negli Stati Uniti. A dicembre 2025, è stata presentata una nuova domanda di farmaco per la combinazione CagriSema alla FDA degli Stati Uniti, con una decisione attesa nel 2026. Cagrilintide è venduto esclusivamente come principio chimico di ricerca.","rechtsstatus_en":"Cagrilintide è attualmente in studi di fase 3 sia come sostanza da sola che in combinazione fissa con semaglutide sotto il nome CagriSema, e non è ancora stato approvato come farmaco nell'UE o negli Stati Uniti. A dicembre 2025, è stata presentata una nuova domanda di farmaco per la combinazione CagriSema alla FDA degli Stati Uniti, con una decisione attesa nel 2026. Cagrilintide è venduto esclusivamente come principio chimico di ricerca.","typischeMg":[5,10],"faq":[{"q":"Cagrilintide è già disponibile come farmaco?","a":"No. Cagrilintide è in fase di studio come sostanza da sola e nella combinazione CagriSema in studi di fase 3. È in corso un processo di approvazione FDA per CagriSema dal dicembre 2025. Cagrilintide non è attualmente un farmaco approvato.","q_en":"Cagrilintide è già disponibile come farmaco?","a_en":"No. Cagrilintide è in fase di studio come sostanza da sola e nella combinazione CagriSema in studi di fase 3. È in corso un processo di approvazione FDA per CagriSema dal dicembre 2025. Cagrilintide non è attualmente un farmaco approvato."},{"q":"Cosa distingue cagrilintide da semaglutide?","a":"Semaglutide agisce sul recettore del GLP-1, mentre cagrilintide agisce sui recettori dell'amilina nel cervello. Entrambi i composti sono studiati anche come combinazione fissa chiamata CagriSema, che ha mostrato un effetto maggiore sul peso corporeo negli studi rispetto a ciascuna sostanza da sola.","q_en":"Cosa distingue cagrilintide da semaglutide?","a_en":"Semaglutide agisce sul recettore del GLP-1, mentre cagrilintide agisce sui recettori dell'amilina nel cervello. Entrambi i composti sono studiati anche come combinazione fissa chiamata CagriSema, che ha mostrato un effetto maggiore sul peso corporeo negli studi rispetto a ciascuna sostanza da sola."},{"q":"Da dove proviene cagrilintide?","a":"Cagrilintide è stato sviluppato dalla società farmaceutica Novo Nordisk, che ha anche sviluppato semaglutide. Viene citato sotto le brevi designazioni AM833 e NN9838 negli studi clinici, incluso il programma di studi REDEFINE.","q_en":"Da dove proviene cagrilintide?","a_en":"Cagrilintide è stato sviluppato dalla società farmaceutica Novo Nordisk, che ha anche sviluppato semaglutide. Viene citato sotto le brevi designazioni AM833 e NN9838 negli studi clinici, incluso il programma di studi REDEFINE."}],"seo":{"title":"Cagrilintide: Analogo dell'amilina in studi di fase 3","title_en":"Cagrilintide: Analogo dell'amilina in studi di fase 3","description":"Cagrilintide in sintesi: meccanismo, stato dello studio e profilo di sicurezza dell'analogo dell'amilina, studiato da solo e nella combinazione CagriSema.","description_en":"Cagrilintide in sintesi: meccanismo, stato dello studio e profilo di sicurezza dell'analogo dell'amilina, studiato da solo e nella combinazione CagriSema."},"demo":false,"steckbrief":{"cas":"1415456-99-3","molekulargewicht":"4409 g/mol","aminosaeuren":37,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":37,"quellen":["PubChem CID 171397054","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)"},"verwandt":["semaglutid","tirzepatid","retatrutid","survodutid"]},{"slug":"mots-c","name":"MOTS-c","synonyme":["Peptide Derivato Mitocondriale MOTS-c","Frame di Lettura Aperto Mitocondriale dell'rRNA 12S Tipo-c"],"kategorie":"Stoffwechsel","studienlage":"frühe klinische Studien","kurz":"Un peptide codificato mitocondrialmente studiato come mimico dell'esercizio nella ricerca metabolica.","kurz_en":"Un peptide codificato mitocondrialmente studiato come mimico dell'esercizio nella ricerca metabolica.","beschreibung":"MOTS-c è un peptide a 16 amminoacidi codificato direttamente nel DNA mitocondriale piuttosto che nel nucleo cellulare. È stato scoperto nel 2015 e viene studiato come molecola di segnalazione endogena rilasciata in quantità maggiori durante lo sforzo fisico. La ricerca si concentra sugli effetti possibili sulla sensibilità all'insulina, sul metabolismo dei grassi e sull'invecchiamento cellulare.","beschreibung_en":"MOTS-c è un peptide a 16 amminoacidi codificato direttamente nel DNA mitocondriale piuttosto che nel nucleo cellulare. È stato scoperto nel 2015 e viene studiato come molecola di segnalazione endogena rilasciata in quantità maggiori durante lo sforzo fisico. La ricerca si concentra sugli effetti possibili sulla sensibilità all'insulina, sul metabolismo dei grassi e sull'invecchiamento cellulare.","mechanismus":"MOTS-c inibisce il ciclo della folato della cellula, causando l'accumulo e l'attivazione del sensore energetico centrale AMPK, AICAR come molecola messaggera. Questa via stimola, tra l'altro, l'assorbimento di glucosio nelle cellule muscolari e l'ossidazione degli acidi grassi. Sotto stress metabolico, MOTS-c si sposta anche nel nucleo della cellula, dove influenza l'espressione dei geni coinvolti nell'adattamento allo stress.","mechanismus_en":"MOTS-c inibisce il ciclo della folato della cellula, causando l'accumulo e l'attivazione del sensore energetico centrale AMPK, AICAR come molecola messaggera. Questa via stimola, tra l'altro, l'assorbimento di glucosio nelle cellule muscolari e l'ossidazione degli acidi grassi. Sotto stress metabolico, MOTS-c si sposta anche nel nucleo della cellula, dove influenza l'espressione dei geni coinvolti nell'adattamento allo stress.","evidenz":[{"art":"preclinico","kurz":"Nella descrizione originale, MOTS-c ha impedito lo sviluppo della resistenza all'insulina nei topi su dieta ricca di grassi per diverse settimane e ha ripristinato la sensibilità all'insulina degli animali giovani nei topi anziani.","kurz_en":"Nella descrizione originale, MOTS-c ha impedito lo sviluppo della resistenza all'insulina nei topi su dieta ricca di grassi per diverse settimane e ha ripristinato la sensibilità all'insulina degli animali giovani nei topi anziani.","quelle":"Lee et al. 2015, Cell Metabolism 21(3):443-454"},{"art":"preclinico","kurz":"Nei topi più anziani, l'somministrazione ripetuta di MOTS-c per diverse settimane ha prolungato l'aspettativa di vita mediana del 5 al 7 per cento e migliorato l'endurance, la forza di presa e l'equilibrio rispetto al placebo.","kurz_en":"Nei topi più anziani, l'somministrazione ripetuta di MOTS-c per diverse settimane ha prolungato l'aspettativa di vita mediana del 5 al 7 per cento e migliorato l'endurance, la forza di presa e l'equilibrio rispetto al placebo.","quelle":"Reynolds et al. 2021, Nature Communications, DOI 10.1038/s41467-020-20790-0"},{"art":"clinico","kurz":"In uno studio osservazionale di 20 adulti fisicamente attivi, i livelli sierici di MOTS-c erano correlati positivamente con la potenza di salto, la forza massima e la massa muscolare delle gambe, ma non con il consumo massimo di ossigeno.","kurz_en":"In uno studio osservazionale di 20 adulti fisicamente attivi, i livelli sierici di MOTS-c erano correlati positivamente con la potenza di salto, la forza massima e la massa muscolare delle gambe, ma non con il consumo massimo di ossigeno.","quelle":"Domin et al. 2023, International Journal of Molecular Sciences"}],"sicherheit":["Studi sugli animali pubblicati fino a sei mesi hanno riportato nessun effetto collaterale rilevante.","L'effetto più comunemente riportato è una reazione nel sito di iniezione locale come bruciore e rossore.","MOTS-c inibisce il ciclo della folato; una possibile carenza di folato con un uso più lungo è finora stata descritta solo teoricamente.","Gli studi clinici controllati sull'efficacia e la sicurezza umana non sono ancora disponibili."],"sicherheit_en":["Studi sugli animali pubblicati fino a sei mesi hanno riportato nessun effetto collaterale rilevante.","L'effetto più comunemente riportato è una reazione nel sito di iniezione locale come bruciore e rossore.","MOTS-c inibisce il ciclo della folato; una possibile carenza di folato con un uso più lungo è finora stata descritta solo teoricamente.","Gli studi clinici controllati sull'efficacia e la sicurezza umana non sono ancora disponibili."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"MOTS-c non è approvato come farmaco o prodotto alimentare né nell'UE né negli Stati Uniti. Viene venduto esclusivamente come sostanza chimica di ricerca e non è destinato all'uso umano.","rechtsstatus_en":"MOTS-c non è approvato come farmaco o prodotto alimentare né nell'UE né negli Stati Uniti. Viene venduto esclusivamente come sostanza chimica di ricerca e non è destinato all'uso umano.","typischeMg":[5,10],"faq":[{"q":"Cosa rende MOTS-c diverso dagli altri peptidi","a":"MOTS-c è codificato direttamente nel DNA mitocondriale piuttosto che nel nucleo della cellula. Agisce attraverso il sensore energetico cellulare AMPK e pertanto è classificato come mimetico dell'esercizio.","q_en":"Cosa rende MOTS-c diverso dagli altri peptidi","a_en":"MOTS-c è codificato direttamente nel DNA mitocondriale piuttosto che nel nucleo della cellula. Agisce attraverso il sensore energetico cellulare AMPK e pertanto è classificato come mimetico dell'esercizio."},{"q":"MOTS-c è un farmaco approvato","a":"No. MOTS-c non è approvato come farmaco o prodotto alimentare né nell'UE né negli Stati Uniti ed è venduto esclusivamente come sostanza chimica di ricerca.","q_en":"MOTS-c è un farmaco approvato","a_en":"No. MOTS-c non è approvato come farmaco o prodotto alimentare né nell'UE né negli Stati Uniti ed è venduto esclusivamente come sostanza chimica di ricerca."},{"q":"Quanto sono solide i dati umani su MOTS-c","a":"Limitati finora. Le evidenze consistono principalmente in studi preclinici su animali e uno studio osservazionale umano sulla correlazione con la forza muscolare; gli studi clinici controllati sull'uomo sono ancora mancanti.","q_en":"Quanto sono solide i dati umani su MOTS-c","a_en":"Limitati finora. Le evidenze consistono principalmente in studi preclinici su animali e uno studio osservazionale umano sulla correlazione con la forza muscolare; gli studi clinici controllati sull'uomo sono ancora mancanti."}],"seo":{"title":"Panoramica della ricerca su MOTS-c","title_en":"Panoramica della ricerca su MOTS-c","description":"MOTS-c spiegato fattualmente: meccanismo d'azione mitocondriale, dati di studi preclinici e clinici, e stato legale del peptide.","description_en":"MOTS-c spiegato fattualmente: meccanismo d'azione mitocondriale, dati di studi preclinici e clinici, e stato legale del peptide."},"demo":false,"steckbrief":{"cas":"1627580-64-6","molekulargewicht":"2174,6 g/mol","aminosaeuren":16,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":16,"quellen":["PubChem CID 146675088","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)"},"verwandt":["semaglutid","ss-31","aod-9604","5-amino-1mq"]},{"slug":"retatrutid","name":"Retatrutide","synonyme":["LY3437943"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Un peptide che agisce simultaneamente sui recettori GLP-1, GIP e glucagone, attualmente in studi clinici avanzati relativi alla regolazione metabolica.","kurz_en":"Un peptide che agisce simultaneamente sui recettori GLP-1, GIP e glucagone, attualmente in studi clinici avanzati relativi alla regolazione metabolica.","beschreibung":"Retatrutide è un cosiddetto triplo agonista che agisce simultaneamente su tre recettori metabolici: GLP-1, GIP e glucagone. Attualmente è in studi di fase 3 e non è approvato come farmaco in nessun paese a oggi.","beschreibung_en":"Retatrutide è un cosiddetto triplo agonista che agisce simultaneamente su tre recettori metabolici: GLP-1, GIP e glucagone. Attualmente è in studi di fase 3 e non è approvato come farmaco in nessun paese a oggi.","mechanismus":"Attraverso il recettore GLP-1 sono stati descritti effetti sulla regolazione della sazietà e un rallentamento dello svuotamento gastrico. Il recettore GIP è stato associato a una maggiore secrezione di insulina e a un possibile effetto tampone sugli effetti gastrointestinali. L'azione aggiuntiva sul recettore del glucagone è stata associata a un aumento della spesa energetica epatica e all'attivazione del tessuto adiposo bruno.","mechanismus_en":"Attraverso il recettore GLP-1 sono stati descritti effetti sulla regolazione della sazietà e un rallentamento dello svuotamento gastrico. Il recettore GIP è stato associato a una maggiore secrezione di insulina e a un possibile effetto tampone sugli effetti gastrointestinali. L'azione aggiuntiva sul recettore del glucagone è stata associata a un aumento della spesa energetica epatica e all'attivazione del tessuto adiposo bruno.","evidenz":[{"art":"clinico","kurz":"In uno studio randomizzato di fase 2 in adulti con obesità, una proporzione marcatamente maggiore di partecipanti su retatrutide ha raggiunto una perdita di peso corporeo rilevante dopo 48 settimane rispetto al placebo.","kurz_en":"In uno studio randomizzato di fase 2 in adulti con obesità, una proporzione marcatamente maggiore di partecipanti su retatrutide ha raggiunto una perdita di peso corporeo rilevante dopo 48 settimane rispetto al placebo.","quelle":"Jastreboff AM et al. 2023, New England Journal of Medicine 389:514-526, PMID 37366315"},{"art":"clinico","kurz":"In uno studio di sottogruppo con partecipanti con malattia epatica grassa concomitante, è stata osservata una riduzione misurata con RMN del contenuto di grasso epatico che aumentava con la quantità somministrata dopo 24 settimane.","kurz_en":"In uno studio di sottogruppo con partecipanti con malattia epatica grassa concomitante, è stata osservata una riduzione misurata con RMN del contenuto di grasso epatico che aumentava con la quantità somministrata dopo 24 settimane.","quelle":"Sanyal AJ et al. 2024, Nature Medicine"},{"art":"clinico","kurz":"In uno studio di fase 2 in persone con diabete di tipo 2, retatrutide ha abbassato l'HbA1c più del comparatore attivo dulaglutide, insieme a una maggiore perdita di peso corporeo.","kurz_en":"In uno studio di fase 2 in persone con diabete di tipo 2, retatrutide ha abbassato l'HbA1c più del comparatore attivo dulaglutide, insieme a una maggiore perdita di peso corporeo.","quelle":"Rosenstock J et al. 2023, The Lancet 402:529-544, PMID 37385280"}],"sicherheit":["Gli effetti più comunemente riportati negli studi sono gastrointestinali, inclusi nausea e diarrea, e diminuiscono nel corso degli studi.","Alla quantità più alta, gli studi hanno osservato un tasso di interruzione più elevato rispetto al placebo.","In uno studio di fase 3, alcuni partecipanti del gruppo con la quantità più alta hanno riportato disestesia (formicolio o intorpidimento alle estremità), che si è risolta in gran parte nel corso dello studio.","Poiché retatrutide non è approvato come farmaco da nessuna parte, non esistono informazioni ufficiali per la prescrizione sulla sicurezza a lungo termine."],"sicherheit_en":["Gli effetti più comunemente riportati negli studi sono gastrointestinali, inclusi nausea e diarrea, e diminuiscono nel corso degli studi.","Alla quantità più alta, gli studi hanno osservato un tasso di interruzione più elevato rispetto al placebo.","In uno studio di fase 3, alcuni partecipanti del gruppo con la quantità più alta hanno riportato disestesia (formicolio o intorpidimento alle estremità), che si è risolta in gran parte nel corso dello studio.","Poiché retatrutide non è approvato come farmaco da nessuna parte, non esistono informazioni ufficiali per la prescrizione sulla sicurezza a lungo termine."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Retatrutide è attualmente in studi di fase 3 e non è ancora approvato come farmaco nell'UE o negli Stati Uniti. Viene venduto esclusivamente come sostanza chimica per la ricerca.","rechtsstatus_en":"Retatrutide è attualmente in studi di fase 3 e non è ancora approvato come farmaco nell'UE o negli Stati Uniti. Viene venduto esclusivamente come sostanza chimica per la ricerca.","typischeMg":[5,10,15],"faq":[{"q":"Retatrutide è già disponibile come farmaco?","a":"No. Retatrutide è attualmente in studi di fase 3; secondo il produttore, l’approvazione non è prevista prima del 2027. Al momento non è un medicinale autorizzato.","q_en":"Retatrutide è già disponibile come farmaco?","a_en":"No. Retatrutide è attualmente in studi di fase 3; secondo il produttore, l’approvazione non è prevista prima del 2027. Al momento non è un medicinale autorizzato."},{"q":"Cosa distingue retatrutide da semaglutide?","a":"Semaglutide agisce solo sul recettore GLP-1, mentre retatrutide agisce in aggiunta sui recettori GIP e glucagone. Gli studi clinici hanno mostrato un effetto maggiore sul peso corporeo e sul grasso epatico come risultato.","q_en":"Cosa distingue retatrutide da semaglutide?","a_en":"Semaglutide agisce solo sul recettore GLP-1, mentre retatrutide agisce in aggiunta sui recettori GIP e glucagone. Gli studi clinici hanno mostrato un effetto maggiore sul peso corporeo e sul grasso epatico come risultato."},{"q":"Da dove proviene retatrutide?","a":"Retatrutide è stato sviluppato dalla società farmaceutica Eli Lilly e viene studiato in diversi studi di fase 3 sotto il nome del programma TRIUMPH.","q_en":"Da dove proviene retatrutide?","a_en":"Retatrutide è stato sviluppato dalla società farmaceutica Eli Lilly e viene studiato in diversi studi di fase 3 sotto il nome del programma TRIUMPH."}],"seo":{"title":"Retatrutide: Agonista Triplo in Studi di Fase 3","title_en":"Retatrutide: Agonista Triplo in Studi di Fase 3","description":"Retatrutide in sintesi: meccanismo, stato dello studio e profilo di sicurezza dell'agonista triplo GLP-1/GIP/glucagone negli studi clinici avanzati.","description_en":"Retatrutide in sintesi: meccanismo, stato dello studio e profilo di sicurezza dell'agonista triplo GLP-1/GIP/glucagone negli studi clinici avanzati."},"demo":false,"steckbrief":{"cas":"2381989-03-1","molekulargewicht":"~4600 g/mol","aminosaeuren":39,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":"solubile in acqua sterile o acqua batteriostatica","sequenzLaenge":39,"quellen":["chemverify Katalog 14.09.2026 (PubChem: kein Eintrag)"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit_en":"solubile in acqua sterile o acqua batteriostatica"},"verwandt":["semaglutid","tirzepatid","cagrilintid","survodutid"]},{"slug":"semaglutid","name":"Semaglutide","synonyme":[],"kategorie":"Stoffwechsel","studienlage":"zugelassenes Arzneimittel","kurz":"Un agonista del recettore GLP-1, noto come farmaco approvato ed elencato qui come sostanza di ricerca per la regolazione metabolica.","kurz_en":"Un agonista del recettore GLP-1, noto come farmaco approvato ed elencato qui come sostanza di ricerca per la regolazione metabolica.","beschreibung":"Semaglutide è un agonista del recettore GLP-1 approvato come farmaco sotto diversi nomi commerciali. È oggetto di estesi studi clinici sulla regolazione del metabolismo e della sazietà. I lotti di ricerca elencati qui non sono equivalenti ai farmaci approvati e sono destinati all'uso in laboratorio solamente.","beschreibung_en":"Semaglutide è un agonista del recettore GLP-1 approvato come farmaco sotto diversi nomi commerciali. È oggetto di estesi studi clinici sulla regolazione del metabolismo e della sazietà. I lotti di ricerca elencati qui non sono equivalenti ai farmaci approvati e sono destinati all'uso in laboratorio solamente.","mechanismus":"Semaglutide attiva il recettore GLP-1, che influenza la regolazione della fame nell'ipotalamo, rallenta lo svuotamento gastrico e stimola il rilascio di insulina in modo dipendente dal glucosio. Questa azione dipendente dal glucosio è descritta come il motivo del rischio inferiore di ipoglicemia rispetto all'insulina.","mechanismus_en":"Semaglutide attiva il recettore GLP-1, che influenza la regolazione della fame nell'ipotalamo, rallenta lo svuotamento gastrico e stimola il rilascio di insulina in modo dipendente dal glucosio. Questa azione dipendente dal glucosio è descritta come il motivo del rischio inferiore di ipoglicemia rispetto all'insulina.","evidenz":[{"art":"clinico","kurz":"In uno studio randomizzato con 1.961 adulti con sovrappeso o obesità, la somministrazione settimanale di semaglutide per 68 settimane ha portato a una perdita media di peso corporeo del 14,9 per cento rispetto al 2,4 per cento nel gruppo placebo.","kurz_en":"In uno studio randomizzato con 1.961 adulti con sovrappeso o obesità, la somministrazione settimanale di semaglutide per 68 settimane ha portato a una perdita media di peso corporeo del 14,9 per cento rispetto al 2,4 per cento nel gruppo placebo.","quelle":"Wilding JPH et al. 2021, New England Journal of Medicine, PMID 33567185"},{"art":"clinico","kurz":"In uno studio sugli esiti cardiovascolari su 3.297 persone con diabete di tipo 2 ed elevato rischio cardiovascolare, semaglutide è stato associato a una frequenza inferiore del 26 % di eventi cardiovascolari maggiori rispetto al placebo.","kurz_en":"In uno studio sugli esiti cardiovascolari su 3.297 persone con diabete di tipo 2 ed elevato rischio cardiovascolare, semaglutide è stato associato a una frequenza inferiore del 26 % di eventi cardiovascolari maggiori rispetto al placebo.","quelle":"Marso SP et al. 2016, New England Journal of Medicine 375:1834-1844, PMID 27633186"}],"sicherheit":["Gli effetti comunemente riportati sono gastrointestinali, in particolare nausea, diarrea e vomito, prevalentemente transitori durante il corso dell'uso.","I casi rari discussi nella letteratura includono un possibile legame con neuropatia ottica ischemica anteriore non arteritica.","Secondo le informazioni per la prescrizione, l'uso è controindicato in persone con storia personale o familiare di carcinoma tiroideo medullare."],"sicherheit_en":["Gli effetti comunemente riportati sono gastrointestinali, in particolare nausea, diarrea e vomito, prevalentemente transitori durante il corso dell'uso.","I casi rari discussi nella letteratura includono un possibile legame con neuropatia ottica ischemica anteriore non arteritica.","Secondo le informazioni per la prescrizione, l'uso è controindicato in persone con storia personale o familiare di carcinoma tiroideo medullare."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Semaglutide è approvato come farmaco con i nomi Ozempic, Wegovy e Rybelsus nell'UE e negli Stati Uniti per il trattamento del diabete di tipo 2 e per la gestione del peso, ed è disponibile solo su prescrizione. I lotti di ricerca descritti qui non sono equivalenti ai prodotti farmaceutici finiti approvati.","rechtsstatus_en":"Semaglutide è approvato come farmaco con i nomi Ozempic, Wegovy e Rybelsus nell'UE e negli Stati Uniti per il trattamento del diabete di tipo 2 e per la gestione del peso, ed è disponibile solo su prescrizione. I lotti di ricerca descritti qui non sono equivalenti ai prodotti farmaceutici finiti approvati.","typischeMg":[2,5],"faq":[{"q":"Semaglutide è un farmaco approvato?","a":"Sì, il semaglutide è approvato come farmaco su prescrizione con i nomi Ozempic, Wegovy e Rybelsus. La sostanza descritta qui è un lotto di ricerca solo, non un prodotto farmaceutico finito.","q_en":"Semaglutide è un farmaco approvato?","a_en":"Sì, il semaglutide è approvato come farmaco su prescrizione con i nomi Ozempic, Wegovy e Rybelsus. La sostanza descritta qui è un lotto di ricerca solo, non un prodotto farmaceutico finito."},{"q":"Come si differenzia il semaglutide dal retatrutide?","a":"Il semaglutide agisce solo sul recettore GLP-1, mentre il retatrutide agisce in aggiunta sui recettori GIP e glucagone. Il retatrutide è ancora in fase 3 di studi clinici, mentre il semaglutide è già approvato.","q_en":"Come si differenzia il semaglutide dal retatrutide?","a_en":"Il semaglutide agisce solo sul recettore GLP-1, mentre il retatrutide agisce in aggiunta sui recettori GIP e glucagone. Il retatrutide è ancora in fase 3 di studi clinici, mentre il semaglutide è già approvato."},{"q":"A cosa serve il semaglutide come farmaco?","a":"Come farmaco approvato, il semaglutide è prescritto per il diabete di tipo 2 e la gestione del peso. Questa pagina descrive la sostanza esclusivamente come un composto di ricerca per scopi di laboratorio.","q_en":"A cosa serve il semaglutide come farmaco?","a_en":"Come farmaco approvato, il semaglutide è prescritto per il diabete di tipo 2 e la gestione del peso. Questa pagina descrive la sostanza esclusivamente come un composto di ricerca per scopi di laboratorio."}],"seo":{"title":"Semaglutide: Composto GLP-1 in un Contesto di Ricerca","title_en":"Semaglutide: Composto GLP-1 in un Contesto di Ricerca","description":"Semaglutide in sintesi: meccanismo, stato dello studio, profilo di sicurezza e stato legale dell'agonista del recettore GLP-1 approvato.","description_en":"Semaglutide in sintesi: meccanismo, stato dello studio, profilo di sicurezza e stato legale dell'agonista del recettore GLP-1 approvato."},"demo":false,"steckbrief":{"cas":"910463-68-2","molekulargewicht":"4114 g/mol","aminosaeuren":31,"halbwertszeit":"≈ 1 settimana (eliminazione, informazioni di prescrizione Ozempic)","reinheitsstandard":"≥ 99 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":31,"quellen":["PubChem CID 56843331","DailyMed SPL OZEMPIC (Semaglutid), Novo Nordisk","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 1 settimana (eliminazione, informazioni di prescrizione Ozempic)","reinheitsstandard_en":"≥ 99 % (HPLC, standard commerciale)"},"verwandt":["tirzepatid","retatrutid","survodutid","cagrilintid"]},{"slug":"survodutid","name":"Survodutide","synonyme":["BI 456906"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Un peptide che agisce simultaneamente sui recettori GLP-1 e glucagone, attualmente in studi clinici avanzati relativi alla regolazione metabolica.","kurz_en":"Un peptide che agisce simultaneamente sui recettori GLP-1 e glucagone, attualmente in studi clinici avanzati relativi alla regolazione metabolica.","beschreibung":"Survodutide è un agonista duale dei recettori GLP-1 e glucagone, sviluppato da Boehringer Ingelheim in collaborazione con Zealand Pharma. Viene studiato in studi clinici di fase 3 per la regolazione del peso nell'obesità così come nella steatoepatite associata a disfunzione metabolica (MASH), e non è approvato come farmaco in alcun paese ad oggi.","beschreibung_en":"Survodutide è un agonista duale dei recettori GLP-1 e glucagone, sviluppato da Boehringer Ingelheim in collaborazione con Zealand Pharma. Viene studiato in studi clinici di fase 3 per la regolazione del peso nell'obesità così come nella steatoepatite associata a disfunzione metabolica (MASH), e non è approvato come farmaco in alcun paese ad oggi.","mechanismus":"Attraverso il recettore GLP-1 sono stati descritti un aumento della sazietà e un rallentamento dello svuotamento gastrico. L'attivazione aggiuntiva del recettore del glucagone è stata collegata a un aumento della spesa energetica epatica e a una riduzione del contenuto di grasso epatico. Questa duplice azione distingue survodutide dagli agonisti puri del GLP-1.","mechanismus_en":"Attraverso il recettore GLP-1 sono stati descritti un aumento della sazietà e un rallentamento dello svuotamento gastrico. L'attivazione aggiuntiva del recettore del glucagone è stata collegata a un aumento della spesa energetica epatica e a una riduzione del contenuto di grasso epatico. Questa duplice azione distingue survodutide dagli agonisti puri del GLP-1.","evidenz":[{"art":"clinico","kurz":"In uno studio randomizzato di fase 3 con 725 adulti con obesità senza diabete, survodutide ha portato a una perdita media di peso corporeo del 12 al 13 per cento dopo 76 settimane, rispetto al 5 per cento sotto placebo.","kurz_en":"In uno studio randomizzato di fase 3 con 725 adulti con obesità senza diabete, survodutide ha portato a una perdita media di peso corporeo del 12 al 13 per cento dopo 76 settimane, rispetto al 5 per cento sotto placebo.","quelle":"Le Roux CW et al. 2026, New England Journal of Medicine, DOI 10.1056/NEJMoa2600751"},{"art":"clinico","kurz":"In uno studio randomizzato di fase 2 con 386 adulti con obesità, survodutide ha portato a una perdita di peso corporeo fino al 14,9 per cento nel gruppo con la quantità più alta dopo 46 settimane, rispetto al 2,8 per cento sotto placebo.","kurz_en":"In uno studio randomizzato di fase 2 con 386 adulti con obesità, survodutide ha portato a una perdita di peso corporeo fino al 14,9 per cento nel gruppo con la quantità più alta dopo 46 settimane, rispetto al 2,8 per cento sotto placebo.","quelle":"le Roux CW et al. 2024, The Lancet Diabetes & Endocrinology 12:162-173, PMID 38330987"},{"art":"clinico","kurz":"In uno studio di fase 2 con 293 persone con MASH e fibrosi epatica, fino al 62 per cento dei partecipanti in trattamento con survodutide ha mostrato un miglioramento istologico di MASH senza peggioramento della fibrosi dopo 48 settimane, rispetto al 14 per cento sotto placebo.","kurz_en":"In uno studio di fase 2 con 293 persone con MASH e fibrosi epatica, fino al 62 per cento dei partecipanti in trattamento con survodutide ha mostrato un miglioramento istologico di MASH senza peggioramento della fibrosi dopo 48 settimane, rispetto al 14 per cento sotto placebo.","quelle":"Sanyal AJ et al. 2024, New England Journal of Medicine, PMID 38847460"}],"sicherheit":["Gli effetti più comunemente riportati negli studi sono gastrointestinali, inclusi nausea, diarrea e vomito, che si verificano in modo marcatamente più frequente con survodutide che sotto placebo.","nello studio di obesità di fase 3, sono stati riportati sintomi gastrointestinali in fino al 90 per cento dei partecipanti in trattamento con survodutide rispetto al 48 per cento sotto placebo, prevalentemente lievi a moderati.","nello studio di MASH di fase 2, sono stati registrati eventi avversi gravi nel 8 per cento dei partecipanti in trattamento con survodutide e nel 7 per cento sotto placebo.","Poiché survodutide non è approvato come farmaco da nessuna parte, non esistono informazioni ufficiali per la prescrizione sulla sicurezza a lungo termine."],"sicherheit_en":["Gli effetti più comunemente riportati negli studi sono gastrointestinali, inclusi nausea, diarrea e vomito, che si verificano in modo marcatamente più frequente con survodutide che sotto placebo.","nello studio di obesità di fase 3, sono stati riportati sintomi gastrointestinali in fino al 90 per cento dei partecipanti in trattamento con survodutide rispetto al 48 per cento sotto placebo, prevalentemente lievi a moderati.","nello studio di MASH di fase 2, sono stati registrati eventi avversi gravi nel 8 per cento dei partecipanti in trattamento con survodutide e nel 7 per cento sotto placebo.","Poiché survodutide non è approvato come farmaco da nessuna parte, non esistono informazioni ufficiali per la prescrizione sulla sicurezza a lungo termine."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Survodutide è attualmente in studi di fase 3 per obesità e MASH e non è ancora stato approvato come medicinale nell’UE né negli Stati Uniti. Secondo il produttore, l’approvazione della FDA non è prevista prima del 2027; viene venduto esclusivamente come sostanza chimica per la ricerca.","rechtsstatus_en":"Survodutide è attualmente in studi di fase 3 per obesità e MASH e non è ancora stato approvato come medicinale nell’UE né negli Stati Uniti. Secondo il produttore, l’approvazione della FDA non è prevista prima del 2027; viene venduto esclusivamente come sostanza chimica per la ricerca.","typischeMg":[5,10,20],"faq":[{"q":"Survodutide è già disponibile come farmaco?","a":"No. Survodutide è attualmente in studi di fase 3; secondo il produttore, l’approvazione della FDA non è prevista prima del 2027. Al momento non è un medicinale autorizzato.","q_en":"Survodutide è già disponibile come farmaco?","a_en":"No. Survodutide è attualmente in studi di fase 3; secondo il produttore, l’approvazione della FDA non è prevista prima del 2027. Al momento non è un medicinale autorizzato."},{"q":"Cosa distingue survodutide da semaglutide?","a":"Semaglutide agisce solo sul recettore GLP-1, mentre survodutide agisce in aggiunta sul recettore del glucagone. Gli studi clinici hanno mostrato che questa azione duale riduce anche il contenuto di grasso epatico insieme all'effetto sul peso corporeo.","q_en":"Cosa distingue survodutide da semaglutide?","a_en":"Semaglutide agisce solo sul recettore GLP-1, mentre survodutide agisce in aggiunta sul recettore del glucagone. Gli studi clinici hanno mostrato che questa azione duale riduce anche il contenuto di grasso epatico insieme all'effetto sul peso corporeo."},{"q":"Da dove proviene survodutide?","a":"Survodutide è stato sviluppato dalla società farmaceutica Boehringer Ingelheim e viene studiato in diversi studi di fase 3 sotto il nome del programma SYNCHRONIZE, in parte in collaborazione con Zealand Pharma.","q_en":"Da dove proviene survodutide?","a_en":"Survodutide è stato sviluppato dalla società farmaceutica Boehringer Ingelheim e viene studiato in diversi studi di fase 3 sotto il nome del programma SYNCHRONIZE, in parte in collaborazione con Zealand Pharma."}],"seo":{"title":"Survodutide: Agonista Duale in Studi di Fase 3","title_en":"Survodutide: Agonista Duale in Studi di Fase 3","description":"Survodutide in sintesi: meccanismo, stato dello studio e profilo di sicurezza dell'agonista duale GLP-1/glucagone negli studi clinici avanzati.","description_en":"Survodutide in sintesi: meccanismo, stato dello studio e profilo di sicurezza dell'agonista duale GLP-1/glucagone negli studi clinici avanzati."},"demo":false,"steckbrief":{"cas":"2805997-46-8","molekulargewicht":"4232 g/mol","aminosaeuren":null,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":null,"quellen":["PubChem CID 171378821","chemverify Katalog 14.09.2026 (Aminosäurenzahl/Reinheitsstandard dort nicht geführt)"]},"verwandt":["semaglutid","tirzepatid","retatrutid","cagrilintid"]},{"slug":"tirzepatid","name":"Tirzepatide","synonyme":["LY3298176"],"kategorie":"Stoffwechsel","studienlage":"zugelassenes Arzneimittel","kurz":"Un agonista duale dei recettori GIP/GLP-1, noto come farmaco approvato e elencato qui come sostanza di ricerca per la regolazione metabolica.","kurz_en":"Un agonista duale dei recettori GIP/GLP-1, noto come farmaco approvato e elencato qui come sostanza di ricerca per la regolazione metabolica.","beschreibung":"Tirzepatide è un agonista duale dei recettori GIP/GLP-1 approvato come farmaco con i nomi Mounjaro e Zepbound. È oggetto di estesi studi clinici sulla regolazione del metabolismo e del peso nel diabete di tipo 2 e nell'obesità. I lotti di ricerca elencati qui non sono equivalenti ai farmaci approvati e sono destinati all'uso in laboratorio solamente.","beschreibung_en":"Tirzepatide è un agonista duale dei recettori GIP/GLP-1 approvato come farmaco con i nomi Mounjaro e Zepbound. È oggetto di estesi studi clinici sulla regolazione del metabolismo e del peso nel diabete di tipo 2 e nell'obesità. I lotti di ricerca elencati qui non sono equivalenti ai farmaci approvati e sono destinati all'uso in laboratorio solamente.","mechanismus":"Tirzepatide attiva simultaneamente sia il recettore GIP che il recettore GLP-1, motivo per cui è descritto come agonista duale. Attraverso il recettore GLP-1 sono stati descritti effetti sulla regolazione della sazietà nell'ipotalamo, rallentamento dello svuotamento gastrico e rilascio di insulina dipendente dal glucosio. Il componente aggiuntivo del recettore GIP è stato collegato a un aumento della secrezione di insulina ed effetti sul metabolismo lipidico.","mechanismus_en":"Tirzepatide attiva simultaneamente sia il recettore GIP che il recettore GLP-1, motivo per cui è descritto come agonista duale. Attraverso il recettore GLP-1 sono stati descritti effetti sulla regolazione della sazietà nell'ipotalamo, rallentamento dello svuotamento gastrico e rilascio di insulina dipendente dal glucosio. Il componente aggiuntivo del recettore GIP è stato collegato a un aumento della secrezione di insulina ed effetti sul metabolismo lipidico.","evidenz":[{"art":"clinico","kurz":"In uno studio randomizzato con 2.539 adulti con obesità o sovrappeso, tirzepatide settimanale per 72 settimane ha portato a una perdita media di peso corporeo fino al 20,9 per cento (15 mg) rispetto al 3,1 per cento in condizioni placebo.","kurz_en":"In uno studio randomizzato con 2.539 adulti con obesità o sovrappeso, tirzepatide settimanale per 72 settimane ha portato a una perdita media di peso corporeo fino al 20,9 per cento (15 mg) rispetto al 3,1 per cento in condizioni placebo.","quelle":"Jastreboff AM et al. 2022, New England Journal of Medicine, PMID 35658024"},{"art":"clinico","kurz":"In uno studio randomizzato testa a testa con 1.879 persone con diabete di tipo 2, tirzepatide ha abbassato l'HbA1c da 2,09 a 2,46 punti percentuali e il peso corporeo da 7,8 a 12,4 kg dopo 40 settimane, in ogni caso più di semaglutide 1 mg.","kurz_en":"In uno studio randomizzato testa a testa con 1.879 persone con diabete di tipo 2, tirzepatide ha abbassato l'HbA1c da 2,09 a 2,46 punti percentuali e il peso corporeo da 7,8 a 12,4 kg dopo 40 settimane, in ogni caso più di semaglutide 1 mg.","quelle":"Frías JP et al. 2021, New England Journal of Medicine, PMID 34170647"}],"sicherheit":["Gli effetti più comunemente riportati sono gastrointestinali, in particolare nausea, vomito e diarrea, con rischio di disidratazione nei casi pronunciati.","Secondo le informazioni per la prescrizione, l'uso è controindicato in persone con storia personale o familiare di carcinoma delle cellule tiroidee medullari o sindrome neoplasia endocrina multipla tipo 2.","Studi sugli animali nei ratti hanno mostrato tumori delle cellule C tiroidee dipendenti dalla quantità e dalla durata dell'esposizione, e secondo le informazioni per la prescrizione non è stato stabilito se questo risultato sia trasferibile all'uomo."],"sicherheit_en":["Gli effetti più comunemente riportati sono gastrointestinali, in particolare nausea, vomito e diarrea, con rischio di disidratazione nei casi pronunciati.","Secondo le informazioni per la prescrizione, l'uso è controindicato in persone con storia personale o familiare di carcinoma delle cellule tiroidee medullari o sindrome neoplasia endocrina multipla tipo 2.","Studi sugli animali nei ratti hanno mostrato tumori delle cellule C tiroidee dipendenti dalla quantità e dalla durata dell'esposizione, e secondo le informazioni per la prescrizione non è stato stabilito se questo risultato sia trasferibile all'uomo."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Tirzepatide è approvato come farmaco con il nome Mounjaro nell'UE da settembre 2022 per il trattamento del diabete di tipo 2 e da fine 2023 anche per la gestione del peso. Negli Stati Uniti è approvato con il nome Mounjaro per il trattamento del diabete di tipo 2 e con il nome Zepbound per la gestione del peso, ed è disponibile solo su prescrizione in entrambe le regioni. I lotti di ricerca descritti qui non sono equivalenti ai prodotti farmaceutici finiti approvati.","rechtsstatus_en":"Tirzepatide è approvato come farmaco con il nome Mounjaro nell'UE da settembre 2022 per il trattamento del diabete di tipo 2 e da fine 2023 anche per la gestione del peso. Negli Stati Uniti è approvato con il nome Mounjaro per il trattamento del diabete di tipo 2 e con il nome Zepbound per la gestione del peso, ed è disponibile solo su prescrizione in entrambe le regioni. I lotti di ricerca descritti qui non sono equivalenti ai prodotti farmaceutici finiti approvati.","typischeMg":[10,30,60],"faq":[{"q":"Tirzepatide è un farmaco approvato?","a":"Sì, tirzepatide è approvato come farmaco da prescrizione con i nomi Mounjaro e Zepbound. La sostanza descritta qui è solo un lotto di ricerca, non un prodotto farmaceutico finito.","q_en":"Tirzepatide è un farmaco approvato?","a_en":"Sì, tirzepatide è approvato come farmaco da prescrizione con i nomi Mounjaro e Zepbound. La sostanza descritta qui è solo un lotto di ricerca, non un prodotto farmaceutico finito."},{"q":"Come si differenzia il tirzepatide dal semaglutide?","a":"Il semaglutide agisce solo sul recettore GLP-1, mentre il tirzepatide agisce in aggiunta sul recettore GIP. In uno studio comparativo, il tirzepatide ha mostrato effetti maggiori su HbA1c e peso corporeo rispetto al semaglutide.","q_en":"Come si differenzia il tirzepatide dal semaglutide?","a_en":"Il semaglutide agisce solo sul recettore GLP-1, mentre il tirzepatide agisce in aggiunta sul recettore GIP. In uno studio comparativo, il tirzepatide ha mostrato effetti maggiori su HbA1c e peso corporeo rispetto al semaglutide."},{"q":"A cosa si usa il tirzepatide come farmaco?","a":"Come farmaco approvato, il tirzepatide è prescritto per il diabete di tipo 2 e la gestione del peso. Questa pagina descrive la sostanza esclusivamente come un composto di ricerca per scopi di laboratorio.","q_en":"A cosa si usa il tirzepatide come farmaco?","a_en":"Come farmaco approvato, il tirzepatide è prescritto per il diabete di tipo 2 e la gestione del peso. Questa pagina descrive la sostanza esclusivamente come un composto di ricerca per scopi di laboratorio."}],"seo":{"title":"Tirzepatide: Panoramica del composto Dual GIP/GLP-1","title_en":"Tirzepatide: Panoramica del composto Dual GIP/GLP-1","description":"Tirzepatide in sintesi: meccanismo duale GIP/GLP-1, evidenze degli studi SURMOUNT e SURPASS, profilo di sicurezza e stato legale del composto.","description_en":"Tirzepatide in sintesi: meccanismo duale GIP/GLP-1, evidenze degli studi SURMOUNT e SURPASS, profilo di sicurezza e stato legale del composto."},"demo":false,"steckbrief":{"cas":"2023788-19-2","molekulargewicht":"4813 g/mol","aminosaeuren":39,"halbwertszeit":"≈ 5 giorni (eliminazione, informazioni di prescrizione Mounjaro)","reinheitsstandard":"≥ 99 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":39,"quellen":["PubChem CID 166567236","DailyMed SPL MOUNJARO (Tirzepatid), Eli Lilly and Company","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 5 giorni (eliminazione, informazioni di prescrizione Mounjaro)","reinheitsstandard_en":"≥ 99 % (HPLC, standard commerciale)"},"verwandt":["semaglutid","retatrutid","cagrilintid","survodutid"]},{"slug":"cjc-1295","name":"CJC-1295","synonyme":["Mod GRF 1-29","Modified GRF (1-29)","CJC-1295 con DAC","DAC:GRF"],"kategorie":"Wachstumshormon-Achse","studienlage":"frühe klinische Studien","kurz":"Un analogo sintetico dell'ormone di rilascio della crescita, studiato in due varianti con diverse durate di azione.","kurz_en":"Un analogo sintetico dell'ormone di rilascio della crescita, studiato in due varianti con diverse durate di azione.","beschreibung":"CJC-1295 è un analogo stabilizzato del GHRH endogeno, studiato nel contesto dell'asse dell'ormone della crescita. Esiste in due varianti: senza DAC (Drug Affinity Complex), che ha una breve durata d'azione, e con DAC, che ottiene una durata sostanzialmente estesa tramite legame con l'albumina sierica. I dati umani disponibili provengono principalmente da ricerche cliniche iniziali in adulti sani.","beschreibung_en":"CJC-1295 è un analogo stabilizzato del GHRH endogeno, studiato nel contesto dell'asse dell'ormone della crescita. Esiste in due varianti: senza DAC (Drug Affinity Complex), che ha una breve durata d'azione, e con DAC, che ottiene una durata sostanzialmente estesa tramite legame con l'albumina sierica. I dati umani disponibili provengono principalmente da ricerche cliniche iniziali in adulti sani.","mechanismus":"CJC-1295 si lega al recettore del GHRH sulle cellule somatotrope nella ghiandola pituitaria, innescando il rilascio pulsatile dell'ormone della crescita del corpo. Senza DAC, la molecola viene degradata entro minuti, producendo un impulso ormonale breve e pronunciato. Con DAC, un ancoraggio chimico si lega covalentemente all'albumina nel sangue, estendendo la durata d'azione per diversi giorni, mentre gli studi indicano che il modello di rilascio pulsatile è preservato.","mechanismus_en":"CJC-1295 si lega al recettore del GHRH sulle cellule somatotrope nella ghiandola pituitaria, innescando il rilascio pulsatile dell'ormone della crescita del corpo. Senza DAC, la molecola viene degradata entro minuti, producendo un impulso ormonale breve e pronunciato. Con DAC, un ancoraggio chimico si lega covalentemente all'albumina nel sangue, estendendo la durata d'azione per diversi giorni, mentre gli studi indicano che il modello di rilascio pulsatile è preservato.","evidenz":[{"art":"clinico","kurz":"Due studi randomizzati, controllati con placebo in adulti sani con quantità crescenti a gradini: un'iniezione singola di CJC-1295 con DAC ha aumentato i livelli di ormone della crescita per diversi giorni e i livelli di IGF-1 per 9 a 11 giorni.","kurz_en":"Due studi randomizzati, controllati con placebo in adulti sani con quantità crescenti a gradini: un'iniezione singola di CJC-1295 con DAC ha aumentato i livelli di ormone della crescita per diversi giorni e i livelli di IGF-1 per 9 a 11 giorni.","quelle":"Teichman et al. 2006, Journal of Clinical Endocrinology & Metabolism, PMID 16352683"},{"art":"clinico","kurz":"Un'analisi di follow-up degli stessi soggetti ha rilevato che il rilascio pulsatile dell'ormone della crescita è stato preservato anche sotto la stimolazione estesa da CJC-1295 con DAC.","kurz_en":"Un'analisi di follow-up degli stessi soggetti ha rilevato che il rilascio pulsatile dell'ormone della crescita è stato preservato anche sotto la stimolazione estesa da CJC-1295 con DAC.","quelle":"Ionescu & Frohman 2006, Journal of Clinical Endocrinology & Metabolism, PMID 17018654"}],"sicherheit":["Negli studi disponibili, sono state riportate principalmente reazioni locali lievi nel sito di iniezione.","Uno studio di fase 2 di CJC-1295 con DAC per una condizione non correlata è stato interrotto come precauzione dopo la morte di un partecipante; non è stata stabilita una relazione causale con il peptide.","Gli effetti a lungo termine di un livello di IGF-1 persistentemente elevato negli esseri umani non sono pienamente compresi.","I dati di sicurezza negli esseri umani a lungo termine non sono ancora disponibili."],"sicherheit_en":["Negli studi disponibili, sono state riportate principalmente reazioni locali lievi nel sito di iniezione.","Uno studio di fase 2 di CJC-1295 con DAC per una condizione non correlata è stato interrotto come precauzione dopo la morte di un partecipante; non è stata stabilita una relazione causale con il peptide.","Gli effetti a lungo termine di un livello di IGF-1 persistentemente elevato negli esseri umani non sono pienamente compresi.","I dati di sicurezza negli esseri umani a lungo termine non sono ancora disponibili."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"CJC-1295 non è approvato come farmaco né nell'UE né negli Stati Uniti. Viene venduto esclusivamente come sostanza chimica per la ricerca e non è destinato all'uso umano.","rechtsstatus_en":"CJC-1295 non è approvato come farmaco né nell'UE né negli Stati Uniti. Viene venduto esclusivamente come sostanza chimica per la ricerca e non è destinato all'uso umano.","typischeMg":[2,5],"faq":[{"q":"Qual è la differenza tra CJC-1295 con e senza DAC","a":"Senza DAC, il peptide si degrada entro minuti, producendo un breve e pronunciato picco ormonale. Con DAC, un ancoraggio chimico si lega all'albumina nel sangue, estendendo la durata per diversi giorni, mentre gli studi indicano che il modello di rilascio pulsatile è preservato.","q_en":"Qual è la differenza tra CJC-1295 con e senza DAC","a_en":"Senza DAC, il peptide si degrada entro minuti, producendo un breve e pronunciato picco ormonale. Con DAC, un ancoraggio chimico si lega all'albumina nel sangue, estendendo la durata per diversi giorni, mentre gli studi indicano che il modello di rilascio pulsatile è preservato."},{"q":"CJC-1295 è un farmaco approvato","a":"No. CJC-1295 non è approvato come farmaco nell'UE o negli Stati Uniti e viene venduto esclusivamente come sostanza chimica per la ricerca per uso in laboratorio.","q_en":"CJC-1295 è un farmaco approvato","a_en":"No. CJC-1295 non è approvato come farmaco nell'UE o negli Stati Uniti e viene venduto esclusivamente come sostanza chimica per la ricerca per uso in laboratorio."},{"q":"Per cosa viene studiato CJC-1295 nella ricerca","a":"CJC-1295 viene studiato nel contesto dell'asse dell'ormone della crescita, in particolare riguardo al rilascio dell'ormone della crescita proprio del corpo e alla conseguente produzione di IGF-1 nel fegato.","q_en":"Per cosa viene studiato CJC-1295 nella ricerca","a_en":"CJC-1295 viene studiato nel contesto dell'asse dell'ormone della crescita, in particolare riguardo al rilascio dell'ormone della crescita proprio del corpo e alla conseguente produzione di IGF-1 nel fegato."}],"seo":{"title":"Panoramica della ricerca su CJC-1295","title_en":"Panoramica della ricerca su CJC-1295","description":"CJC-1295 spiegato fattualmente: meccanismo d'azione, la differenza con e senza DAC, dati degli studi e stato legale di questo analogo di GHRH.","description_en":"CJC-1295 spiegato fattualmente: meccanismo d'azione, la differenza con e senza DAC, dati degli studi e stato legale di questo analogo di GHRH."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":null,"aminosaeuren":null,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":null,"quellen":["chemverify Katalog 14.09.2026 (Eintrag deckt CJC-1295 mit und ohne DAC generisch ab, CAS/Molekulargewicht nicht eindeutig einer Variante zuordenbar)"]},"verwandt":["ipamorelin","sermorelin","tesamorelin","igf-1-lr3"]},{"slug":"hexarelin","name":"Hexarelin","synonyme":[],"kategorie":"Wachstumshormon-Achse","studienlage":"frühe klinische Studien","kurz":"Un esapeptide sintetico dalla classe dei peptidi rilasciatori dell'ormone della crescita, studiato in ricerche cliniche iniziali sul rilascio dell'ormone della crescita.","kurz_en":"Un esapeptide sintetico dalla classe dei peptidi rilasciatori dell'ormone della crescita, studiato in ricerche cliniche iniziali sul rilascio dell'ormone della crescita.","beschreibung":"L'hexarelin è un esapeptide sintetico dalla classe dei peptidi rilasciatori dell'ormone della crescita (GHRP), descritto farmacologicamente per la prima volta nel 1994. È stato studiato in trial clinici sul rilascio dell'ormone della crescita in bambini, adulti e anziani, e separatamente in ricerche precliniche sugli effetti cardiaci.","beschreibung_en":"L'hexarelin è un esapeptide sintetico dalla classe dei peptidi rilasciatori dell'ormone della crescita (GHRP), descritto farmacologicamente per la prima volta nel 1994. È stato studiato in trial clinici sul rilascio dell'ormone della crescita in bambini, adulti e anziani, e separatamente in ricerche precliniche sugli effetti cardiaci.","mechanismus":"L'hexarelin si lega al recettore della grelina (GHS-R1a) nell'ipotalamo e nella ghiandola pituitaria, innescando un rilascio pulsatile dell'ormone della crescita proprio del corpo. A differenza di peptidi più selettivi della stessa classe come l'ipamorelina, l'hexarelin ha mostrato un rilascio aggiuntivo rilevante di ACTH e cortisolo negli studi. Le ricerche precliniche descrivono anche un legame indipendente dall'ormone della crescita ai recettori GHS-R1a cardiaci.","mechanismus_en":"L'hexarelin si lega al recettore della grelina (GHS-R1a) nell'ipotalamo e nella ghiandola pituitaria, innescando un rilascio pulsatile dell'ormone della crescita proprio del corpo. A differenza di peptidi più selettivi della stessa classe come l'ipamorelina, l'hexarelin ha mostrato un rilascio aggiuntivo rilevante di ACTH e cortisolo negli studi. Le ricerche precliniche descrivono anche un legame indipendente dall'ormone della crescita ai recettori GHS-R1a cardiaci.","evidenz":[{"art":"preclinico","kurz":"Negli studi su ratti neonati e adulti, hexarelin ha innescato un rilascio pronunciato e duraturo dell'ormone della crescita ed è stato più efficace del peptide correlato GHRP-6 se somministrato per via sottocutanea.","kurz_en":"Negli studi su ratti neonati e adulti, hexarelin ha innescato un rilascio pronunciato e duraturo dell'ormone della crescita ed è stato più efficace del peptide correlato GHRP-6 se somministrato per via sottocutanea.","quelle":"Deghenghi R et al. 1994, Life Sciences, Bd. 54(18), S. 1321-1328, PMID 7910650"},{"art":"clinico","kurz":"In uno studio di 60 persone di età compresa tra 5 e 81 anni, la risposta dell'ormone della crescita all'hexarelin è stata confrontata tra bambini prepuberali e puberali, giovani adulti e adulti più anziani, con una risposta marcatamente più debole nei bambini prepuberali e nei partecipanti più anziani.","kurz_en":"In uno studio di 60 persone di età compresa tra 5 e 81 anni, la risposta dell'ormone della crescita all'hexarelin è stata confrontata tra bambini prepuberali e puberali, giovani adulti e adulti più anziani, con una risposta marcatamente più debole nei bambini prepuberali e nei partecipanti più anziani.","quelle":"Arvat E et al. 1997, European Journal of Endocrinology, Bd. 137(6), PMID 9437229"},{"art":"clinico","kurz":"In uno studio di 15 uomini sani, l'hexarelin ha aumentato ACTH e cortisolo, un effetto che è stato potenziato dalla desmopressina (un analogo della vasopressina), suggerendo un coinvolgimento della vasopressina in questo effetto collaterale.","kurz_en":"In uno studio di 15 uomini sani, l'hexarelin ha aumentato ACTH e cortisolo, un effetto che è stato potenziato dalla desmopressina (un analogo della vasopressina), suggerendo un coinvolgimento della vasopressina in questo effetto collaterale.","quelle":"Korbonits M et al. 1999, Journal of Clinical Endocrinology & Metabolism, Bd. 84(7), S. 2489-2495, PMID 10404825"},{"art":"preclinico","kurz":"In un modello nel ratto, hexarelin ha mostrato effetti protettivi sul cuore dopo ischemia-riperfusione, che si sono verificati indipendentemente dall'attività dell'ormone della crescita e sono stati attribuiti al legame diretto ai recettori cardiaci.","kurz_en":"In un modello nel ratto, hexarelin ha mostrato effetti protettivi sul cuore dopo ischemia-riperfusione, che si sono verificati indipendentemente dall'attività dell'ormone della crescita e sono stati attribuiti al legame diretto ai recettori cardiaci.","quelle":"Locatelli V et al. 1999, Endocrinology, Bd. 140(9), S. 4024-4031, PMID 10465272"}],"sicherheit":["In studi clinici, l'hexarelin ha innescato non solo l'ormone della crescita ma anche un rilascio rilevante di ACTH, cortisolo e prolattina, un effetto non osservato in tale misura con GHRP più selettivi come l'ipamorelina.","La risposta dell'ormone della crescita all'hexarelin è marcatamente più debole nei bambini prepuberali e negli adulti più anziani rispetto agli adolescenti e ai giovani adulti.","Non sono disponibili dati di sicurezza a lungo termine indipendenti in adulti sani oltre gli studi brevi controllati.","Le interazioni con altri assi ormonali, in particolare l'asse ipotalamo-ipofisi-surrene, non sono state studiate in modo conclusivo."],"sicherheit_en":["In studi clinici, l'hexarelin ha innescato non solo l'ormone della crescita ma anche un rilascio rilevante di ACTH, cortisolo e prolattina, un effetto non osservato in tale misura con GHRP più selettivi come l'ipamorelina.","La risposta dell'ormone della crescita all'hexarelin è marcatamente più debole nei bambini prepuberali e negli adulti più anziani rispetto agli adolescenti e ai giovani adulti.","Non sono disponibili dati di sicurezza a lungo termine indipendenti in adulti sani oltre gli studi brevi controllati.","Le interazioni con altri assi ormonali, in particolare l'asse ipotalamo-ipofisi-surrene, non sono state studiate in modo conclusivo."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"L'hexarelin non è approvata come farmaco in Germania, nell'UE o negli Stati Uniti ed è venduta esclusivamente come sostanza chimica di ricerca per scopi di laboratorio.","rechtsstatus_en":"L'hexarelin non è approvata come farmaco in Germania, nell'UE o negli Stati Uniti ed è venduta esclusivamente come sostanza chimica di ricerca per scopi di laboratorio.","typischeMg":[2,5],"faq":[{"q":"L'hexarelin differisce dall'ipamorelina","a":"Sì. Entrambe si legano allo stesso recettore della grelina, ma l'hexarelin ha inoltre mostrato un rilascio rilevante di ACTH e cortisolo negli studi, mentre l'ipamorelina è considerata più selettiva per l'asse dell'ormone della crescita da sola.","q_en":"L'hexarelin differisce dall'ipamorelina","a_en":"Sì. Entrambe si legano allo stesso recettore della grelina, ma l'hexarelin ha inoltre mostrato un rilascio rilevante di ACTH e cortisolo negli studi, mentre l'ipamorelina è considerata più selettiva per l'asse dell'ormone della crescita da sola."},{"q":"L'hexarelin è stata studiata nei bambini","a":"L'hexarelin è stata utilizzata in studi clinici sulla secrezione dell'ormone della crescita nei bambini a diverse fasi puberali, all'interno di protocolli di ricerca controllati e non come farmaco approvato.","q_en":"L'hexarelin è stata studiata nei bambini","a_en":"L'hexarelin è stata utilizzata in studi clinici sulla secrezione dell'ormone della crescita nei bambini a diverse fasi puberali, all'interno di protocolli di ricerca controllati e non come farmaco approvato."},{"q":"L'hexarelin è un farmaco approvato","a":"No. L'hexarelin non è approvata come farmaco nell'UE o negli Stati Uniti ed è offerta esclusivamente come sostanza chimica di ricerca, non per uso umano.","q_en":"L'hexarelin è un farmaco approvato","a_en":"No. L'hexarelin non è approvata come farmaco nell'UE o negli Stati Uniti ed è offerta esclusivamente come sostanza chimica di ricerca, non per uso umano."}],"seo":{"title":"Panoramica della ricerca su hexarelin","title_en":"Panoramica della ricerca su hexarelin","description":"L'hexarelin spiegata fattualmente: meccanismo d'azione, dati di studio sull'ormone della crescita e ACTH/cortisolo, profilo di sicurezza e stato legale di questo peptide GHRP.","description_en":"L'hexarelin spiegata fattualmente: meccanismo d'azione, dati di studio sull'ormone della crescita e ACTH/cortisolo, profilo di sicurezza e stato legale di questo peptide GHRP."},"demo":false,"steckbrief":{"cas":"140703-51-1","molekulargewicht":"887,0 g/mol","aminosaeuren":6,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":6,"quellen":["PubChem CID 6918297","chemverify Katalog 14.09.2026"]},"verwandt":["ipamorelin","cjc-1295","sermorelin","igf-1-lr3"]},{"slug":"igf-1-lr3","name":"IGF-1 LR3","synonyme":["Long R3 IGF-1","LR3-IGF-1","IGF-1 Long R3"],"kategorie":"Wachstumshormon-Achse","studienlage":"präklinisch","kurz":"Un analogo geneticamente allungato dell'IGF-1 con 83 amminoacidi, studiato in modelli animali per gli effetti sulla crescita e elencato come sostanza dopante nello sport competitivo.","kurz_en":"Un analogo geneticamente allungato dell'IGF-1 con 83 amminoacidi, studiato in modelli animali per gli effetti sulla crescita e elencato come sostanza dopante nello sport competitivo.","beschreibung":"IGF-1 LR3 è un analogo ricombinante del fattore di crescita insulino-simile 1 naturalmente presente, originariamente sviluppato per la ricerca in colture cellulari. Porta aminoacidi aggiuntivi all'N-terminale e una posizione 3 alterata, il che lo rende in gran parte incapace di legarsi alle proteine leganti IGF. Viene studiato principalmente in modelli animali di crescita di organi e cellule, ma al di fuori della ricerca è anche ampiamente utilizzato per il miglioramento delle prestazioni presunto senza dati umani solidi.","beschreibung_en":"IGF-1 LR3 è un analogo ricombinante del fattore di crescita insulino-simile 1 naturalmente presente, originariamente sviluppato per la ricerca in colture cellulari. Porta aminoacidi aggiuntivi all'N-terminale e una posizione 3 alterata, il che lo rende in gran parte incapace di legarsi alle proteine leganti IGF. Viene studiato principalmente in modelli animali di crescita di organi e cellule, ma al di fuori della ricerca è anche ampiamente utilizzato per il miglioramento delle prestazioni presunto senza dati umani solidi.","mechanismus":"Poiché si lega scarsamente alle proteine leganti IGF, una quota maggiore di IGF-1 LR3 rimane libera e attiva il recettore IGF-1 più fortemente e più a lungo del IGF-1 nativo. Nei modelli preclinici, ciò è descritto come la promozione di una maggiore proliferazione cellulare attraverso le vie ERK e PI3K/Akt. Allo stesso tempo, si riporta la soppressione della produzione endogena di IGF-1 e dei livelli di proteine leganti IGF.","mechanismus_en":"Poiché si lega scarsamente alle proteine leganti IGF, una quota maggiore di IGF-1 LR3 rimane libera e attiva il recettore IGF-1 più fortemente e più a lungo del IGF-1 nativo. Nei modelli preclinici, ciò è descritto come la promozione di una maggiore proliferazione cellulare attraverso le vie ERK e PI3K/Akt. Allo stesso tempo, si riporta la soppressione della produzione endogena di IGF-1 e dei livelli di proteine leganti IGF.","evidenz":[{"art":"preclinico","kurz":"Uno studio di infusione nelle cavie descrisse un aumento della crescita degli organi sotto R3 IGF-1 prolungato, mentre allo stesso tempo i livelli plasmatici di IGF-1 endogeno, IGF-2 e proteine leganti IGF diminuirono.","kurz_en":"Uno studio di infusione nelle cavie descrisse un aumento della crescita degli organi sotto R3 IGF-1 prolungato, mentre allo stesso tempo i livelli plasmatici di IGF-1 endogeno, IGF-2 e proteine leganti IGF diminuirono.","quelle":"Conlon et al. 1995, Journal of Endocrinology, PMID 7561636"},{"art":"preclinico","kurz":"Uno studio cellulare in cardiomiociti di ovini fetali ha utilizzato IGF-1 LR3 come stimolo stabile del recettore e ha descritto la proliferazione cellulare mediata attraverso le vie ERK e PI3K.","kurz_en":"Uno studio cellulare in cardiomiociti di ovini fetali ha utilizzato IGF-1 LR3 come stimolo stabile del recettore e ha descritto la proliferazione cellulare mediata attraverso le vie ERK e PI3K.","quelle":"Sundgren et al. 2003, American Journal of Physiology, PMID 12947030"},{"art":"clinico","kurz":"Una revisione del 2026 ha descritto un divario sostanziale tra la base di evidenze cliniche per i peptidi dell'asse dell'ormone della crescita come IGF-1 LR3 e la loro auto somministrazione diffusa al di fuori della supervisione medica.","kurz_en":"Una revisione del 2026 ha descritto un divario sostanziale tra la base di evidenze cliniche per i peptidi dell'asse dell'ormone della crescita come IGF-1 LR3 e la loro auto somministrazione diffusa al di fuori della supervisione medica.","quelle":"Dominikowski et al. 2026, Frontiers in Endocrinology, PMID 42395176"}],"sicherheit":["Mancano studi di sicurezza umana controllati su IGF-1 LR3, le evidenze disponibili provengono da modelli cellulari e animali.","I modelli animali descrivono la soppressione dell'asse IGF-1 del corpo, le cui conseguenze non sono state studiate negli esseri umani.","L'elevazione incontrollata dell'attività di IGF-1 è discussa nella letteratura come fattore di rischio teorico per la crescita indesiderata di cellule e tessuti, non è stata stabilita una connessione causale negli esseri umani.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"sicherheit_en":["Mancano studi di sicurezza umana controllati su IGF-1 LR3, le evidenze disponibili provengono da modelli cellulari e animali.","I modelli animali descrivono la soppressione dell'asse IGF-1 del corpo, le cui conseguenze non sono state studiate negli esseri umani.","L'elevazione incontrollata dell'attività di IGF-1 è discussa nella letteratura come fattore di rischio teorico per la crescita indesiderata di cellule e tessuti, non è stata stabilita una connessione causale negli esseri umani.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"IGF-1 LR3 non è autorizzato come farmaco in Germania, nell’UE o negli Stati Uniti e non è classificato come prodotto alimentare. È venduto esclusivamente come sostanza chimica per la ricerca. Nello sport organizzato è sempre vietato come fattore di crescita di categoria S2 secondo la Lista delle sostanze proibite della WADA.","rechtsstatus_en":"IGF-1 LR3 non è autorizzato come farmaco in Germania, nell’UE o negli Stati Uniti e non è classificato come prodotto alimentare. È venduto esclusivamente come sostanza chimica per la ricerca. Nello sport organizzato è sempre vietato come fattore di crescita di categoria S2 secondo la Lista delle sostanze proibite della WADA.","typischeMg":[],"faq":[{"q":"Cosa distingue IGF-1 LR3 dal IGF-1 naturale?","a":"IGF-1 LR3 porta aminoacidi aggiuntivi all'N-terminale e una posizione 3 alterata, il che significa che si lega a stento alle proteine leganti IGF e quindi agisce sul recettore più a lungo e più fortemente del IGF-1 nativo.","q_en":"Cosa distingue IGF-1 LR3 dal IGF-1 naturale?","a_en":"IGF-1 LR3 porta aminoacidi aggiuntivi all'N-terminale e una posizione 3 alterata, il che significa che si lega a stento alle proteine leganti IGF e quindi agisce sul recettore più a lungo e più fortemente del IGF-1 nativo."},{"q":"Il IGF-1 LR3 è consentito nello sport?","a":"No, è elencato come fattore di crescita sulla Lista Proibita WADA (categoria S2) ed è vietato in ogni momento nello sport organizzato.","q_en":"Il IGF-1 LR3 è consentito nello sport?","a_en":"No, è elencato come fattore di crescita sulla Lista Proibita WADA (categoria S2) ed è vietato in ogni momento nello sport organizzato."},{"q":"Ci sono studi sull'uomo su IGF-1 LR3?","a":"Non sono disponibili studi sull'uomo controllati, le evidenze esistenti provengono da modelli cellulari e animali, una revisione del 2026 indica questa lacuna delle evidenze.","q_en":"Ci sono studi sull'uomo su IGF-1 LR3?","a_en":"Non sono disponibili studi sull'uomo controllati, le evidenze esistenti provengono da modelli cellulari e animali, una revisione del 2026 indica questa lacuna delle evidenze."}],"seo":{"title":"IGF-1 LR3: profilo di ricerca ed evidenze","title_en":"IGF-1 LR3: profilo di ricerca ed evidenze","description":"Panoramica IGF-1 LR3: struttura, evidenze precliniche, stato di doping nello sport (WADA S2) e profilo di sicurezza, presentate in modo fattuale per il contesto della ricerca.","description_en":"Panoramica IGF-1 LR3: struttura, evidenze precliniche, stato di doping nello sport (WADA S2) e profilo di sicurezza, presentate in modo fattuale per il contesto della ricerca."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":"9111,4 g/mol","aminosaeuren":83,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":83,"quellen":["chemverify Katalog 14.09.2026 (PubChem: kein Eintrag für IGF-1 LR3, CAS dort nicht geführt)"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)"},"verwandt":["hexarelin","cjc-1295","tesamorelin","sermorelin"]},{"slug":"ipamorelin","name":"Ipamorelina","synonyme":["NNC 26-0161"],"kategorie":"Wachstumshormon-Achse","studienlage":"frühe klinische Studien","kurz":"Un pentapeptide selettivo dalla classe dei peptidi rilasciatori dell'ormone della crescita, studiato in ricerche cliniche iniziali.","kurz_en":"Un pentapeptide selettivo dalla classe dei peptidi rilasciatori dell'ormone della crescita, studiato in ricerche cliniche iniziali.","beschreibung":"Ipamorelina è un peptide sintetico composto da cinque amminoacidi che imita il messaggero proprio del corpo ghrelina. È stato descritto per la prima volta nel 1998 come il primo membro selettivo della sua classe di farmaci ed è stato studiato in trial clinici inclusi pazienti in recupero da interventi chirurgici addominali. Per applicazioni correlate all'ormone della crescita, non sono disponibili studi controllati in adulti sani ad oggi.","beschreibung_en":"Ipamorelina è un peptide sintetico composto da cinque amminoacidi che imita il messaggero proprio del corpo ghrelina. È stato descritto per la prima volta nel 1998 come il primo membro selettivo della sua classe di farmaci ed è stato studiato in trial clinici inclusi pazienti in recupero da interventi chirurgici addominali. Per applicazioni correlate all'ormone della crescita, non sono disponibili studi controllati in adulti sani ad oggi.","mechanismus":"L'ipamorelina si lega selettivamente al recettore della ghrelina (GHS-R1A) nell'ipotalamo e nella ghiandola pituitaria, allentando l'effetto inibitorio della somatostatina. Ciò porta al rilascio pulsatile dell'ormone della crescita proprio del corpo dalla ghiandola pituitaria. A differenza dei peptidi più vecchi della stessa classe, gli studi non hanno trovato un aumento rilevante di ACTH, cortisolo o prolattina con l'ipamorelina.","mechanismus_en":"L'ipamorelina si lega selettivamente al recettore della ghrelina (GHS-R1A) nell'ipotalamo e nella ghiandola pituitaria, allentando l'effetto inibitorio della somatostatina. Ciò porta al rilascio pulsatile dell'ormone della crescita proprio del corpo dalla ghiandola pituitaria. A differenza dei peptidi più vecchi della stessa classe, gli studi non hanno trovato un aumento rilevante di ACTH, cortisolo o prolattina con l'ipamorelina.","evidenz":[{"art":"preclinico","kurz":"La descrizione originale in un modello su maiale ha mostrato che l'ipamorelina rilascia l'ormone della crescita senza un effetto rilevante su ACTH, cortisolo, prolattina, FSH o LH, a differenza dei peptidi più vecchi della stessa classe.","kurz_en":"La descrizione originale in un modello su maiale ha mostrato che l'ipamorelina rilascia l'ormone della crescita senza un effetto rilevante su ACTH, cortisolo, prolattina, FSH o LH, a differenza dei peptidi più vecchi della stessa classe.","quelle":"Raun et al. 1998, European Journal of Endocrinology, PMID 9849822"},{"art":"preclinico","kurz":"In un modello di ratto di paralisi intestinale postoperatoria, l'ipamorelina ha accelerato il ritorno del movimento intestinale dopo l'intervento chirurgico.","kurz_en":"In un modello di ratto di paralisi intestinale postoperatoria, l'ipamorelina ha accelerato il ritorno del movimento intestinale dopo l'intervento chirurgico.","quelle":"Venkova et al. 2009, Journal of Pharmacology and Experimental Therapeutics, PMID 19289567"},{"art":"clinico","kurz":"In uno studio randomizzato, controllato con placebo di fase 2 in 117 pazienti dopo chirurgia intestinale, il tempo fino al primo pasto tollerato non ha differito statisticamente tra i gruppi ipamorelina e placebo.","kurz_en":"In uno studio randomizzato, controllato con placebo di fase 2 in 117 pazienti dopo chirurgia intestinale, il tempo fino al primo pasto tollerato non ha differito statisticamente tra i gruppi ipamorelina e placebo.","quelle":"International Journal of Colorectal Disease 2014, DOI 10.1007/s00384-014-2030-8"}],"sicherheit":["Nell'esperimento controllato più grande a oggi, gli eventi avversi riportati sono stati frequenti in modo simile nei gruppi ipamorelina e placebo.","La FDA ha interrotto lo sviluppo clinico dell'ipamorelina nel 2023 dopo due decessi avvenuti nel gruppo di studio; un legame causale con il peptide è considerato scientificamente contestato.","I dati di sicurezza a lungo termine negli adulti sani non sono disponibili.","Le interazioni con altri assi ormonali non sono state completamente studiate."],"sicherheit_en":["Nell'esperimento controllato più grande a oggi, gli eventi avversi riportati sono stati frequenti in modo simile nei gruppi ipamorelina e placebo.","La FDA ha interrotto lo sviluppo clinico dell'ipamorelina nel 2023 dopo due decessi avvenuti nel gruppo di studio; un legame causale con il peptide è considerato scientificamente contestato.","I dati di sicurezza a lungo termine negli adulti sani non sono disponibili.","Le interazioni con altri assi ormonali non sono state completamente studiate."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Ipamorelina non è approvata come farmaco né nell'UE né negli Stati Uniti. La FDA ha interrotto lo sviluppo clinico ulteriore nel 2023. Viene venduta esclusivamente come sostanza chimica di ricerca.","rechtsstatus_en":"Ipamorelina non è approvata come farmaco né nell'UE né negli Stati Uniti. La FDA ha interrotto lo sviluppo clinico ulteriore nel 2023. Viene venduta esclusivamente come sostanza chimica di ricerca.","typischeMg":[2,5],"faq":[{"q":"L'ipamorelina aumenta il cortisolo come i peptidi più vecchi della stessa classe","a":"Negli studi disponibili, a differenza dei peptidi più vecchi come GHRP-6 o GHRP-2, l'ipamorelina non ha mostrato un aumento rilevante di ACTH o cortisolo. Questa è considerata la sua caratteristica distintiva meglio documentata scientificamente.","q_en":"L'ipamorelina aumenta il cortisolo come i peptidi più vecchi della stessa classe","a_en":"Negli studi disponibili, a differenza dei peptidi più vecchi come GHRP-6 o GHRP-2, l'ipamorelina non ha mostrato un aumento rilevante di ACTH o cortisolo. Questa è considerata la sua caratteristica distintiva meglio documentata scientificamente."},{"q":"L'ipamorelina è un farmaco approvato","a":"No. La FDA ha interrotto lo sviluppo clinico dell'ipamorelina nel 2023. Non è approvato nell'UE o negli Stati Uniti e viene venduto come sostanza chimica di ricerca.","q_en":"L'ipamorelina è un farmaco approvato","a_en":"No. La FDA ha interrotto lo sviluppo clinico dell'ipamorelina nel 2023. Non è approvato nell'UE o negli Stati Uniti e viene venduto come sostanza chimica di ricerca."},{"q":"Perché è stato interrotto lo sviluppo dell'ipamorelina","a":"Dopo che si sono verificate due morti in una popolazione di pazienti gravemente malati dopo un intervento chirurgico addominale, la FDA ha interrotto ulteriori sviluppi nel 2023. Un legame causale con il peptide è considerato scientificamente contestato.","q_en":"Perché è stato interrotto lo sviluppo dell'ipamorelina","a_en":"Dopo che si sono verificate due morti in una popolazione di pazienti gravemente malati dopo un intervento chirurgico addominale, la FDA ha interrotto ulteriori sviluppi nel 2023. Un legame causale con il peptide è considerato scientificamente contestato."}],"seo":{"title":"Panoramica della ricerca su ipamorelina","title_en":"Panoramica della ricerca su ipamorelina","description":"Ipamorelina spiegata in modo fattuale: meccanismo d'azione selettivo, dati degli studi, profilo di sicurezza e stato legale di questo mimetico della grelina.","description_en":"Ipamorelina spiegata in modo fattuale: meccanismo d'azione selettivo, dati degli studi, profilo di sicurezza e stato legale di questo mimetico della grelina."},"demo":false,"steckbrief":{"cas":"170851-70-4","molekulargewicht":"711,9 g/mol","aminosaeuren":5,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":5,"quellen":["PubChem CID 9831659","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, standard commerciale)"},"verwandt":["cjc-1295","sermorelin","tesamorelin","hexarelin"]},{"slug":"sermorelin","name":"Sermorelina","synonyme":["GRF 1-29","GHRH(1-29)","Geref (nome commerciale storico)"],"kategorie":"Wachstumshormon-Achse","studienlage":"klinisch untersucht","kurz":"Un frammento a catena corta della GHRH del corpo stesso, storicamente approvato come farmaco, ora venduto come sostanza di ricerca.","kurz_en":"Un frammento a catena corta della GHRH del corpo stesso, storicamente approvato come farmaco, ora venduto come sostanza di ricerca.","beschreibung":"Sermorelina è il frammento biologicamente attivo GHRH(1-29) dell'ormone di rilascio dell'ormone della crescita del corpo stesso. Negli Stati Uniti è stato approvato nel 1990 come agente diagnostico e nel 1997 per la statura ridotta correlata alla carenza di ormone della crescita nei bambini; l'approvazione è stata ritirata nel 2008 per motivi di produzione. Oggi è studiato al di fuori di quell'approvazione storica come sostanza di ricerca.","beschreibung_en":"Sermorelina è il frammento biologicamente attivo GHRH(1-29) dell'ormone di rilascio dell'ormone della crescita del corpo stesso. Negli Stati Uniti è stato approvato nel 1990 come agente diagnostico e nel 1997 per la statura ridotta correlata alla carenza di ormone della crescita nei bambini; l'approvazione è stata ritirata nel 2008 per motivi di produzione. Oggi è studiato al di fuori di quell'approvazione storica come sostanza di ricerca.","mechanismus":"Il sermorelina si lega al recettore della GHRH sulle cellule somatotrope della ghiandola pituitaria e attiva la cascata adenilato ciclasi-cAMP. Ciò innesca il rilascio dell'ormone di crescita del corpo stesso in impulsi fisiologici. A causa della sua emivita molto breve di solo pochi minuti, l'impulso ormonale risultante è breve e moderato.","mechanismus_en":"Il sermorelina si lega al recettore della GHRH sulle cellule somatotrope della ghiandola pituitaria e attiva la cascata adenilato ciclasi-cAMP. Ciò innesca il rilascio dell'ormone di crescita del corpo stesso in impulsi fisiologici. A causa della sua emivita molto breve di solo pochi minuti, l'impulso ormonale risultante è breve e moderato.","evidenz":[{"art":"clinico","kurz":"In uno studio randomizzato e controllato con placebo in uomini e donne più anziani, un analogo GHRH(1-29) sostituito con Nle27 ha aumentato i livelli di ormone della crescita e IGF-1 per diversi mesi e migliorato la massa corporea senza grasso.","kurz_en":"In uno studio randomizzato e controllato con placebo in uomini e donne più anziani, un analogo GHRH(1-29) sostituito con Nle27 ha aumentato i livelli di ormone della crescita e IGF-1 per diversi mesi e migliorato la massa corporea senza grasso.","quelle":"Khorram et al. 1997, Journal of Clinical Endocrinology & Metabolism, PMID 9141536"},{"art":"clinico","kurz":"Una revisione dei dati clinici disponibili nei bambini con carenza di ormone della crescita ha descritto una velocità di crescita accelerata in dodici mesi nella maggior parte dei bambini studiati.","kurz_en":"Una revisione dei dati clinici disponibili nei bambini con carenza di ormone della crescita ha descritto una velocità di crescita accelerata in dodici mesi nella maggior parte dei bambini studiati.","quelle":"Prakash & Goa 1999, BioDrugs, PMID 18031173"}],"sicherheit":["Gli studi disponibili hanno riportato principalmente effetti collaterali lievi e transitori.","L'approvazione originale è stata ritirata nel 2008 per motivi di produzione; non c'era un avviso di sicurezza dietro questa decisione.","Si discute un possibile aumento, incoerentemente osservato, di LH e FSH nella letteratura.","I dati di sicurezza a lungo termine negli adulti sani non sono disponibili."],"sicherheit_en":["Gli studi disponibili hanno riportato principalmente effetti collaterali lievi e transitori.","L'approvazione originale è stata ritirata nel 2008 per motivi di produzione; non c'era un avviso di sicurezza dietro questa decisione.","Si discute un possibile aumento, incoerentemente osservato, di LH e FSH nella letteratura.","I dati di sicurezza a lungo termine negli adulti sani non sono disponibili."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Sermorelina è stato approvato come farmaco negli Stati Uniti dal 1990 al 2008; l'approvazione è stata ritirata per motivi di produzione. Attualmente non è commercializzato come farmaco né nell'UE né negli Stati Uniti ed è offerto come composto di ricerca.","rechtsstatus_en":"Sermorelina è stato approvato come farmaco negli Stati Uniti dal 1990 al 2008; l'approvazione è stata ritirata per motivi di produzione. Attualmente non è commercializzato come farmaco né nell'UE né negli Stati Uniti ed è offerto come composto di ricerca.","typischeMg":[5,10],"faq":[{"q":"Sermorelina è stato un tempo un farmaco approvato","a":"Sì. Sermorelina è stato approvato negli Stati Uniti dal 1990 al 2008, prima come agente diagnostico, successivamente per la statura ridotta correlata alla carenza di ormone della crescita nei bambini. L'approvazione è stata ritirata per motivi di produzione, non per preoccupazioni sulla sicurezza.","q_en":"Sermorelina è stato un tempo un farmaco approvato","a_en":"Sì. Sermorelina è stato approvato negli Stati Uniti dal 1990 al 2008, prima come agente diagnostico, successivamente per la statura ridotta correlata alla carenza di ormone della crescita nei bambini. L'approvazione è stata ritirata per motivi di produzione, non per preoccupazioni sulla sicurezza."},{"q":"Qual è la differenza tra sermorelina e CJC-1295","a":"Entrambi sono analoghi del GHRH. Sermorelina consiste nei primi 29 aminoacidi del GHRH del corpo con nessuna ulteriore modifica, mentre CJC-1295 è aggiuntivamente stabilizzato e quindi ha un'emivita più lunga.","q_en":"Qual è la differenza tra sermorelina e CJC-1295","a_en":"Entrambi sono analoghi del GHRH. Sermorelina consiste nei primi 29 aminoacidi del GHRH del corpo con nessuna ulteriore modifica, mentre CJC-1295 è aggiuntivamente stabilizzato e quindi ha un'emivita più lunga."},{"q":"Sermorelina è disponibile come farmaco oggi","a":"No. Dal ritiro dal mercato nel 2008, il sermorelina non è più disponibile come farmaco approvato nell'UE o negli Stati Uniti ed è venduto come composto di ricerca.","q_en":"Sermorelina è disponibile come farmaco oggi","a_en":"No. Dal ritiro dal mercato nel 2008, il sermorelina non è più disponibile come farmaco approvato nell'UE o negli Stati Uniti ed è venduto come composto di ricerca."}],"seo":{"title":"Panoramica della ricerca su sermorelina","title_en":"Panoramica della ricerca su sermorelina","description":"Sermorelina spiegato fattualmente: meccanismo d'azione, approvazione storica, dati di studio e stato legale attuale di questo frammento di GHRH.","description_en":"Sermorelina spiegato fattualmente: meccanismo d'azione, approvazione storica, dati di studio e stato legale attuale di questo frammento di GHRH."},"demo":false,"steckbrief":{"cas":"86168-78-7","molekulargewicht":"3357,9 g/mol","aminosaeuren":29,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":"solubile in acqua e acido acetico diluito","sequenzLaenge":29,"quellen":["PubChem CID 16132413","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit_en":"solubile in acqua e acido acetico diluito"},"verwandt":["cjc-1295","ipamorelin","tesamorelin","hexarelin"]},{"slug":"tesamorelin","name":"Tesamorelina","synonyme":["Egrifta","TH9507","Egrifta WR"],"kategorie":"Wachstumshormon-Achse","studienlage":"zugelassenes Arzneimittel","kurz":"Un analogo del GHRH stabilizzato, approvato negli Stati Uniti come farmaco Egrifta per la riduzione del grasso addominale viscerale nella lipodistrofia associata all'HIV.","kurz_en":"Un analogo del GHRH stabilizzato, approvato negli Stati Uniti come farmaco Egrifta per la riduzione del grasso addominale viscerale nella lipodistrofia associata all'HIV.","beschreibung":"Tesamorelina è un analogo stabilizzato del GHRH completo a 44 aminoacidi. Con il nome commerciale Egrifta, è stato approvato dalla FDA statunitense dal 2010 per la riduzione del grasso addominale viscerale nella lipodistrofia associata all'HIV. Questo lo rende l'unico peptide della sua classe con uno studio di approvazione di fase 3 completato in più di 800 partecipanti.","beschreibung_en":"Tesamorelina è un analogo stabilizzato del GHRH completo a 44 aminoacidi. Con il nome commerciale Egrifta, è stato approvato dalla FDA statunitense dal 2010 per la riduzione del grasso addominale viscerale nella lipodistrofia associata all'HIV. Questo lo rende l'unico peptide della sua classe con uno studio di approvazione di fase 3 completato in più di 800 partecipanti.","mechanismus":"Tesamorelina si lega al recettore del GHRH sulle cellule somatotrope nella ghiandola pituitaria, stimolando il rilascio pulsatile del proprio ormone della crescita del corpo mentre il ciclo di feedback della somatostatina rimane completamente integro. L'ormone della crescita rilasciato viene convertito in IGF-1 nel fegato. Tesamorelina agisce anche in modo relativamente selettivo sui recettori dell'ormone della crescita nel tessuto adiposo viscerale, attivando la lipasi sensibile all'ormone lì.","mechanismus_en":"Tesamorelina si lega al recettore del GHRH sulle cellule somatotrope nella ghiandola pituitaria, stimolando il rilascio pulsatile del proprio ormone della crescita del corpo mentre il ciclo di feedback della somatostatina rimane completamente integro. L'ormone della crescita rilasciato viene convertito in IGF-1 nel fegato. Tesamorelina agisce anche in modo relativamente selettivo sui recettori dell'ormone della crescita nel tessuto adiposo viscerale, attivando la lipasi sensibile all'ormone lì.","evidenz":[{"art":"clinico","kurz":"In uno studio randomizzato, controllato con placebo di fase 3 in persone con redistribuzione del grasso associata all'HIV, tesamorelina ha ridotto significativamente il tessuto adiposo viscerale rispetto al placebo in 26 settimane e ha aumentato i livelli di IGF-1.","kurz_en":"In uno studio randomizzato, controllato con placebo di fase 3 in persone con redistribuzione del grasso associata all'HIV, tesamorelina ha ridotto significativamente il tessuto adiposo viscerale rispetto al placebo in 26 settimane e ha aumentato i livelli di IGF-1.","quelle":"Falutz et al. 2007, New England Journal of Medicine, PMID 18057338"},{"art":"clinico","kurz":"Un ulteriore studio randomizzato in pazienti HIV con accumulo di grasso addominale ha confermato la riduzione del tessuto adiposo viscerale e ha inoltre mostrato una diminuzione del grasso epatico.","kurz_en":"Un ulteriore studio randomizzato in pazienti HIV con accumulo di grasso addominale ha confermato la riduzione del tessuto adiposo viscerale e ha inoltre mostrato una diminuzione del grasso epatico.","quelle":"Stanley et al. 2014, JAMA, PMID 25038357"}],"sicherheit":["L'effetto collaterale più comune riportato negli studi è stato il dolore articolare in una sottopopolazione di partecipanti.","La ritenzione di fluidi nelle estremità è stata osservata in una porzione più piccola di partecipanti, meno frequentemente rispetto all'ormone della crescita.","Il glucosio nel sangue è aumentato leggermente e temporaneamente in media negli studi.","Secondo le informazioni per la prescrizione, il tesamorelina è considerato controindicato in presenza di malattia tumorale attiva, tumore alla ghiandola pituitaria, gravidanza o retinopatia diabetica."],"sicherheit_en":["L'effetto collaterale più comune riportato negli studi è stato il dolore articolare in una sottopopolazione di partecipanti.","La ritenzione di fluidi nelle estremità è stata osservata in una porzione più piccola di partecipanti, meno frequentemente rispetto all'ormone della crescita.","Il glucosio nel sangue è aumentato leggermente e temporaneamente in media negli studi.","Secondo le informazioni per la prescrizione, il tesamorelina è considerato controindicato in presenza di malattia tumorale attiva, tumore alla ghiandola pituitaria, gravidanza o retinopatia diabetica."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Il tesamorelina è stato approvato negli Stati Uniti con il nome commerciale Egrifta dal 2010 per un'indicazione specifica nella lipodistrofia associata all'HIV. Non è approvato nell'UE o in Svizzera, e nell'Europa di lingua tedesca non è praticamente disponibile. Al di fuori dell'indicazione approvata, qualsiasi uso è considerato off-label.","rechtsstatus_en":"Il tesamorelina è stato approvato negli Stati Uniti con il nome commerciale Egrifta dal 2010 per un'indicazione specifica nella lipodistrofia associata all'HIV. Non è approvato nell'UE o in Svizzera, e nell'Europa di lingua tedesca non è praticamente disponibile. Al di fuori dell'indicazione approvata, qualsiasi uso è considerato off-label.","typischeMg":[2,5],"faq":[{"q":"Il tesamorelina è un farmaco approvato","a":"Sì, con il nome Egrifta dal 2010 negli Stati Uniti, ma solo per un'indicazione specifica: la riduzione del grasso addominale viscerale nella lipodistrofia associata all'HIV. Non c'è approvazione nell'UE.","q_en":"Il tesamorelina è un farmaco approvato","a_en":"Sì, con il nome Egrifta dal 2010 negli Stati Uniti, ma solo per un'indicazione specifica: la riduzione del grasso addominale viscerale nella lipodistrofia associata all'HIV. Non c'è approvazione nell'UE."},{"q":"Il tesamorelina costruisce muscoli","a":"Gli studi mostrano un aumento della massa corporea priva di grasso, ma una parte rilevante di questa consiste in acqua e tessuto connettivo. Una crescita muscolare notevole senza stimolazione aggiuntiva dei recettori androgeni non è documentata scientificamente.","q_en":"Il tesamorelina costruisce muscoli","a_en":"Gli studi mostrano un aumento della massa corporea priva di grasso, ma una parte rilevante di questa consiste in acqua e tessuto connettivo. Una crescita muscolare notevole senza stimolazione aggiuntiva dei recettori androgeni non è documentata scientificamente."},{"q":"Come si differenzia il tesamorelina dagli altri analoghi del GHRH","a":"Il tesamorelina è l'unico analogo del GHRH con uno studio di approvazione di fase 3 completato in più di 800 partecipanti e un'approvazione regolatoria attiva negli Stati Uniti. Sermorelina e CJC-1295 non hanno raggiunto questo status.","q_en":"Come si differenzia il tesamorelina dagli altri analoghi del GHRH","a_en":"Il tesamorelina è l'unico analogo del GHRH con uno studio di approvazione di fase 3 completato in più di 800 partecipanti e un'approvazione regolatoria attiva negli Stati Uniti. Sermorelina e CJC-1295 non hanno raggiunto questo status."}],"seo":{"title":"Panoramica della ricerca su tesamorelina","title_en":"Panoramica della ricerca su tesamorelina","description":"Tesamorelina (Egrifta) spiegato fattualmente: stato di approvazione, meccanismo d'azione, dati degli studi clinici e stato legale al di fuori degli Stati Uniti.","description_en":"Tesamorelina (Egrifta) spiegato fattualmente: stato di approvazione, meccanismo d'azione, dati degli studi clinici e stato legale al di fuori degli Stati Uniti."},"demo":false,"steckbrief":{"cas":"218949-48-5","molekulargewicht":"5136 g/mol","aminosaeuren":44,"halbwertszeit":"≈ 8 minuti (eliminazione, informazioni per la prescrizione Egrifta SV)","reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":44,"quellen":["PubChem CID 16137828","DailyMed SPL EGRIFTA SV (Tesamorelin), Theratechnologies","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 8 minuti (eliminazione, informazioni per la prescrizione Egrifta SV)","reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)"},"verwandt":["cjc-1295","ipamorelin","sermorelin","igf-1-lr3"]},{"slug":"ghk-cu","name":"GHK-Cu","synonyme":["Glicil-L-istidil-L-lisina rame","Tripeptide di rame-1"],"kategorie":"Haut & Kosmetik","studienlage":"frühe klinische Studien","kurz":"Un tripeptide naturale che lega il rame, studiato soprattutto nella ricerca sulla pelle, con ulteriori dati preclinici su altri tessuti.","kurz_en":"Un tripeptide naturale che lega il rame, studiato soprattutto nella ricerca sulla pelle, con ulteriori dati preclinici su altri tessuti.","beschreibung":"GHK-Cu è un tripeptide a tre amminoacidi che si trova naturalmente nel corpo e lega stabilmente uno ione di rame. Viene studiato principalmente in ricerche cosmetiche e dermatologiche sulla formazione di collagene e sul rinnovamento della pelle. Inoltre, la ricerca prevalentemente preclinica esamina possibili effetti sui processi infiammatori e sull'espressione genica attraverso vari modelli tissutali.","beschreibung_en":"GHK-Cu è un tripeptide a tre amminoacidi che si trova naturalmente nel corpo e lega stabilmente uno ione di rame. Viene studiato principalmente in ricerche cosmetiche e dermatologiche sulla formazione di collagene e sul rinnovamento della pelle. Inoltre, la ricerca prevalentemente preclinica esamina possibili effetti sui processi infiammatori e sull'espressione genica attraverso vari modelli tissutali.","mechanismus":"Nelle cellule della pelle, GHK-Cu è stato descritto come aumentando la sintesi di collagene ed elastina e attivando i fibroblasti, le cellule che costruiscono il tessuto connettivo. Nei modelli preclinici di espressione genica, GHK-Cu ha mostrato una regolazione dipendente dal contesto di numerosi geni collegati alla riparazione dei tessuti, allo stress ossidativo e all'infiammazione. L'entità con cui questi effetti sull'espressione genica si trasferiscono agli esseri umani viventi è oggetto di ricerca in corso.","mechanismus_en":"Nelle cellule della pelle, GHK-Cu è stato descritto come aumentando la sintesi di collagene ed elastina e attivando i fibroblasti, le cellule che costruiscono il tessuto connettivo. Nei modelli preclinici di espressione genica, GHK-Cu ha mostrato una regolazione dipendente dal contesto di numerosi geni collegati alla riparazione dei tessuti, allo stress ossidativo e all'infiammazione. L'entità con cui questi effetti sull'espressione genica si trasferiscono agli esseri umani viventi è oggetto di ricerca in corso.","evidenz":[{"art":"clinico","kurz":"Uno studio di applicazione di dodici settimane in donne con segni visibili di invecchiamento cutaneo ha descritto un aumento dello spessore della pelle, una riduzione della profondità delle rughe e un aumento confermato da biopsia dell'attività delle cellule cutanee sotto una crema a GHK-Cu, rispetto alla linea di base.","kurz_en":"Uno studio di applicazione di dodici settimane in donne con segni visibili di invecchiamento cutaneo ha descritto un aumento dello spessore della pelle, una riduzione della profondità delle rughe e un aumento confermato da biopsia dell'attività delle cellule cutanee sotto una crema a GHK-Cu, rispetto alla linea di base.","quelle":"Finkley et al. 2005, in: Cosmeceuticals and Active Cosmetics: Drugs vs. Cosmetics"},{"art":"preclinico","kurz":"Uno studio in un modello murino di colite ulcerosa ha descritto GHK-Cu che supporta la funzione della barriera intestinale tramite la via SIRT1/STAT3 e riduce i messaggeri infiammatori.","kurz_en":"Uno studio in un modello murino di colite ulcerosa ha descritto GHK-Cu che supporta la funzione della barriera intestinale tramite la via SIRT1/STAT3 e riduce i messaggeri infiammatori.","quelle":"Mao et al. 2025, Frontiers in Pharmacology, PMID 40672369"}],"sicherheit":["Gli studi topici disponibili non hanno descritto preoccupazioni di sicurezza rilevanti.","GHK-Cu contiene rame legato, a concentrazioni cosmetiche tipiche questo non è associato a sovraccarico di rame.","Per l'uso iniettabile sistemico, non sono disponibili studi di sicurezza umana controllati con placebo.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"sicherheit_en":["Gli studi topici disponibili non hanno descritto preoccupazioni di sicurezza rilevanti.","GHK-Cu contiene rame legato, a concentrazioni cosmetiche tipiche questo non è associato a sovraccarico di rame.","Per l'uso iniettabile sistemico, non sono disponibili studi di sicurezza umana controllati con placebo.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Nelle formulazioni cosmetiche, il tripeptide di rame-1 è elencato come ingrediente cosmetico negli Stati Uniti. Nell'UE e in Germania, la forma di ricerca iniettabile si trova in una zona grigia legale e non è approvata come farmaco.","rechtsstatus_en":"Nelle formulazioni cosmetiche, il tripeptide di rame-1 è elencato come ingrediente cosmetico negli Stati Uniti. Nell'UE e in Germania, la forma di ricerca iniettabile si trova in una zona grigia legale e non è approvata come farmaco.","typischeMg":[],"faq":[{"q":"GHK-Cu è approvato in cosmetica?","a":"Negli Stati Uniti, il tripeptide di rame-1 è elencato come ingrediente cosmetico. L'UE non ha un'approvazione autonoma comparabile, sebbene i prodotti cosmetici siano ampiamente venduti.","q_en":"GHK-Cu è approvato in cosmetica?","a_en":"Negli Stati Uniti, il tripeptide di rame-1 è elencato come ingrediente cosmetico. L'UE non ha un'approvazione autonoma comparabile, sebbene i prodotti cosmetici siano ampiamente venduti."},{"q":"Dove si trova la prova più solida per GHK-Cu?","a":"I dati umani più robusti provengono dagli studi topici sulla pelle. L'uso sistemico iniettabile si basa principalmente su modelli animali e cellulari preclinici.","q_en":"Dove si trova la prova più solida per GHK-Cu?","a_en":"I dati umani più robusti provengono dagli studi topici sulla pelle. L'uso sistemico iniettabile si basa principalmente su modelli animali e cellulari preclinici."},{"q":"Il rame in GHK-Cu è un rischio per la sicurezza?","a":"A concentrazioni cosmetiche tipiche questo non è descritto come un rischio rilevante. La letteratura considera la carenza di rame più probabile del sovraccarico.","q_en":"Il rame in GHK-Cu è un rischio per la sicurezza?","a_en":"A concentrazioni cosmetiche tipiche questo non è descritto come un rischio rilevante. La letteratura considera la carenza di rame più probabile del sovraccarico."}],"seo":{"title":"GHK-Cu: profilo di ricerca ed evidenze","title_en":"GHK-Cu: profilo di ricerca ed evidenze","description":"Panoramica di GHK-Cu: tripeptide di rame, meccanismo, ricerca sulla pelle e profilo di sicurezza, presentati in modo fattuale per il contesto della ricerca.","description_en":"Panoramica di GHK-Cu: tripeptide di rame, meccanismo, ricerca sulla pelle e profilo di sicurezza, presentati in modo fattuale per il contesto della ricerca."},"demo":false,"steckbrief":{"cas":"89030-95-5","molekulargewicht":"402,92 g/mol","aminosaeuren":3,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale, polvere blu)","loeslichkeit":null,"sequenzLaenge":3,"quellen":["PubChem CID 71587328","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale, polvere blu)"},"verwandt":["bpc-157","tb-500","pentadeca-arginate"]},{"slug":"dihexa","name":"Dihexa","synonyme":["PNB-0408","N-Hexanoyl-Tyr-Ile-(6)aminoesanamide"],"kategorie":"Kognition","studienlage":"präklinisch","kurz":"Un analogo sintetico dell'angiotensina IV studiato in modelli preclinici di ratti della funzione della memoria, senza dati umani pubblicati a oggi.","kurz_en":"Un analogo sintetico dell'angiotensina IV studiato in modelli preclinici di ratti della funzione della memoria, senza dati umani pubblicati a oggi.","beschreibung":"Dihexa è un peptidomimetico sintetico derivato dall'angiotensina IV del corpo, sviluppato nel gruppo di ricerca di Joseph Harding presso la Washington State University. Ad oggi è stato studiato esclusivamente in modelli preclinici, principalmente ratti, in relazione alle prestazioni di apprendimento e memoria. Non esistono studi umani pubblicati per dihexa, quindi il suo profilo di sicurezza negli esseri umani non è stato esaminato.","beschreibung_en":"Dihexa è un peptidomimetico sintetico derivato dall'angiotensina IV del corpo, sviluppato nel gruppo di ricerca di Joseph Harding presso la Washington State University. Ad oggi è stato studiato esclusivamente in modelli preclinici, principalmente ratti, in relazione alle prestazioni di apprendimento e memoria. Non esistono studi umani pubblicati per dihexa, quindi il suo profilo di sicurezza negli esseri umani non è stato esaminato.","mechanismus":"Dihexa è descritto come un analogo metabolicamente stabilizzato dell'angiotensina IV che è disponibile per via orale e in grado di attraversare la barriera ematoencefalica. A differenza dell'angiotensina IV del corpo, è riportato in modelli cellulari che si lega direttamente al recettore del fattore di crescita dell'epatocita c-Met, attraverso il quale si ipotizza che inneschi la crescita dendritica e la sinaptogenesi. Parte del lavoro che originariamente supportava questo meccanismo è stato ritirato nel 2025 a causa di manipolazione delle immagini confermata, quindi il meccanismo d'azione preciso non può essere considerato scientificamente stabilito.","mechanismus_en":"Dihexa è descritto come un analogo metabolicamente stabilizzato dell'angiotensina IV che è disponibile per via orale e in grado di attraversare la barriera ematoencefalica. A differenza dell'angiotensina IV del corpo, è riportato in modelli cellulari che si lega direttamente al recettore del fattore di crescita dell'epatocita c-Met, attraverso il quale si ipotizza che inneschi la crescita dendritica e la sinaptogenesi. Parte del lavoro che originariamente supportava questo meccanismo è stato ritirato nel 2025 a causa di manipolazione delle immagini confermata, quindi il meccanismo d'azione preciso non può essere considerato scientificamente stabilito.","evidenz":[{"art":"preclinico","kurz":"Nei ratti, il dihexa somministrato per via orale (2 mg/kg) ha invertito i deficit di memoria indotti dalla scopolamina nel test del labirinto d'acqua di Morris e ha migliorato l'apprendimento negli animali di 24 mesi.","kurz_en":"Nei ratti, il dihexa somministrato per via orale (2 mg/kg) ha invertito i deficit di memoria indotti dalla scopolamina nel test del labirinto d'acqua di Morris e ha migliorato l'apprendimento negli animali di 24 mesi.","quelle":"McCoy AT et al. 2013, Journal of Pharmacology and Experimental Therapeutics, PMID 23055539 (This paper has carried an Expression of Concern from the publisher since 2021 over possible image manipulation, no retraction)"},{"art":"preclinico","kurz":"In un modello nel ratto di sintomi simili alla malattia di Huntington indotti da acido 3-nitropropionico, PNB-0408 (dihexa) non ha mostrato miglioramenti significativi negli endpoint motori o neuropatologici rispetto agli animali di controllo.","kurz_en":"In un modello nel ratto di sintomi simili alla malattia di Huntington indotti da acido 3-nitropropionico, PNB-0408 (dihexa) non ha mostrato miglioramenti significativi negli endpoint motori o neuropatologici rispetto agli animali di controllo.","quelle":"Wells RG et al. 2024, Journal of Huntington's Disease, Bd. 13, Nr. 1, S. 55-66, PMID 38489193"}],"sicherheit":["Non esistono studi umani pubblicati per dihexa e il suo profilo di sicurezza negli esseri umani non è stato esaminato.","Tutti i dati pubblicati a oggi provengono da modelli animali, principalmente ratti, con periodi di osservazione di solo poche settimane.","Uno studio del 2013 su analoghi metabolicamente stabilizzati dell'angiotensina IV ha avuto un commento di Espressione di Preoccupazione da parte dell'editoriale dal 2021 riguardo a possibile manipolazione delle immagini, senza che il documento sia stato ritirato.","Un articolo del 2014 sul meccanismo sottostante HGF/c-Met è stato formalmente ritirato nel 2025 dopo un'indagine che ha confermato figure falsificate e manipolate.","I dati di sicurezza a lungo termine, inclusi quelli dagli studi sugli animali, non sono ancora disponibili."],"sicherheit_en":["Non esistono studi umani pubblicati per dihexa e il suo profilo di sicurezza negli esseri umani non è stato esaminato.","Tutti i dati pubblicati a oggi provengono da modelli animali, principalmente ratti, con periodi di osservazione di solo poche settimane.","Uno studio del 2013 su analoghi metabolicamente stabilizzati dell'angiotensina IV ha avuto un commento di Espressione di Preoccupazione da parte dell'editoriale dal 2021 riguardo a possibile manipolazione delle immagini, senza che il documento sia stato ritirato.","Un articolo del 2014 sul meccanismo sottostante HGF/c-Met è stato formalmente ritirato nel 2025 dopo un'indagine che ha confermato figure falsificate e manipolate.","I dati di sicurezza a lungo termine, inclusi quelli dagli studi sugli animali, non sono ancora disponibili."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Dihexa non è mai entrato in un processo di approvazione clinica per l'uso umano e non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti. Viene venduto esclusivamente come sostanza di ricerca per uso di laboratorio.","rechtsstatus_en":"Dihexa non è mai entrato in un processo di approvazione clinica per l'uso umano e non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti. Viene venduto esclusivamente come sostanza di ricerca per uso di laboratorio.","typischeMg":[],"faq":[{"q":"Ci sono studi umani su dihexa","a":"No. Tutti i dati pubblicati su dihexa fino ad oggi provengono da modelli animali, principalmente ratti. Un profilo di sicurezza per l'uso umano non è stato esaminato, quindi non esistono dati su tollerabilità o efficacia negli esseri umani.","q_en":"Ci sono studi umani su dihexa","a_en":"No. Tutti i dati pubblicati su dihexa fino ad oggi provengono da modelli animali, principalmente ratti. Un profilo di sicurezza per l'uso umano non è stato esaminato, quindi non esistono dati su tollerabilità o efficacia negli esseri umani."},{"q":"Come è spiegato il meccanismo d'azione di dihexa","a":"Si riporta che dihexa si leghi al recettore del fattore di crescita dell'epatocita c-Met, una via proposta per innescare la sinaptogenesi in modelli cellulari. Parte del lavoro che originariamente supportava questo meccanismo è stato ritirato nel 2025 a causa di dati falsificati.","q_en":"Come è spiegato il meccanismo d'azione di dihexa","a_en":"Si riporta che dihexa si leghi al recettore del fattore di crescita dell'epatocita c-Met, una via proposta per innescare la sinaptogenesi in modelli cellulari. Parte del lavoro che originariamente supportava questo meccanismo è stato ritirato nel 2025 a causa di dati falsificati."},{"q":"Dihexa è un farmaco approvato","a":"No. Dihexa non è mai entrato in un processo di approvazione clinica per l'uso umano e non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti. Viene venduto esclusivamente come composto di ricerca.","q_en":"Dihexa è un farmaco approvato","a_en":"No. Dihexa non è mai entrato in un processo di approvazione clinica per l'uso umano e non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti. Viene venduto esclusivamente come composto di ricerca."}],"seo":{"title":"Dihexa: Stato di ricerca dell'analogo dell'Angiotensina IV","title_en":"Dihexa: Stato di ricerca dell'analogo dell'Angiotensina IV","description":"Dihexa spiegato in modo fattuale: origine, meccanismo d'azione, stato degli studi preclinici e questioni di sicurezza aperte riguardanti questo peptide di ricerca.","description_en":"Dihexa spiegato in modo fattuale: origine, meccanismo d'azione, stato degli studi preclinici e questioni di sicurezza aperte riguardanti questo peptide di ricerca."},"demo":false,"steckbrief":{"cas":"1401708-83-5","molekulargewicht":"504,7 g/mol","aminosaeuren":2,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":2,"quellen":["PubChem CID 129010512","chemverify Katalog 14.09.2026"]},"verwandt":["semax","selank","dsip"]},{"slug":"dsip","name":"DSIP","synonyme":["Peptide induttore del sonno Delta","Peptide del sonno Delta"],"kategorie":"Kognition","studienlage":"klinisch untersucht","kurz":"Uno dei neuropeptidi più studiati, originariamente isolato come messaggero induttore del sonno dal cervello di conigli dormienti, con un corpo di ricerca incoerente fino ad oggi.","kurz_en":"Uno dei neuropeptidi più studiati, originariamente isolato come messaggero induttore del sonno dal cervello di conigli dormienti, con un corpo di ricerca incoerente fino ad oggi.","beschreibung":"DSIP (peptide induttore del sonno delta) è un nonapeptide isolato per la prima volta nel 1977 da Schoenenberger e Monnier dal sangue cerebrale venoso di conigli dormienti e denominato per la sua capacità di innescare attività EEG a onde delta in quel modello animale. Negli anni successivi è stato studiato in numerosi trial umani sul sonno, l'asse dello stress e la regolazione ormonale. L'effetto favorente il sonno descritto originariamente non è stato riprodotto in modo affidabile in studi indipendenti e più rigorosi.","beschreibung_en":"DSIP (peptide induttore del sonno delta) è un nonapeptide isolato per la prima volta nel 1977 da Schoenenberger e Monnier dal sangue cerebrale venoso di conigli dormienti e denominato per la sua capacità di innescare attività EEG a onde delta in quel modello animale. Negli anni successivi è stato studiato in numerosi trial umani sul sonno, l'asse dello stress e la regolazione ormonale. L'effetto favorente il sonno descritto originariamente non è stato riprodotto in modo affidabile in studi indipendenti e più rigorosi.","mechanismus":"Il meccanismo d'azione preciso di DSIP rimane irrisolto nonostante decenni di ricerca. L'implicazione proposta include un ruolo nella regolazione dell'asse ipotalamo-ipofisi-surrene e interazioni con le vie di segnalazione GABAergica e oppioide. Ad oggi non è stato descritto un recettore specifico e chiaramente identificato per DSIP, il che complica l'interpretazione dei suoi effetti.","mechanismus_en":"Il meccanismo d'azione preciso di DSIP rimane irrisolto nonostante decenni di ricerca. L'implicazione proposta include un ruolo nella regolazione dell'asse ipotalamo-ipofisi-surrene e interazioni con le vie di segnalazione GABAergica e oppioide. Ad oggi non è stato descritto un recettore specifico e chiaramente identificato per DSIP, il che complica l'interpretazione dei suoi effetti.","evidenz":[{"art":"preclinico","kurz":"L'isolamento originale dal sangue cerebrale di conigli dormienti ha identificato la sequenza del nonapeptide e ha mostrato un aumento dell'attività EEG a onde delta nel modello animale dopo somministrazione intraventricolare.","kurz_en":"L'isolamento originale dal sangue cerebrale di conigli dormienti ha identificato la sequenza del nonapeptide e ha mostrato un aumento dell'attività EEG a onde delta nel modello animale dopo somministrazione intraventricolare.","quelle":"Schoenenberger GA, Monnier M 1977, Proceedings of the National Academy of Sciences, Bd. 74(3), S. 1282-1286, PMID 265572"},{"art":"clinico","kurz":"In uno studio crossover in doppio cieco su pazienti con insonnia cronica con monitoraggio polisomnografico per quattro notti, il miglioramento del sonno sotto DSIP è stato minimo rispetto al placebo.","kurz_en":"In uno studio crossover in doppio cieco su pazienti con insonnia cronica con monitoraggio polisomnografico per quattro notti, il miglioramento del sonno sotto DSIP è stato minimo rispetto al placebo.","quelle":"Monti JM et al. 1987, International Journal of Clinical Pharmacology Research, Bd. 7(2), S. 105-110, PMID 3583493"},{"art":"clinico","kurz":"Una revisione che riassume tre decenni di ricerca umana e animale conclude che l'effetto induttore del sonno di DSIP originariamente postulato non è stato confermato in modo coerente in studi indipendenti.","kurz_en":"Una revisione che riassume tre decenni di ricerca umana e animale conclude che l'effetto induttore del sonno di DSIP originariamente postulato non è stato confermato in modo coerente in studi indipendenti.","quelle":"Kovalzon VM, Strekalova TV 2006, Journal of Neurochemistry, Bd. 97(2), S. 303-309, PMID 16539679"},{"art":"preclinico","kurz":"Uno studio preclinico del 2024 ha esaminato un peptide fusione DSIP in un modello murino di insonnia indotta farmacologicamente e ha descritto effetti sui livelli di neurotrasmettitori come serotonina e dopamina.","kurz_en":"Uno studio preclinico del 2024 ha esaminato un peptide fusione DSIP in un modello murino di insonnia indotta farmacologicamente e ha descritto effetti sui livelli di neurotrasmettitori come serotonina e dopamina.","quelle":"Mu X et al. 2024, Frontiers in Pharmacology, Bd. 15, Artikel 1439536, PMID 39444618"}],"sicherheit":["L'effetto promosse del sonno descritto negli studi umani più vecchi non è considerato riproducibile in modo affidabile, secondo la letteratura di revisione attuale.","Molti degli studi umani disponibili risalgono agli anni 1980 e mostrano debolezze metodologiche come piccoli campioni e brevi periodi di osservazione.","In uno studio su volontari sani, l'infusione di DSIP non ha alterato misurabilmente la secrezione di ACTH e cortisolo stimolati da CRH.","Non sono disponibili dati di sicurezza umani a lungo termine riprodotti indipendentemente."],"sicherheit_en":["L'effetto promosse del sonno descritto negli studi umani più vecchi non è considerato riproducibile in modo affidabile, secondo la letteratura di revisione attuale.","Molti degli studi umani disponibili risalgono agli anni 1980 e mostrano debolezze metodologiche come piccoli campioni e brevi periodi di osservazione.","In uno studio su volontari sani, l'infusione di DSIP non ha alterato misurabilmente la secrezione di ACTH e cortisolo stimolati da CRH.","Non sono disponibili dati di sicurezza umani a lungo termine riprodotti indipendentemente."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"DSIP non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti, dove è venduto esclusivamente come sostanza chimica di ricerca.","rechtsstatus_en":"DSIP non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti, dove è venduto esclusivamente come sostanza chimica di ricerca.","typischeMg":[5,10],"faq":[{"q":"L'effetto di DSIP favorente il sonno è stato confermato in studi","a":"Le evidenze sono incoerenti. Studi iniziali hanno riportato effetti favorenti il sonno, ma una revisione del 2006 ha concluso che questo effetto non può essere riprodotto in modo coerente in studi indipendenti.","q_en":"L'effetto di DSIP favorente il sonno è stato confermato in studi","a_en":"Le evidenze sono incoerenti. Studi iniziali hanno riportato effetti favorenti il sonno, ma una revisione del 2006 ha concluso che questo effetto non può essere riprodotto in modo coerente in studi indipendenti."},{"q":"Da dove viene il nome DSIP","a":"DSIP sta per peptide induttore del sonno delta. Il nome risale alla sua prima descrizione nel 1977, quando è stato isolato dal sangue cerebrale di conigli dormienti e ha innescato attività EEG a onde delta in quel modello animale.","q_en":"Da dove viene il nome DSIP","a_en":"DSIP sta per peptide induttore del sonno delta. Il nome risale alla sua prima descrizione nel 1977, quando è stato isolato dal sangue cerebrale di conigli dormienti e ha innescato attività EEG a onde delta in quel modello animale."},{"q":"DSIP è legalmente disponibile in Germania","a":"DSIP non è approvato come farmaco in Germania o nell'UE. Viene offerto esclusivamente come sostanza chimica di ricerca per scopi di laboratorio, non per uso umano.","q_en":"DSIP è legalmente disponibile in Germania","a_en":"DSIP non è approvato come farmaco in Germania o nell'UE. Viene offerto esclusivamente come sostanza chimica di ricerca per scopi di laboratorio, non per uso umano."}],"seo":{"title":"DSIP: Peptide di Ricerca con Evidenze Incoerenti","title_en":"DSIP: Peptide di Ricerca con Evidenze Incoerenti","description":"DSIP in sintesi: origine, meccanismo, stato degli studi e profilo di sicurezza di uno dei peptidi del sonno più studiati.","description_en":"DSIP in sintesi: origine, meccanismo, stato degli studi e profilo di sicurezza di uno dei peptidi del sonno più studiati."},"demo":false,"steckbrief":{"cas":"62568-57-4","molekulargewicht":"848,8 g/mol","aminosaeuren":9,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":9,"quellen":["PubChem CID 68816","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)"},"verwandt":["selank","semax","dihexa"]},{"slug":"selank","name":"Selank","synonyme":[],"kategorie":"Kognition","studienlage":"klinisch untersucht","kurz":"Un analogo heptapeptide sintetico del tuftsin proprio del corpo, studiato in ricerche sulla regolazione dell'ansia e sulla funzione cognitiva.","kurz_en":"Un analogo heptapeptide sintetico del tuftsin proprio del corpo, studiato in ricerche sulla regolazione dell'ansia e sulla funzione cognitiva.","beschreibung":"Selank è un heptapeptide derivato dal tuftsin tetrapeptide proprio del corpo, originariamente sviluppato in Russia come ansiolitico. La ricerca lo collega a effetti regolatori dell'ansia e a effetti lievemente supportanti della cognizione, senza la sedazione tipica delle benzodiazepine.","beschreibung_en":"Selank è un heptapeptide derivato dal tuftsin tetrapeptide proprio del corpo, originariamente sviluppato in Russia come ansiolitico. La ricerca lo collega a effetti regolatori dell'ansia e a effetti lievemente supportanti della cognizione, senza la sedazione tipica delle benzodiazepine.","mechanismus":"Selank è descritto come inibitore delle enkephalinasi, gli enzimi che degradano le encefaline del corpo, mantenendone i livelli elevati più a lungo. È anche collegato alla modulazione del recettore GABA in un sito di legame distinto da quello delle benzodiazepine, e a effetti indiretti sul sistema dopaminergico attraverso la via enkefalina.","mechanismus_en":"Selank è descritto come inibitore delle enkephalinasi, gli enzimi che degradano le encefaline del corpo, mantenendone i livelli elevati più a lungo. È anche collegato alla modulazione del recettore GABA in un sito di legame distinto da quello delle benzodiazepine, e a effetti indiretti sul sistema dopaminergico attraverso la via enkefalina.","evidenz":[{"art":"clinico","kurz":"Uno studio randomizzato su 62 persone con disturbo d'ansia generalizzato o neurastenia ha confrontato l'effetto ansiolitico di selank con medazepam, con miglioramenti osservati aggiuntivi di energia e concentrazione senza sedazione.","kurz_en":"Uno studio randomizzato su 62 persone con disturbo d'ansia generalizzato o neurastenia ha confrontato l'effetto ansiolitico di selank con medazepam, con miglioramenti osservati aggiuntivi di energia e concentrazione senza sedazione.","quelle":"Zozulya AA et al. 2008, Bjulleten Eksperimentalnoj Biologii i Mediciny, PMID 18454096"},{"art":"clinico","kurz":"In uno studio fMRI con 52 partecipanti sani, l'somministrazione di selank è stata associata a alterazioni della connettività funzionale tra l'amigdala destra e la corteccia temporale destra, misurabili già a 5 minuti dopo l'applicazione.","kurz_en":"In uno studio fMRI con 52 partecipanti sani, l'somministrazione di selank è stata associata a alterazioni della connettività funzionale tra l'amigdala destra e la corteccia temporale destra, misurabili già a 5 minuti dopo l'applicazione.","quelle":"Panikratova KR et al. 2020, Doklady Biological Sciences, Bd. 490, S. 9-11"}],"sicherheit":["La letteratura degli studi disponibili descrive effetti lievi e transitori come irritazione nasale con uso intranasale.","L'uso concomitante con benzodiazepine è discusso nella letteratura a causa di possibile interazione reciproca dei recettori.","Dati di sicurezza a lungo termine robusti da studi indipendenti condotti al di fuori della Russia non sono ancora disponibili."],"sicherheit_en":["La letteratura degli studi disponibili descrive effetti lievi e transitori come irritazione nasale con uso intranasale.","L'uso concomitante con benzodiazepine è discusso nella letteratura a causa di possibile interazione reciproca dei recettori.","Dati di sicurezza a lungo termine robusti da studi indipendenti condotti al di fuori della Russia non sono ancora disponibili."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Selank è approvato come ansiolitico in Russia, ma non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti, dove è venduto esclusivamente come sostanza chimica di ricerca.","rechtsstatus_en":"Selank è approvato come ansiolitico in Russia, ma non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti, dove è venduto esclusivamente come sostanza chimica di ricerca.","typischeMg":[5,10],"faq":[{"q":"Selank è la stessa cosa di una benzodiazepina?","a":"No. Entrambi agiscono sul sistema GABA in modi diversi. Selank si lega in un sito diverso e non ha mostrato potenziale sedativo o di dipendenza negli studi, a differenza delle benzodiazepine classiche.","q_en":"Selank è la stessa cosa di una benzodiazepina?","a_en":"No. Entrambi agiscono sul sistema GABA in modi diversi. Selank si lega in un sito diverso e non ha mostrato potenziale sedativo o di dipendenza negli studi, a differenza delle benzodiazepine classiche."},{"q":"Da dove proviene selank?","a":"Selank è stato sviluppato all'Accademia Russa delle Scienze dal tuftsin peptidico del corpo, con un'aggiunta stabilizzante per una durata più lunga nel corpo.","q_en":"Da dove proviene selank?","a_en":"Selank è stato sviluppato all'Accademia Russa delle Scienze dal tuftsin peptidico del corpo, con un'aggiunta stabilizzante per una durata più lunga nel corpo."},{"q":"Selank è legalmente disponibile in Germania?","a":"Selank non è approvato come farmaco in Germania o nell'UE. Viene offerto esclusivamente come sostanza chimica di ricerca per scopi di laboratorio, non per uso umano.","q_en":"Selank è legalmente disponibile in Germania?","a_en":"Selank non è approvato come farmaco in Germania o nell'UE. Viene offerto esclusivamente come sostanza chimica di ricerca per scopi di laboratorio, non per uso umano."}],"seo":{"title":"Selank: Peptide di Ricerca per la Regolazione dell'Ansia","title_en":"Selank: Peptide di Ricerca per la Regolazione dell'Ansia","description":"Selank in sintesi: origine, meccanismo, stato degli studi e profilo di sicurezza di un peptide di ricerca studiato per la regolazione dell'ansia e della cognizione.","description_en":"Selank in sintesi: origine, meccanismo, stato degli studi e profilo di sicurezza di un peptide di ricerca studiato per la regolazione dell'ansia e della cognizione."},"demo":false,"steckbrief":{"cas":"129954-34-3","molekulargewicht":"751,9 g/mol","aminosaeuren":7,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 11765600","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)"},"verwandt":["semax","epitalon","dihexa"]},{"slug":"semax","name":"Semax","synonyme":[],"kategorie":"Kognition","studienlage":"klinisch untersucht","kurz":"Un heptapeptide derivato da ACTH sintetico, approvato in Russia per la neuroprotezione e studiato in ricerca sulla cognizione e adattamento allo stress.","kurz_en":"Un heptapeptide derivato da ACTH sintetico, approvato in Russia per la neuroprotezione e studiato in ricerca sulla cognizione e adattamento allo stress.","beschreibung":"Semax è un heptapeptide derivato dal frammento ACTH(4-10) dell'ormone dello stress ACTH, approvato come farmaco per ictus ischemico in Russia. La ricerca l'esamina anche in relazione alla neuroplasticità e alla funzione cognitiva, senza attivare l'asse del cortisolo.","beschreibung_en":"Semax è un heptapeptide derivato dal frammento ACTH(4-10) dell'ormone dello stress ACTH, approvato come farmaco per ictus ischemico in Russia. La ricerca l'esamina anche in relazione alla neuroplasticità e alla funzione cognitiva, senza attivare l'asse del cortisolo.","mechanismus":"Semax è descritto come potenziatore di BDNF e del suo recettore TrkB, collegato alla plasticità neuronale. Come derivato dell'ACTH, si lega anche ai recettori della melanocortina, che possono influenzare i livelli di dopamina, serotonina e noradrenalina. Il legame al recettore mu-oppioide, descritto nel 2025, è stato collegato a effetti antiossidanti.","mechanismus_en":"Semax è descritto come potenziatore di BDNF e del suo recettore TrkB, collegato alla plasticità neuronale. Come derivato dell'ACTH, si lega anche ai recettori della melanocortina, che possono influenzare i livelli di dopamina, serotonina e noradrenalina. Il legame al recettore mu-oppioide, descritto nel 2025, è stato collegato a effetti antiossidanti.","evidenz":[{"art":"preclinico","kurz":"In uno studio sul ratto, una singola applicazione intranasale di semax ha aumentato di 1,4 volte i livelli proteici di BDNF nell'ippocampo e di 1,6 volte la fosforilazione di TrkB.","kurz_en":"In uno studio sul ratto, una singola applicazione intranasale di semax ha aumentato di 1,4 volte i livelli proteici di BDNF nell'ippocampo e di 1,6 volte la fosforilazione di TrkB.","quelle":"PubMed ID 14556513"},{"art":"clinico","kurz":"Nello stesso studio fMRI con 52 partecipanti sani, semax ha mostrato una connettività funzionale alterata tra l'amigdala e la corteccia temporale, con effetti in parte distinguibili da selank.","kurz_en":"Nello stesso studio fMRI con 52 partecipanti sani, semax ha mostrato una connettività funzionale alterata tra l'amigdala e la corteccia temporale, con effetti in parte distinguibili da selank.","quelle":"Panikratova KR et al. 2020, Doklady Biological Sciences, Bd. 490, S. 9-11"}],"sicherheit":["Gli studi sugli animali hanno finora riportato nessun effetto tossico grave.","È stata descritta un'interazione in vitro con enzimi dipendenti dal rame, la sua rilevanza clinica non è ancora stabilita.","I dati di sicurezza umana a lungo termine indipendenti sono ancora non disponibili."],"sicherheit_en":["Gli studi sugli animali hanno finora riportato nessun effetto tossico grave.","È stata descritta un'interazione in vitro con enzimi dipendenti dal rame, la sua rilevanza clinica non è ancora stabilita.","I dati di sicurezza umana a lungo termine indipendenti sono ancora non disponibili."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Semax è approvato come farmaco per la neuroprotezione in Russia, ma non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti, dove è venduto esclusivamente come sostanza chimica di ricerca.","rechtsstatus_en":"Semax è approvato come farmaco per la neuroprotezione in Russia, ma non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti, dove è venduto esclusivamente come sostanza chimica di ricerca.","typischeMg":[10,30],"faq":[{"q":"Semax agisce come un nootropico classico?","a":"La ricerca collega principalmente semax a effetti neuroprotettivi e correlati a BDNF, meno a un effetto di focus acuto come gli stimolanti classici.","q_en":"Semax agisce come un nootropico classico?","a_en":"La ricerca collega principalmente semax a effetti neuroprotettivi e correlati a BDNF, meno a un effetto di focus acuto come gli stimolanti classici."},{"q":"Semax è lo stesso di selank?","a":"No, entrambi sono peptidi russi correlati con origini diverse. Semax deriva dall'ACTH ed è principalmente collegato alla neuroprotezione, selank da tuftina ed è principalmente collegato alla regolazione dell'ansia.","q_en":"Semax è lo stesso di selank?","a_en":"No, entrambi sono peptidi russi correlati con origini diverse. Semax deriva dall'ACTH ed è principalmente collegato alla neuroprotezione, selank da tuftina ed è principalmente collegato alla regolazione dell'ansia."},{"q":"Semax è legalmente disponibile in Germania?","a":"Semax non è approvato come farmaco in Germania o nell'UE ed è offerto esclusivamente come sostanza chimica di ricerca per scopi di laboratorio, non per uso umano.","q_en":"Semax è legalmente disponibile in Germania?","a_en":"Semax non è approvato come farmaco in Germania o nell'UE ed è offerto esclusivamente come sostanza chimica di ricerca per scopi di laboratorio, non per uso umano."}],"seo":{"title":"Semax: Peptide di Ricerca ACTH per la Neuroprotezione","title_en":"Semax: Peptide di Ricerca ACTH per la Neuroprotezione","description":"Semax in sintesi: origine, meccanismo, stato dello studio e profilo di sicurezza di un peptide di ricerca studiato per la neuroprotezione e la cognizione.","description_en":"Semax in sintesi: origine, meccanismo, stato dello studio e profilo di sicurezza di un peptide di ricerca studiato per la neuroprotezione e la cognizione."},"demo":false,"steckbrief":{"cas":"80714-61-0","molekulargewicht":"813,9 g/mol","aminosaeuren":7,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 9811102","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)"},"verwandt":["selank","epitalon","dsip"]},{"slug":"kpv","name":"KPV","synonyme":["Lys-Pro-Val","alpha-MSH(11-13)"],"kategorie":"Immunsystem","studienlage":"präklinisch","kurz":"Un frammento a tre amminoacidi di alfa-MSH, studiato in modelli animali per proprietà antinfiammatorie nell'intestino e sulla pelle.","kurz_en":"Un frammento a tre amminoacidi di alfa-MSH, studiato in modelli animali per proprietà antinfiammatorie nell'intestino e sulla pelle.","beschreibung":"KPV è un tripeptide formato dagli amminoacidi lisina, prolina e valina, derivato dall'estremità C-terminale dell'ormone alfa-MSH. È tra i peptidi più piccoli studiati nella ricerca sull'infiammazione, con un focus sui modelli animali di malattia infiammatoria intestinale cronica e infiammazione cutanea. Studi sull'uomo non sono ancora disponibili.","beschreibung_en":"KPV è un tripeptide formato dagli amminoacidi lisina, prolina e valina, derivato dall'estremità C-terminale dell'ormone alfa-MSH. È tra i peptidi più piccoli studiati nella ricerca sull'infiammazione, con un focus sui modelli animali di malattia infiammatoria intestinale cronica e infiammazione cutanea. Studi sull'uomo non sono ancora disponibili.","mechanismus":"Nei modelli preclinici viene descritto un effetto antinfiammatorio che agisce indipendentemente dal recettore della melanocortina e si basa invece sull'assorbimento nelle cellule intestinali tramite il trasportatore peptidico PepT1. Viene descritta l'inibizione dell'attivazione di NF-κB, un interruttore centrale della risposta infiammatoria. I meccanismi esatti negli esseri umani non sono stati studiati.","mechanismus_en":"Nei modelli preclinici viene descritto un effetto antinfiammatorio che agisce indipendentemente dal recettore della melanocortina e si basa invece sull'assorbimento nelle cellule intestinali tramite il trasportatore peptidico PepT1. Viene descritta l'inibizione dell'attivazione di NF-κB, un interruttore centrale della risposta infiammatoria. I meccanismi esatti negli esseri umani non sono stati studiati.","evidenz":[{"art":"preclinico","kurz":"Uno studio su due modelli murini di colite ha descritto un recupero più rapido del peso corporeo e una riduzione marcata degli infiltrati infiammatori nel tessuto intestinale sotto KPV rispetto agli animali non trattati.","kurz_en":"Uno studio su due modelli murini di colite ha descritto un recupero più rapido del peso corporeo e una riduzione marcata degli infiltrati infiammatori nel tessuto intestinale sotto KPV rispetto agli animali non trattati.","quelle":"Kannengiesser et al. 2008, Inflammatory Bowel Diseases, PMID 18092346"},{"art":"preclinico","kurz":"Uno studio ha mostrato che l'effetto antinfiammatorio di KPV nel modello murino è mediato tramite assorbimento tramite il trasportatore peptidico PepT1 piuttosto che il recettore della melanocortina.","kurz_en":"Uno studio ha mostrato che l'effetto antinfiammatorio di KPV nel modello murino è mediato tramite assorbimento tramite il trasportatore peptidico PepT1 piuttosto che il recettore della melanocortina.","quelle":"Dalmasso et al. 2008, Gastroenterology, PMID 18061177"},{"art":"preclinico","kurz":"Uno studio che utilizza nanoparticelle funzionalizzate con acido ialuronico per il rilascio orale mirato di KPV nel colon ha descritto una riduzione significativa dell'infiammazione nei topi con colite rispetto a KPV non trattato.","kurz_en":"Uno studio che utilizza nanoparticelle funzionalizzate con acido ialuronico per il rilascio orale mirato di KPV nel colon ha descritto una riduzione significativa dell'infiammazione nei topi con colite rispetto a KPV non trattato.","quelle":"Xiao et al. 2017, Molecular Therapy, PMID 28143741"}],"sicherheit":["Studi sulla sicurezza umana di KPV non sono ancora disponibili, tutte le evidenze provengono da modelli cellulari e animali.","Nessun effetto avverso grave è stato riportato negli studi sugli animali disponibili.","Le interazioni con altre sostanze non sono state studiate negli esseri umani.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"sicherheit_en":["Studi sulla sicurezza umana di KPV non sono ancora disponibili, tutte le evidenze provengono da modelli cellulari e animali.","Nessun effetto avverso grave è stato riportato negli studi sugli animali disponibili.","Le interazioni con altre sostanze non sono state studiate negli esseri umani.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"KPV non è autorizzato come farmaco in Germania, nell’UE o negli Stati Uniti e non è classificato come prodotto alimentare. È venduto esclusivamente come sostanza chimica per la ricerca.","rechtsstatus_en":"KPV non è autorizzato come farmaco in Germania, nell’UE o negli Stati Uniti e non è classificato come prodotto alimentare. È venduto esclusivamente come sostanza chimica per la ricerca.","typischeMg":[],"faq":[{"q":"Da dove proviene KPV?","a":"KPV è un frammento dell'ormone alfa-MSH, formato dagli amminoacidi lisina, prolina e valina.","q_en":"Da dove proviene KPV?","a_en":"KPV è un frammento dell'ormone alfa-MSH, formato dagli amminoacidi lisina, prolina e valina."},{"q":"KPV agisce attraverso il recettore della melanocortina?","a":"No. Nei modelli animali, l'effetto antinfiammatorio è descritto indipendentemente dal recettore della melanocortina, basandosi invece sul trasportatore PepT1.","q_en":"KPV agisce attraverso il recettore della melanocortina?","a_en":"No. Nei modelli animali, l'effetto antinfiammatorio è descritto indipendentemente dal recettore della melanocortina, basandosi invece sul trasportatore PepT1."},{"q":"Ci sono studi sull'uomo su KPV?","a":"No, ad oggi esistono solo studi cellulari e su animali, principalmente sulla malattia infiammatoria intestinale.","q_en":"Ci sono studi sull'uomo su KPV?","a_en":"No, ad oggi esistono solo studi cellulari e su animali, principalmente sulla malattia infiammatoria intestinale."}],"seo":{"title":"KPV: profilo di ricerca ed evidenze","title_en":"KPV: profilo di ricerca ed evidenze","description":"Panoramica KPV: origine da alpha-MSH, meccanismo, evidenze precliniche e profilo di sicurezza, presentate in modo fattuale per il contesto della ricerca.","description_en":"Panoramica KPV: origine da alpha-MSH, meccanismo, evidenze precliniche e profilo di sicurezza, presentate in modo fattuale per il contesto della ricerca."},"demo":false,"steckbrief":{"cas":"67727-97-3","molekulargewicht":"342,43 g/mol","aminosaeuren":3,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":3,"quellen":["PubChem CID 125672","chemverify Katalog 14.09.2026"]},"verwandt":["ll-37","thymosin-alpha-1","bpc-157"]},{"slug":"ll-37","name":"LL-37","synonyme":["Catelicidina","hCAP18(134-170)","Catelicidina umana"],"kategorie":"Immunsystem","studienlage":"klinisch untersucht","kurz":"Un peptide antimicrobico di origine naturale composto da 37 aminoacidi che protegge la pelle e le membrane mucose, studiato in trial clinici per la guarigione delle ferite.","kurz_en":"Un peptide antimicrobico di origine naturale composto da 37 aminoacidi che protegge la pelle e le membrane mucose, studiato in trial clinici per la guarigione delle ferite.","beschreibung":"LL-37 è l'unico membro noto della famiglia dei peptidi catelicidina negli esseri umani e viene prodotto dalle cellule immunitarie nonché dalle cellule cutanee e mucosali in risposta a lesioni o infezioni. Viene generato dal clivaggio dalla proteina precursore hCAP18. La ricerca clinica si è concentrata principalmente sull'applicazione topica per ferite difficili da guarire, come le ulcere delle gambe venose e le ulcere del piede diabetico.","beschreibung_en":"LL-37 è l'unico membro noto della famiglia dei peptidi catelicidina negli esseri umani e viene prodotto dalle cellule immunitarie nonché dalle cellule cutanee e mucosali in risposta a lesioni o infezioni. Viene generato dal clivaggio dalla proteina precursore hCAP18. La ricerca clinica si è concentrata principalmente sull'applicazione topica per ferite difficili da guarire, come le ulcere delle gambe venose e le ulcere del piede diabetico.","mechanismus":"LL-37 si inserisce nelle membrane cellulari batteriche e ne interrompe l'integrità, producendo un effetto antimicrobico diretto contro una vasta gamma di patogeni. Sono descritti effetti immunomodulatori aggiuntivi, inclusa l'reclutamento di cellule immunitarie nel sito della ferita e la promozione dell'angiogenesi. La produzione endogena può essere potenziata da certi stimoli come analoghi della vitamina D.","mechanismus_en":"LL-37 si inserisce nelle membrane cellulari batteriche e ne interrompe l'integrità, producendo un effetto antimicrobico diretto contro una vasta gamma di patogeni. Sono descritti effetti immunomodulatori aggiuntivi, inclusa l'reclutamento di cellule immunitarie nel sito della ferita e la promozione dell'angiogenesi. La produzione endogena può essere potenziata da certi stimoli come analoghi della vitamina D.","evidenz":[{"art":"clinico","kurz":"Uno studio randomizzato controllato con placebo in primo essere umano su 34 pazienti con ulcere delle gambe venose difficili da guarire ha descritto un tasso di guarigione approssimativamente 3-6 volte più rapido sotto le due concentrazioni inferiori di LL-37 rispetto al placebo.","kurz_en":"Uno studio randomizzato controllato con placebo in primo essere umano su 34 pazienti con ulcere delle gambe venose difficili da guarire ha descritto un tasso di guarigione approssimativamente 3-6 volte più rapido sotto le due concentrazioni inferiori di LL-37 rispetto al placebo.","quelle":"Grönberg et al. 2014, Wound Repair and Regeneration, PMID 25041740"},{"art":"clinico","kurz":"Uno studio randomizzato in doppio cieco in pazienti con ulcere del piede diabetico ha esaminato una crema contenente LL-37 e ha descritto gli effetti sulla colonizzazione batterica, sui marcatori infiammatori e sul tasso di guarigione rispetto al placebo.","kurz_en":"Uno studio randomizzato in doppio cieco in pazienti con ulcere del piede diabetico ha esaminato una crema contenente LL-37 e ha descritto gli effetti sulla colonizzazione batterica, sui marcatori infiammatori e sul tasso di guarigione rispetto al placebo.","quelle":"Miranda et al. 2023, Archives of Dermatological Research, PMID 37480520"},{"art":"clinico","kurz":"Uno studio sulla pelle umana ha descritto che la produzione endogena di hCAP18/LL-37 aumenta dopo una lesione e può essere ulteriormente potenziata dall'applicazione topica dell'analogo della vitamina D calcipotriolo.","kurz_en":"Uno studio sulla pelle umana ha descritto che la produzione endogena di hCAP18/LL-37 aumenta dopo una lesione e può essere ulteriormente potenziata dall'applicazione topica dell'analogo della vitamina D calcipotriolo.","quelle":"Heilborn et al. 2010, Experimental Dermatology, PMID 19878298"}],"sicherheit":["Nei trial randomizzati disponibili, l'applicazione topica di LL-37 è stata descritta come sicura e ben tollerata, senza eventi avversi gravi.","Le popolazioni degli studi erano ciascuna piccole, gli studi controllati con placebo più grandi con più partecipanti sono ancora in sospeso.","Le forme di applicazione sistemica e la sicurezza umana a lungo termine non sono state studiate a un livello comparabile all'uso topico.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"sicherheit_en":["Nei trial randomizzati disponibili, l'applicazione topica di LL-37 è stata descritta come sicura e ben tollerata, senza eventi avversi gravi.","Le popolazioni degli studi erano ciascuna piccole, gli studi controllati con placebo più grandi con più partecipanti sono ancora in sospeso.","Le forme di applicazione sistemica e la sicurezza umana a lungo termine non sono state studiate a un livello comparabile all'uso topico.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"LL-37 non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti, e non è classificato come prodotto alimentare. Viene venduto esclusivamente come prodotto chimico di ricerca, le formulazioni di LL-37 in fase di indagine clinica sono legate a programmi di studio individuali.","rechtsstatus_en":"LL-37 non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti, e non è classificato come prodotto alimentare. Viene venduto esclusivamente come prodotto chimico di ricerca, le formulazioni di LL-37 in fase di indagine clinica sono legate a programmi di studio individuali.","typischeMg":[],"faq":[{"q":"LL-37 è un peptide umano di origine naturale?","a":"Sì. È l'unico peptide catelicidina umano noto e viene prodotto dalle cellule immunitarie, cutanee e mucosali, specialmente durante lesioni o infezioni.","q_en":"LL-37 è un peptide umano di origine naturale?","a_en":"Sì. È l'unico peptide catelicidina umano noto e viene prodotto dalle cellule immunitarie, cutanee e mucosali, specialmente durante lesioni o infezioni."},{"q":"Ci sono studi clinici su LL-37?","a":"Sì, diversi studi randomizzati hanno esaminato l'applicazione topica su ferite difficili da guarire come ulcere degli arti venosi e ulcere del piede diabetico, con risultati di sicurezza prevalentemente positivi.","q_en":"Ci sono studi clinici su LL-37?","a_en":"Sì, diversi studi randomizzati hanno esaminato l'applicazione topica su ferite difficili da guarire come ulcere degli arti venosi e ulcere del piede diabetico, con risultati di sicurezza prevalentemente positivi."},{"q":"LL-37 agisce solo come antimicrobico?","a":"No, oltre al suo effetto diretto sulle membrane batteriche, sono descritti anche effetti immunomodulatori come il reclutamento delle cellule immunitarie e la promozione della formazione dei vasi sanguigni.","q_en":"LL-37 agisce solo come antimicrobico?","a_en":"No, oltre al suo effetto diretto sulle membrane batteriche, sono descritti anche effetti immunomodulatori come il reclutamento delle cellule immunitarie e la promozione della formazione dei vasi sanguigni."}],"seo":{"title":"LL-37: profilo di ricerca ed evidenze","title_en":"LL-37: profilo di ricerca ed evidenze","description":"Panoramica di LL-37: catelicidina di origine naturale, meccanismo d'azione, evidenze cliniche sulla guarigione delle ferite e profilo di sicurezza nel contesto della ricerca.","description_en":"Panoramica di LL-37: catelicidina di origine naturale, meccanismo d'azione, evidenze cliniche sulla guarigione delle ferite e profilo di sicurezza nel contesto della ricerca."},"demo":false,"steckbrief":{"cas":"154947-66-7","molekulargewicht":"4493 g/mol","aminosaeuren":37,"halbwertszeit":null,"reinheitsstandard":"≥ 95 % (HPLC, standard commerciale)","loeslichkeit":"solubile in acqua e DMSO","sequenzLaenge":37,"quellen":["PubChem CID 16198951","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 95 % (HPLC, standard commerciale)","loeslichkeit_en":"solubile in acqua e DMSO"},"verwandt":["kpv","thymosin-alpha-1","bpc-157"]},{"slug":"thymosin-alpha-1","name":"Timosina alfa 1","synonyme":["Tα1","Zadaxin (nome commerciale)"],"kategorie":"Immunsystem","studienlage":"zugelassenes Arzneimittel","kurz":"Un peptide immunitario di origine naturale derivato dal timo, approvato come farmaco in più di 35 paesi, sebbene non attualmente in Germania, Austria o Svizzera.","kurz_en":"Un peptide immunitario di origine naturale derivato dal timo, approvato come farmaco in più di 35 paesi, sebbene non attualmente in Germania, Austria o Svizzera.","beschreibung":"La timosina alfa 1 è un peptide a 28 aminoacidi originariamente isolato dalla ghiandola del timo, l'organo centrale dove maturano le cellule T. Agisce come modulatore immunitario e viene utilizzato sia nella ricerca clinica che, con il nome commerciale Zadaxin, come farmaco approvato per determinate condizioni immunitarie. Le aree di studio includono infezioni virali croniche, la risposta immunitaria alla vaccinazione e un ruolo di supporto in oncologia.","beschreibung_en":"La timosina alfa 1 è un peptide a 28 aminoacidi originariamente isolato dalla ghiandola del timo, l'organo centrale dove maturano le cellule T. Agisce come modulatore immunitario e viene utilizzato sia nella ricerca clinica che, con il nome commerciale Zadaxin, come farmaco approvato per determinate condizioni immunitarie. Le aree di studio includono infezioni virali croniche, la risposta immunitaria alla vaccinazione e un ruolo di supporto in oncologia.","mechanismus":"L'effetto è descritto principalmente tramite i recettori Toll-like sulle cellule immunitarie, strutture di riconoscimento molecolare che rispondono ai patogeni. Questo attiva vie come NF-κB e la produzione di interferone, coinvolgendo contemporaneamente il sistema immunitario innato e quello adattativo. Gli effetti descritti includono un aumento dell'attività delle cellule T e delle cellule killer naturali, nonché un miglioramento della produzione di anticorpi.","mechanismus_en":"L'effetto è descritto principalmente tramite i recettori Toll-like sulle cellule immunitarie, strutture di riconoscimento molecolare che rispondono ai patogeni. Questo attiva vie come NF-κB e la produzione di interferone, coinvolgendo contemporaneamente il sistema immunitario innato e quello adattativo. Gli effetti descritti includono un aumento dell'attività delle cellule T e delle cellule killer naturali, nonché un miglioramento della produzione di anticorpi.","evidenz":[{"art":"clinico","kurz":"Una revisione retrospettiva di 76 pazienti con COVID-19 grave in due ospedali ha descritto una mortalità inferiore con la timosina alfa 1 rispetto al gruppo non trattato, accompagnata da un recupero dei conteggi delle cellule T.","kurz_en":"Una revisione retrospettiva di 76 pazienti con COVID-19 grave in due ospedali ha descritto una mortalità inferiore con la timosina alfa 1 rispetto al gruppo non trattato, accompagnata da un recupero dei conteggi delle cellule T.","quelle":"Liu et al. 2020, Clinical Infectious Diseases"},{"art":"clinico","kurz":"Uno studio randomizzato in 42 pazienti con cancro al polmone non a piccole cellule dopo radioterapia ha descritto una normalizzazione più rapida della funzione delle cellule T con la timosina alfa 1 rispetto al placebo, insieme a un beneficio di sopravvivenza, più pronunciato nei pazienti con tumori più piccoli.","kurz_en":"Uno studio randomizzato in 42 pazienti con cancro al polmone non a piccole cellule dopo radioterapia ha descritto una normalizzazione più rapida della funzione delle cellule T con la timosina alfa 1 rispetto al placebo, insieme a un beneficio di sopravvivenza, più pronunciato nei pazienti con tumori più piccoli.","quelle":"Schulof et al. 1985, Journal of Biological Response Modifiers, PMID 3998766"}],"sicherheit":["Grandi database di sicurezza che coprono migliaia di pazienti descrivono prevalentemente reazioni lievi e transitorie nel sito di iniezione e lieve affaticamento.","Rapporti rari includono reazioni cutanee allergiche e un'acutizzazione temporanea di condizioni autoimmuni preesistenti.","L'uso concomitante di farmaci immunosoppressori è elencato come controindicazione nelle informazioni sul prodotto, poiché gli effetti agiscono in direzioni opposte.","Le informazioni sul prodotto consigliano cautela per il trapianto d'organo attivo e la malattia autoimmune attiva."],"sicherheit_en":["Grandi database di sicurezza che coprono migliaia di pazienti descrivono prevalentemente reazioni lievi e transitorie nel sito di iniezione e lieve affaticamento.","Rapporti rari includono reazioni cutanee allergiche e un'acutizzazione temporanea di condizioni autoimmuni preesistenti.","L'uso concomitante di farmaci immunosoppressori è elencato come controindicazione nelle informazioni sul prodotto, poiché gli effetti agiscono in direzioni opposte.","Le informazioni sul prodotto consigliano cautela per il trapianto d'organo attivo e la malattia autoimmune attiva."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Sotto il nome commerciale Zadaxin, la timosina alfa 1 è approvata come farmaco per il trattamento di determinate condizioni immunitarie, inclusa l'epatite B e C, in più di 35 paesi. Non è attualmente approvata in Germania, Austria o Svizzera, dove l'approvvigionamento si trova in una zona grigia legale.","rechtsstatus_en":"Sotto il nome commerciale Zadaxin, la timosina alfa 1 è approvata come farmaco per il trattamento di determinate condizioni immunitarie, inclusa l'epatite B e C, in più di 35 paesi. Non è attualmente approvata in Germania, Austria o Svizzera, dove l'approvvigionamento si trova in una zona grigia legale.","typischeMg":[],"faq":[{"q":"La timosina alfa 1 è un farmaco approvato?","a":"Sì, sotto il nome commerciale Zadaxin in più di 35 paesi, incluso per l'epatite B e C cronica. Attualmente non c'è approvazione in Germania, Austria o Svizzera.","q_en":"La timosina alfa 1 è un farmaco approvato?","a_en":"Sì, sotto il nome commerciale Zadaxin in più di 35 paesi, incluso per l'epatite B e C cronica. Attualmente non c'è approvazione in Germania, Austria o Svizzera."},{"q":"Su cosa agisce la timosina alfa 1 nel sistema immunitario?","a":"Agisce sia sul sistema immunitario innato che su quello adattativo contemporaneamente, inclusa attraverso l'aumento dell'attività delle cellule T e delle cellule killer naturali, e il miglioramento della formazione di anticorpi.","q_en":"Su cosa agisce la timosina alfa 1 nel sistema immunitario?","a_en":"Agisce sia sul sistema immunitario innato che su quello adattativo contemporaneamente, inclusa attraverso l'aumento dell'attività delle cellule T e delle cellule killer naturali, e il miglioramento della formazione di anticorpi."},{"q":"Ci sono studi sull'uomo sulla timosina alfa 1?","a":"Sì, rispetto a molti altri peptidi esiste una base più ampia di studi clinici, inclusi lavori su infezioni virali gravi, un ruolo di supporto nella cura del cancro e la risposta vaccinale.","q_en":"Ci sono studi sull'uomo sulla timosina alfa 1?","a_en":"Sì, rispetto a molti altri peptidi esiste una base più ampia di studi clinici, inclusi lavori su infezioni virali gravi, un ruolo di supporto nella cura del cancro e la risposta vaccinale."}],"seo":{"title":"Timosina alfa 1: profilo di ricerca ed evidenze","title_en":"Timosina alfa 1: profilo di ricerca ed evidenze","description":"Panoramica della timosina alfa 1: modulazione immunitaria, stato di approvazione internazionale, evidenze cliniche e profilo di sicurezza.","description_en":"Panoramica della timosina alfa 1: modulazione immunitaria, stato di approvazione internazionale, evidenze cliniche e profilo di sicurezza."},"demo":false,"steckbrief":{"cas":"62304-98-7","molekulargewicht":"3108,3 g/mol","aminosaeuren":28,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":28,"quellen":["PubChem CID 16130571","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)"},"verwandt":["bpc-157","tb-500","kpv","ll-37"]},{"slug":"epitalon","name":"Epitalon","synonyme":["Epithalon","Tetrapeptide AEDG"],"kategorie":"Sonstige","studienlage":"präklinisch","kurz":"Un tetrapeptide sintetico, studiato nella ricerca sull'invecchiamento come sostanza di ricerca correlata all'invecchiamento cellulare.","kurz_en":"Un tetrapeptide sintetico, studiato nella ricerca sull'invecchiamento come sostanza di ricerca correlata all'invecchiamento cellulare.","beschreibung":"Epitalon è un tetrapeptide sintetico sviluppato da Vladimir Khavinson presso l'Istituto di Bioregolazione e Gerontologia di San Pietroburgo. Viene studiato in ricerca preclinica in relazione all'invecchiamento cellulare e alla regolazione dell'attività della telomerasi. Dati clinici robusti negli esseri umani sono ancora in sospeso.","beschreibung_en":"Epitalon è un tetrapeptide sintetico sviluppato da Vladimir Khavinson presso l'Istituto di Bioregolazione e Gerontologia di San Pietroburgo. Viene studiato in ricerca preclinica in relazione all'invecchiamento cellulare e alla regolazione dell'attività della telomerasi. Dati clinici robusti negli esseri umani sono ancora in sospeso.","mechanismus":"Si è descritto che l'epitalon aumenta l'attività della telomerasi nelle colture di cellule, il che è associato all'allungamento dei telomeri in vitro. Sono state anche descritte gli effetti sulla sintesi della melatonina e sulle molecole di segnalazione del sistema immunitario.","mechanismus_en":"Si è descritto che l'epitalon aumenta l'attività della telomerasi nelle colture di cellule, il che è associato all'allungamento dei telomeri in vitro. Sono state anche descritte gli effetti sulla sintesi della melatonina e sulle molecole di segnalazione del sistema immunitario.","evidenz":[{"art":"preclinico","kurz":"Nelle colture di fibroblasti fetali umani, l'epitalon ha indotto l'espressione della subunità catalitica della telomerasi e un'attività della telomerasi misurabile, associata all'allungamento dei telomeri.","kurz_en":"Nelle colture di fibroblasti fetali umani, l'epitalon ha indotto l'espressione della subunità catalitica della telomerasi e un'attività della telomerasi misurabile, associata all'allungamento dei telomeri.","quelle":"Khavinson VKh, Bondarev IE, Butyugov AA 2003, Bulletin of Experimental Biology and Medicine 135:590-592"},{"art":"preclinico","kurz":"Nei modelli animali, sono stati descritti gli effetti dell'epitalon sul rilascio di melatonina e sui parametri del sistema immunitario, con risultati misti sulla durata della vita a seconda del modello e del protocollo utilizzato.","kurz_en":"Nei modelli animali, sono stati descritti gli effetti dell'epitalon sul rilascio di melatonina e sui parametri del sistema immunitario, con risultati misti sulla durata della vita a seconda del modello e del protocollo utilizzato.","quelle":"Khavinson VKh, Morozov VG 2003, Neuroendocrinology Letters"}],"sicherheit":["Le ricerche precliniche non hanno ancora descritto effetti tossici gravi.","Non sono disponibili studi di sicurezza umana controllati che soddisfino gli standard dei trial occidentali.","Non esistono dati solidi sull'uso a lungo termine."],"sicherheit_en":["Le ricerche precliniche non hanno ancora descritto effetti tossici gravi.","Non sono disponibili studi di sicurezza umana controllati che soddisfino gli standard dei trial occidentali.","Non esistono dati solidi sull'uso a lungo termine."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Epitalon non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti ed è venduto esclusivamente come sostanza chimica di ricerca per scopi di laboratorio.","rechtsstatus_en":"Epitalon non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti ed è venduto esclusivamente come sostanza chimica di ricerca per scopi di laboratorio.","typischeMg":[10,20],"faq":[{"q":"Epitalon è stato studiato in esseri umani?","a":"I dati disponibili provengono prevalentemente dalla coltura cellulare e dai modelli animali. Studi clinici controllati su esseri umani che soddisfano gli standard occidentali non sono ancora disponibili.","q_en":"Epitalon è stato studiato in esseri umani?","a_en":"I dati disponibili provengono prevalentemente dalla coltura cellulare e dai modelli animali. Studi clinici controllati su esseri umani che soddisfano gli standard occidentali non sono ancora disponibili."},{"q":"Cosa ha a che fare l'epitalon con i telomeri?","a":"Gli studi sulla coltura cellulare hanno osservato un aumento dell'attività della telomerasi e dell'allungamento dei telomeri. Se ciò si traduce nell'organismo intero rimane aperto.","q_en":"Cosa ha a che fare l'epitalon con i telomeri?","a_en":"Gli studi sulla coltura cellulare hanno osservato un aumento dell'attività della telomerasi e dell'allungamento dei telomeri. Se ciò si traduce nell'organismo intero rimane aperto."},{"q":"L'epitalon è legalmente disponibile in Germania?","a":"Epitalon non è approvato come farmaco ed è offerto esclusivamente come sostanza chimica di ricerca, non per uso umano.","q_en":"L'epitalon è legalmente disponibile in Germania?","a_en":"Epitalon non è approvato come farmaco ed è offerto esclusivamente come sostanza chimica di ricerca, non per uso umano."}],"seo":{"title":"Epitalon: Tetrapeptide nella Ricerca sull'Invecchiamento","title_en":"Epitalon: Tetrapeptide nella Ricerca sull'Invecchiamento","description":"Epitalon in sintesi: meccanismo, stato degli studi preclinici e profilo di sicurezza del peptide di ricerca sulla telomerasi di Khavinson.","description_en":"Epitalon in sintesi: meccanismo, stato degli studi preclinici e profilo di sicurezza del peptide di ricerca sulla telomerasi di Khavinson."},"demo":false,"steckbrief":{"cas":"307297-39-8","molekulargewicht":"390,35 g/mol","aminosaeuren":4,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":4,"quellen":["PubChem CID 219042","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)"},"verwandt":["melanotan-2","selank","semax","dsip"]},{"slug":"kisspeptin","name":"Kisspeptina-10","synonyme":["Metastina (45-54)","KP-10"],"kategorie":"Sonstige","studienlage":"klinisch untersucht","kurz":"Il frammento bioattivo più corto del sistema kisspeptina proprio del corpo, studiato nella ricerca endocrina sul controllo dell'asse ipotalamo-ipofisi-gonadi.","kurz_en":"Il frammento bioattivo più corto del sistema kisspeptina proprio del corpo, studiato nella ricerca endocrina sul controllo dell'asse ipotalamo-ipofisi-gonadi.","beschreibung":"La kisspeptina-10 è il frammento più corto della kisspeptina (metastina), il peptide endogeno, e mantiene la piena attività sul recettore KISS1R. Nella ricerca viene utilizzata per innescare direttamente il rilascio di GnRH e per studiare l'asse ipotalamo-ipofisi-gonadi nello sviluppo puberale, nell'ipogonadismo e nella fertilità. Gli studi clinici più ampi su endpoint come la maturazione degli ovociti o l'eccitazione sessuale hanno utilizzato per lo più l'isoforma naturale più lunga, la kisspeptina-54, che agisce sullo stesso recettore.","beschreibung_en":"La kisspeptina-10 è il frammento più corto della kisspeptina (metastina), il peptide endogeno, e mantiene la piena attività sul recettore KISS1R. Nella ricerca viene utilizzata per innescare direttamente il rilascio di GnRH e per studiare l'asse ipotalamo-ipofisi-gonadi nello sviluppo puberale, nell'ipogonadismo e nella fertilità. Gli studi clinici più ampi su endpoint come la maturazione degli ovociti o l'eccitazione sessuale hanno utilizzato per lo più l'isoforma naturale più lunga, la kisspeptina-54, che agisce sullo stesso recettore.","mechanismus":"La Kisspeptina-10 si lega al recettore accoppiato a proteine G KISS1R (GPR54) sui neuroni GnRH nell'ipotalamo. Attraverso una cascata di segnalazione mediata da Gq/11 che coinvolge l'afflusso di calcio, depolarizza questi neuroni e innesca il rilascio pulsatile di GnRH, che a valle regola il rilascio di LH e FSH dalla ghiandola pituitaria. Nei maschi, un bolo di kisspeptina-10 aumenta i livelli di LH e la frequenza di impulso, con un effetto più forte a quantità somministrate più elevate. Al contrario, la stimolazione del recettore sostenuta o ad alta frequenza può desensibilizzare il KISS1R e attenuare la risposta di LH.","mechanismus_en":"La Kisspeptina-10 si lega al recettore accoppiato a proteine G KISS1R (GPR54) sui neuroni GnRH nell'ipotalamo. Attraverso una cascata di segnalazione mediata da Gq/11 che coinvolge l'afflusso di calcio, depolarizza questi neuroni e innesca il rilascio pulsatile di GnRH, che a valle regola il rilascio di LH e FSH dalla ghiandola pituitaria. Nei maschi, un bolo di kisspeptina-10 aumenta i livelli di LH e la frequenza di impulso, con un effetto più forte a quantità somministrate più elevate. Al contrario, la stimolazione del recettore sostenuta o ad alta frequenza può desensibilizzare il KISS1R e attenuare la risposta di LH.","evidenz":[{"art":"clinico","kurz":"In uno studio in uomini sani, un bolo di kisspeptina-10 per via endovenosa ha aumentato i livelli di LH con un effetto crescente a quantità più elevate, e un'infusione continua a bassa concentrazione ha ulteriormente aumentato la frequenza dei picchi di LH.","kurz_en":"In uno studio in uomini sani, un bolo di kisspeptina-10 per via endovenosa ha aumentato i livelli di LH con un effetto crescente a quantità più elevate, e un'infusione continua a bassa concentrazione ha ulteriormente aumentato la frequenza dei picchi di LH.","quelle":"George JT et al. 2011, The Journal of Clinical Endocrinology & Metabolism, PMID 21632807"},{"art":"clinico","kurz":"In uno studio randomizzato su 60 donne ad alto rischio di OHSS, un'iniezione singola dell'isoforma correlata kisspeptina-54 ha innescato la maturazione degli oociti in il 95 per cento dei casi durante un ciclo IVF, senza osservare OHSS moderata o grave.","kurz_en":"In uno studio randomizzato su 60 donne ad alto rischio di OHSS, un'iniezione singola dell'isoforma correlata kisspeptina-54 ha innescato la maturazione degli oociti in il 95 per cento dei casi durante un ciclo IVF, senza osservare OHSS moderata o grave.","quelle":"Jayasena CN et al. 2015, The Journal of Clinical Endocrinology & Metabolism, PMID 26192876"},{"art":"clinico","kurz":"In uno studio randomizzato controllato con placebo su 32 uomini con disturbo del desiderio sessuale ipoattivo, un'infusione singola dell'isoforma kisspeptina-54 ha aumentato l'attività cerebrale sessuale e la tumescenza penile durante la visione di video erotici rispetto al placebo.","kurz_en":"In uno studio randomizzato controllato con placebo su 32 uomini con disturbo del desiderio sessuale ipoattivo, un'infusione singola dell'isoforma kisspeptina-54 ha aumentato l'attività cerebrale sessuale e la tumescenza penile durante la visione di video erotici rispetto al placebo.","quelle":"Mills EG et al. 2023, JAMA Network Open, PMID 36735255"}],"sicherheit":["Attraverso studi pubblicati con più di 1.000 partecipanti combinati, non sono stati segnalati eventi avversi gravi attribuibili alla sostanza finora, con un profilo di eventi avversi paragonabile al placebo.","Gli effetti più comunemente descritti sono reazioni lievi e transitorie come reazioni nel sito di iniezione, rossore e mal di testa lieve.","La stimolazione prolungata o ad alta frequenza del recettore KISS1R può portare a desensibilizzazione del recettore e a una risposta di LH attenuata (tachifilassi).","Dati di sicurezza a lungo termine robusti non sono ancora disponibili, poiché gli studi disponibili coprono principalmente l'amministrazione a breve termine e controllata."],"sicherheit_en":["Attraverso studi pubblicati con più di 1.000 partecipanti combinati, non sono stati segnalati eventi avversi gravi attribuibili alla sostanza finora, con un profilo di eventi avversi paragonabile al placebo.","Gli effetti più comunemente descritti sono reazioni lievi e transitorie come reazioni nel sito di iniezione, rossore e mal di testa lieve.","La stimolazione prolungata o ad alta frequenza del recettore KISS1R può portare a desensibilizzazione del recettore e a una risposta di LH attenuata (tachifilassi).","Dati di sicurezza a lungo termine robusti non sono ancora disponibili, poiché gli studi disponibili coprono principalmente l'amministrazione a breve termine e controllata."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"La kisspeptina-10 non è approvata come farmaco in Germania, nell'UE o negli Stati Uniti. Viene venduta esclusivamente come sostanza chimica di ricerca per scopi di laboratorio; le applicazioni cliniche come trigger IVF o uso nel disturbo del desiderio sessuale ipoattivo rimangono sotto indagine sperimentale.","rechtsstatus_en":"La kisspeptina-10 non è approvata come farmaco in Germania, nell'UE o negli Stati Uniti. Viene venduta esclusivamente come sostanza chimica di ricerca per scopi di laboratorio; le applicazioni cliniche come trigger IVF o uso nel disturbo del desiderio sessuale ipoattivo rimangono sotto indagine sperimentale.","typischeMg":[5,10],"faq":[{"q":"La kisspeptina-10 è la stessa kisspeptina testata negli studi clinici","a":"Non esattamente. La maggior parte degli studi clinici principali su fertilità o eccitazione sessuale ha utilizzato la più lunga isoforma naturale kisspeptina-54. La kisspeptina-10 è il frammento più corto con piena attività del recettore ed è stata studiata principalmente in ricerche meccanicistiche sul rilascio di LH negli uomini.","q_en":"La kisspeptina-10 è la stessa kisspeptina testata negli studi clinici","a_en":"Non esattamente. La maggior parte degli studi clinici principali su fertilità o eccitazione sessuale ha utilizzato la più lunga isoforma naturale kisspeptina-54. La kisspeptina-10 è il frammento più corto con piena attività del recettore ed è stata studiata principalmente in ricerche meccanicistiche sul rilascio di LH negli uomini."},{"q":"Come agisce la kisspeptina-10 sul corpo","a":"Si lega al recettore KISS1R sulle neuroni GnRH nell'ipotalamo e innesca il rilascio pulsatile di GnRH. Questo regola a valle la secrezione di LH e FSH dalla ghiandola pituitaria e, con essa, le funzioni centrali dell'asse riproduttivo.","q_en":"Come agisce la kisspeptina-10 sul corpo","a_en":"Si lega al recettore KISS1R sulle neuroni GnRH nell'ipotalamo e innesca il rilascio pulsatile di GnRH. Questo regola a valle la secrezione di LH e FSH dalla ghiandola pituitaria e, con essa, le funzioni centrali dell'asse riproduttivo."},{"q":"La kisspeptina-10 è legalmente disponibile in Germania","a":"La kisspeptina-10 non è approvata come farmaco in Germania, nell'UE o negli Stati Uniti. Viene offerta esclusivamente come sostanza chimica di ricerca per scopi di laboratorio, non per uso umano.","q_en":"La kisspeptina-10 è legalmente disponibile in Germania","a_en":"La kisspeptina-10 non è approvata come farmaco in Germania, nell'UE o negli Stati Uniti. Viene offerta esclusivamente come sostanza chimica di ricerca per scopi di laboratorio, non per uso umano."}],"seo":{"title":"Kisspeptina-10: Peptide di Ricerca per l'Asse Ormonale","title_en":"Kisspeptina-10: Peptide di Ricerca per l'Asse Ormonale","description":"Kisspeptina-10 spiegato in modo fattuale: meccanismo al recettore KISS1R, dati di studio su GnRH e l'asse ormonale, e il profilo di sicurezza di un peptide di ricerca.","description_en":"Kisspeptina-10 spiegato in modo fattuale: meccanismo al recettore KISS1R, dati di studio su GnRH e l'asse ormonale, e il profilo di sicurezza di un peptide di ricerca."},"demo":false,"steckbrief":{"cas":"374675-21-5","molekulargewicht":"1302,4 g/mol","aminosaeuren":10,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":"solubile in acqua e buffer acquosi","sequenzLaenge":10,"quellen":["PubChem CID 25240297","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit_en":"solubile in acqua e buffer acquosi"},"verwandt":["pt-141","oxytocin"]},{"slug":"melanotan-2","name":"Melanotan II","synonyme":["MT-2","MT2"],"kategorie":"Sonstige","studienlage":"frühe klinische Studien","kurz":"Un analogo sintetico dell'ormone alpha-MSH del corpo, studiato in studi clinici iniziali su pigmentazione e funzione sessuale.","kurz_en":"Un analogo sintetico dell'ormone alpha-MSH del corpo, studiato in studi clinici iniziali su pigmentazione e funzione sessuale.","beschreibung":"Melanotan II è un peptide sintetico ciclico a sette amminoacidi che si lega a diversi recettori melanocortina nel corpo. È stato sviluppato negli anni 1980 all'Università dell'Arizona ed è considerevolmente più potente del suo corrispondente naturale, alpha-MSH. Le aree di studio includono un ruolo nella pigmentazione cutanea nonché nel desiderio e nell'eccitazione sessuale.","beschreibung_en":"Melanotan II è un peptide sintetico ciclico a sette amminoacidi che si lega a diversi recettori melanocortina nel corpo. È stato sviluppato negli anni 1980 all'Università dell'Arizona ed è considerevolmente più potente del suo corrispondente naturale, alpha-MSH. Le aree di studio includono un ruolo nella pigmentazione cutanea nonché nel desiderio e nell'eccitazione sessuale.","mechanismus":"Tramite il recettore MC1R sulle cellule pigmentate della pelle, il melanotan II innesca la produzione di eumelanina che avviene indipendentemente dall'esposizione ai raggi UV. Tramite il recettore MC4R nel sistema nervoso centrale, viene descritto un effetto sul desiderio e sull'eccitazione sessuale, insieme a un effetto regolatore dell'appetito. Poiché il melanotan II attiva diversi recettori non selettivamente contemporaneamente, l'interazione di questi effetti è più complessa rispetto a quella con i composti più selettivi e correlati.","mechanismus_en":"Tramite il recettore MC1R sulle cellule pigmentate della pelle, il melanotan II innesca la produzione di eumelanina che avviene indipendentemente dall'esposizione ai raggi UV. Tramite il recettore MC4R nel sistema nervoso centrale, viene descritto un effetto sul desiderio e sull'eccitazione sessuale, insieme a un effetto regolatore dell'appetito. Poiché il melanotan II attiva diversi recettori non selettivamente contemporaneamente, l'interazione di questi effetti è più complessa rispetto a quella con i composti più selettivi e correlati.","evidenz":[{"art":"clinico","kurz":"Uno studio pilota di fase 1 su tre volontari maschi ha descritto una marcata pigmentazione cutanea senza esposizione ai raggi UV dopo iniezioni sottocutanee ripetute, accompagnata da nausea, rossore e erezioni spontanee come effetti avversi più comuni.","kurz_en":"Uno studio pilota di fase 1 su tre volontari maschi ha descritto una marcata pigmentazione cutanea senza esposizione ai raggi UV dopo iniezioni sottocutanee ripetute, accompagnata da nausea, rossore e erezioni spontanee come effetti avversi più comuni.","quelle":"Dorr et al. 1996, Life Sciences, PMID 8637402"},{"art":"clinico","kurz":"Uno studio crossover in doppio cieco e controllato con placebo su uomini con disfunzione erettile psicogena ha descritto un'erezione in 8 su 10 partecipanti dopo iniezione di melanotan II, con rigidità significativamente più lunga rispetto al placebo.","kurz_en":"Uno studio crossover in doppio cieco e controllato con placebo su uomini con disfunzione erettile psicogena ha descritto un'erezione in 8 su 10 partecipanti dopo iniezione di melanotan II, con rigidità significativamente più lunga rispetto al placebo.","quelle":"Hadley et al. 1998, PMID 9679884"}],"sicherheit":["Gli effetti acuti comunemente riportati sono nausea e rossore facciale, attribuiti al rilascio di istamina.","Sono stati osservati lievi aumenti della pressione sanguigna e della frequenza cardiaca.","È stata documentata un'emergenza medica che coinvolge un'erezione di diverse ore come effetto collaterale raro ma grave.","I case report descrivono la comparsa di nei nuovi o più scuri, per lo più in relazione a una contemporanea esposizione ai raggi UV. Un nesso causale con il cancro della pelle non è stato stabilito."],"sicherheit_en":["Gli effetti acuti comunemente riportati sono nausea e rossore facciale, attribuiti al rilascio di istamina.","Sono stati osservati lievi aumenti della pressione sanguigna e della frequenza cardiaca.","È stata documentata un'emergenza medica che coinvolge un'erezione di diverse ore come effetto collaterale raro ma grave.","I case report descrivono la comparsa di nei nuovi o più scuri, per lo più in relazione a una contemporanea esposizione ai raggi UV. Un nesso causale con il cancro della pelle non è stato stabilito."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Melanotan II non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti, ed è venduto esclusivamente come sostanza chimica per la ricerca. Tre farmaci melanocortine strutturalmente correlati (afamelanotide, bremelanotide, setmelanotide) sono approvati per indicazioni separate e specifiche negli Stati Uniti e in parti dell'UE; il melanotan II stesso non è tra di essi.","rechtsstatus_en":"Melanotan II non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti, ed è venduto esclusivamente come sostanza chimica per la ricerca. Tre farmaci melanocortine strutturalmente correlati (afamelanotide, bremelanotide, setmelanotide) sono approvati per indicazioni separate e specifiche negli Stati Uniti e in parti dell'UE; il melanotan II stesso non è tra di essi.","typischeMg":[],"faq":[{"q":"Il melanotan II è approvato?","a":"No, il melanotan II stesso non è approvato nell'UE o negli Stati Uniti. Viene venduto solo come sostanza chimica per la ricerca, mentre tre composti correlati sono approvati per altre indicazioni.","q_en":"Il melanotan II è approvato?","a_en":"No, il melanotan II stesso non è approvato nell'UE o negli Stati Uniti. Viene venduto solo come sostanza chimica per la ricerca, mentre tre composti correlati sono approvati per altre indicazioni."},{"q":"Il melanotan II funziona solo con la luce solare?","a":"No. Secondo gli studi, la formazione del pigmento avviene indipendentemente dall'esposizione ai raggi UV. La luce UV può potenziare ulteriormente l'effetto ma non è richiesta per esso.","q_en":"Il melanotan II funziona solo con la luce solare?","a_en":"No. Secondo gli studi, la formazione del pigmento avviene indipendentemente dall'esposizione ai raggi UV. La luce UV può potenziare ulteriormente l'effetto ma non è richiesta per esso."},{"q":"Quali effetti collaterali sono stati descritti negli studi?","a":"Più spesso nausea e arrossamento del viso. Meno frequentemente sono stati descritti aumenti della pressione arteriosa, un’erezione prolungata come emergenza medica e modifiche dei nei.","q_en":"Quali effetti collaterali sono stati descritti negli studi?","a_en":"Più spesso nausea e arrossamento del viso. Meno frequentemente sono stati descritti aumenti della pressione arteriosa, un’erezione prolungata come emergenza medica e modifiche dei nei."}],"seo":{"title":"Melanotan II: profilo di ricerca ed evidenze","title_en":"Melanotan II: profilo di ricerca ed evidenze","description":"Panoramica del Melanotan II: meccanismo, evidenze cliniche sulla pigmentazione e sulla funzione sessuale, e profilo di sicurezza.","description_en":"Panoramica del Melanotan II: meccanismo, evidenze cliniche sulla pigmentazione e sulla funzione sessuale, e profilo di sicurezza."},"demo":false,"steckbrief":{"cas":"121062-08-6","molekulargewicht":"1024,2 g/mol","aminosaeuren":7,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 92432","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, standard commerciale)"},"verwandt":["ghk-cu","epitalon","pt-141","kpv"]},{"slug":"oxytocin","name":"Ossitocina","synonyme":["OXT","Pitocin"],"kategorie":"Sonstige","studienlage":"zugelassenes Arzneimittel","kurz":"Un ormone nonapeptide endogeno, approvato come farmaco per indurre il parto e studiato anche in ricerca sul comportamento sociale e sul legame.","kurz_en":"Un ormone nonapeptide endogeno, approvato come farmaco per indurre il parto e studiato anche in ricerca sul comportamento sociale e sul legame.","beschreibung":"L'ossitocina è un ormone a nove amminoacidi prodotto nell'ipotalamo e rilasciato tramite la ghiandola pituitaria. Come farmaco, come Syntocinon o Pitocin, è approvata per indurre il parto e controllare il sanguinamento postparto. L'ossitocina somministrata intranasalmente viene studiata in ricerca di base sul comportamento sociale, la fiducia e il legame.","beschreibung_en":"L'ossitocina è un ormone a nove amminoacidi prodotto nell'ipotalamo e rilasciato tramite la ghiandola pituitaria. Come farmaco, come Syntocinon o Pitocin, è approvata per indurre il parto e controllare il sanguinamento postparto. L'ossitocina somministrata intranasalmente viene studiata in ricerca di base sul comportamento sociale, la fiducia e il legame.","mechanismus":"L'ossitocina si lega al recettore dell'ossitocina (OXTR), un recettore accoppiato a proteine Gq/11 sul muscolo liscio uterino e in varie regioni cerebrali. Il legame del recettore attiva la fosfolipasi C e, attraverso di essa, il rilascio di calcio intracellulare, che guida la contrazione del muscolo liscio uterino. A concentrazioni più elevate, l'ossitocina agisce anche sul recettore vasopressina V2 strutturalmente correlato, producendo un effetto antidiuretico.","mechanismus_en":"L'ossitocina si lega al recettore dell'ossitocina (OXTR), un recettore accoppiato a proteine Gq/11 sul muscolo liscio uterino e in varie regioni cerebrali. Il legame del recettore attiva la fosfolipasi C e, attraverso di essa, il rilascio di calcio intracellulare, che guida la contrazione del muscolo liscio uterino. A concentrazioni più elevate, l'ossitocina agisce anche sul recettore vasopressina V2 strutturalmente correlato, producendo un effetto antidiuretico.","evidenz":[{"art":"preclinico","kurz":"In un modello animale con arvicole della prateria, la somministrazione centrale di ossitocina ha indotto nelle femmine una preferenza per il partner, mentre un antagonista selettivo dell'ossitocina ne ha bloccato la formazione dopo l'accoppiamento.","kurz_en":"In un modello animale con arvicole della prateria, la somministrazione centrale di ossitocina ha indotto nelle femmine una preferenza per il partner, mentre un antagonista selettivo dell'ossitocina ne ha bloccato la formazione dopo l'accoppiamento.","quelle":"Insel TR & Hulihan TJ 1995, Behavioral Neuroscience, 109:782-789"},{"art":"clinico","kurz":"In uno studio comportamentale controllato con placebo in partecipanti maschi sani, l'ossitocina somministrata intranasalmente ha aumentato la volontà di affidare denaro a uno sconosciuto in un gioco di fiducia, senza alterare il comportamento generale di assunzione di rischio.","kurz_en":"In uno studio comportamentale controllato con placebo in partecipanti maschi sani, l'ossitocina somministrata intranasalmente ha aumentato la volontà di affidare denaro a uno sconosciuto in un gioco di fiducia, senza alterare il comportamento generale di assunzione di rischio.","quelle":"Kosfeld M, Heinrichs M, Zak PJ, Fischbacher U, Fehr E 2005, Nature, PMID 15931222"},{"art":"clinico","kurz":"In uno studio randomizzato, controllato con placebo in 106 adulti con disturbo dello spettro autistico, sei settimane di ossitocina intranasale non hanno mostrato un miglioramento statisticamente significativo dei sintomi sociali principali rispetto al placebo.","kurz_en":"In uno studio randomizzato, controllato con placebo in 106 adulti con disturbo dello spettro autistico, sei settimane di ossitocina intranasale non hanno mostrato un miglioramento statisticamente significativo dei sintomi sociali principali rispetto al placebo.","quelle":"Yamasue H et al. 2020, Molecular Psychiatry, PMID 29955161"},{"art":"preclinico","kurz":"Una revisione della farmacologia dei recettori descrive l'accoppiamento del recettore dell'ossitocina con le vie di segnalazione mediate dalla proteina Gq/11 come la fosfolipasi C e la proteina chinasi C in modelli cellulari e animali.","kurz_en":"Una revisione della farmacologia dei recettori descrive l'accoppiamento del recettore dell'ossitocina con le vie di segnalazione mediate dalla proteina Gq/11 come la fosfolipasi C e la proteina chinasi C in modelli cellulari e animali.","quelle":"Jurek B & Neumann ID 2018, Physiological Reviews, PMID 29897293"}],"sicherheit":["Con somministrazione endovenosa combinata con grandi volumi di fluido privo di elettroliti, si documenta l'intossicazione da acqua con iponatremia, guidata dall'effetto antidiuretico dell'ossitocina collegato alla sua somiglianza strutturale alla vasopressina.","Uno studio ampiamente citato sugli effetti sul rafforzamento della fiducia dell'ossitocina intranasale non è stato confermato in uno studio di replicazione successivo in condizioni sperimentali identiche.","Nel più grande studio randomizzato di ossitocina intranasale nel disturbo dello spettro autistico fino ad oggi, non è stato osservato alcun effetto significativo sui sintomi principali.","Per usi al di fuori dell'indicazione ostetrica approvata, non sono disponibili dati di sicurezza a lungo termine robusti."],"sicherheit_en":["Con somministrazione endovenosa combinata con grandi volumi di fluido privo di elettroliti, si documenta l'intossicazione da acqua con iponatremia, guidata dall'effetto antidiuretico dell'ossitocina collegato alla sua somiglianza strutturale alla vasopressina.","Uno studio ampiamente citato sugli effetti sul rafforzamento della fiducia dell'ossitocina intranasale non è stato confermato in uno studio di replicazione successivo in condizioni sperimentali identiche.","Nel più grande studio randomizzato di ossitocina intranasale nel disturbo dello spettro autistico fino ad oggi, non è stato osservato alcun effetto significativo sui sintomi principali.","Per usi al di fuori dell'indicazione ostetrica approvata, non sono disponibili dati di sicurezza a lungo termine robusti."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"L'ossitocina è approvata come farmaco, come Syntocinon o Pitocin, in Germania, nell'UE e negli Stati Uniti per l'induzione del parto e il trattamento dell'emorragia post-partum, ed è su prescrizione solo per tale uso. Per altre domande di ricerca non approvate come comportamento sociale o legame, è venduta separatamente come sostanza chimica di ricerca.","rechtsstatus_en":"L'ossitocina è approvata come farmaco, come Syntocinon o Pitocin, in Germania, nell'UE e negli Stati Uniti per l'induzione del parto e il trattamento dell'emorragia post-partum, ed è su prescrizione solo per tale uso. Per altre domande di ricerca non approvate come comportamento sociale o legame, è venduta separatamente come sostanza chimica di ricerca.","typischeMg":[],"faq":[{"q":"L'ossitocina è un farmaco approvato o una sostanza chimica di ricerca","a":"Entrambi, a seconda dell'uso. Per l'induzione del parto e l'emorragia post-partum, l'ossitocina è un farmaco su prescrizione. Per altre domande di ricerca come il comportamento sociale, è venduta separatamente come sostanza chimica di ricerca, senza approvazione per tale scopo.","q_en":"L'ossitocina è un farmaco approvato o una sostanza chimica di ricerca","a_en":"Entrambi, a seconda dell'uso. Per l'induzione del parto e l'emorragia post-partum, l'ossitocina è un farmaco su prescrizione. Per altre domande di ricerca come il comportamento sociale, è venduta separatamente come sostanza chimica di ricerca, senza approvazione per tale scopo."},{"q":"Per cosa viene studiata l'ossitocina nella ricerca sul comportamento sociale","a":"Gli studi esaminano l'ossitocina somministrata intranasalmente in relazione alla fiducia, al legame e alla percezione sociale. I risultati sono misti e uno studio precoce sulla fiducia ampiamente citato non è stato confermato in una replicazione.","q_en":"Per cosa viene studiata l'ossitocina nella ricerca sul comportamento sociale","a_en":"Gli studi esaminano l'ossitocina somministrata intranasalmente in relazione alla fiducia, al legame e alla percezione sociale. I risultati sono misti e uno studio precoce sulla fiducia ampiamente citato non è stato confermato in una replicazione."},{"q":"L'ossitocina funziona per il disturbo dello spettro autistico","a":"Il più grande studio randomizzato in adulti con disturbo dello spettro autistico fino ad oggi non ha trovato alcun effetto significativo dell'ossitocina intranasale sui sintomi sociali principali rispetto al placebo.","q_en":"L'ossitocina funziona per il disturbo dello spettro autistico","a_en":"Il più grande studio randomizzato in adulti con disturbo dello spettro autistico fino ad oggi non ha trovato alcun effetto significativo dell'ossitocina intranasale sui sintomi sociali principali rispetto al placebo."}],"seo":{"title":"Ossitocina: Ormone, Farmaco e Peptide di Ricerca","title_en":"Ossitocina: Ormone, Farmaco e Peptide di Ricerca","description":"Ossitocina spiegata fattualmente: indicazione approvata, meccanismo d'azione, ricerca sul comportamento sociale e status legale come sostanza chimica di ricerca.","description_en":"Ossitocina spiegata fattualmente: indicazione approvata, meccanismo d'azione, ricerca sul comportamento sociale e status legale come sostanza chimica di ricerca."},"demo":false,"steckbrief":{"cas":"50-56-6","molekulargewicht":"1007,2 g/mol","aminosaeuren":9,"halbwertszeit":"≈ 1 a 6 minuti (emivita del plasma, informazioni di prescrizione Pitocin)","reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":9,"quellen":["PubChem CID 439302","DailyMed SPL PITOCIN (Oxytocin), Par Health USA","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 1 a 6 minuti (emivita del plasma, informazioni di prescrizione Pitocin)","reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)"},"verwandt":["kisspeptin","pt-141","dsip"]},{"slug":"pt-141","name":"PT-141 (bremelanotide)","synonyme":["Bremelanotide","Vyleesi"],"kategorie":"Sonstige","studienlage":"zugelassenes Arzneimittel","kurz":"Un heptapeptide sintetico e agonista del recettore della melanocortina, approvato negli Stati Uniti con il nome Vyleesi per una specifica forma di basso desiderio sessuale nelle donne.","kurz_en":"Un heptapeptide sintetico e agonista del recettore della melanocortina, approvato negli Stati Uniti con il nome Vyleesi per una specifica forma di basso desiderio sessuale nelle donne.","beschreibung":"PT-141 (bremelanotide) è un peptide a sette amminoacidi sviluppato da Palatin Technologies come composto di follow-on a melanotan II. A differenza di melanotan II, che è stato studiato principalmente per la pigmentazione cutanea, la ricerca su bremelanotide si è concentrata sulla regolazione centrale del desiderio sessuale. Dal 2019, il composto è stato approvato negli Stati Uniti con il nome Vyleesi per l'indicazione di disturbo del desiderio sessuale ipoattivo (HSDD) nelle donne premenopausali.","beschreibung_en":"PT-141 (bremelanotide) è un peptide a sette amminoacidi sviluppato da Palatin Technologies come composto di follow-on a melanotan II. A differenza di melanotan II, che è stato studiato principalmente per la pigmentazione cutanea, la ricerca su bremelanotide si è concentrata sulla regolazione centrale del desiderio sessuale. Dal 2019, il composto è stato approvato negli Stati Uniti con il nome Vyleesi per l'indicazione di disturbo del desiderio sessuale ipoattivo (HSDD) nelle donne premenopausali.","mechanismus":"Bremelanotide agisce come agonista dei recettori della melanocortina, principalmente il sottotipo MC4R concentrato nell'area preottica mediale dell'ipotalamo. La ricerca preclinica descrive il rilascio di dopamina innescato attraverso questo recettore nelle regioni cerebrali coinvolte nell'eccitazione sessuale. Il sito d'azione è quindi centrale, nel cervello, piuttosto che vascolare come con gli inibitori della PDE5. Secondo l'etichetta FDA, il meccanismo preciso dietro il miglioramento dei sintomi di HSDD non è stato pienamente stabilito.","mechanismus_en":"Bremelanotide agisce come agonista dei recettori della melanocortina, principalmente il sottotipo MC4R concentrato nell'area preottica mediale dell'ipotalamo. La ricerca preclinica descrive il rilascio di dopamina innescato attraverso questo recettore nelle regioni cerebrali coinvolte nell'eccitazione sessuale. Il sito d'azione è quindi centrale, nel cervello, piuttosto che vascolare come con gli inibitori della PDE5. Secondo l'etichetta FDA, il meccanismo preciso dietro il miglioramento dei sintomi di HSDD non è stato pienamente stabilito.","evidenz":[{"art":"preclinico","kurz":"Studi su femmine di ratto hanno mostrato un aumento del comportamento di sollecitazione sessuale dopo la somministrazione di bremelanotide, mediato dal rilascio di dopamina a seguito dell'attivazione dei recettori MC4 nell'area preottica mediale dell'ipotalamo.","kurz_en":"Studi su femmine di ratto hanno mostrato un aumento del comportamento di sollecitazione sessuale dopo la somministrazione di bremelanotide, mediato dal rilascio di dopamina a seguito dell'attivazione dei recettori MC4 nell'area preottica mediale dell'ipotalamo.","quelle":"Pfaus JG et al. 2007, The Journal of Sexual Medicine, PMID 17958619"},{"art":"clinico","kurz":"In due studi randomizzati controllati con placebo di fase 3 (RECONNECT) in donne premenopausali con HSDD, bremelanotide ha migliorato il desiderio sessuale e il disagio correlato più del placebo.","kurz_en":"In due studi randomizzati controllati con placebo di fase 3 (RECONNECT) in donne premenopausali con HSDD, bremelanotide ha migliorato il desiderio sessuale e il disagio correlato più del placebo.","quelle":"Kingsberg SA, Clayton AH, Portman D et al. 2019, Obstetrics & Gynecology, PMID 31599840"},{"art":"clinico","kurz":"Un'analisi aggregata di 43 studi clinici con circa 3.500 partecipanti ha documentato nausea, rossore, mal di testa e aumenti transitori della pressione sanguigna come gli effetti avversi più comuni di bremelanotide.","kurz_en":"Un'analisi aggregata di 43 studi clinici con circa 3.500 partecipanti ha documentato nausea, rossore, mal di testa e aumenti transitori della pressione sanguigna come gli effetti avversi più comuni di bremelanotide.","quelle":"Clayton AH et al. 2022, Journal of Women's Health, PMID 35147466"}],"sicherheit":["Nei trial clinici, la nausea si è verificata in circa il 40 per cento dei partecipanti con bremelanotide, rispetto a circa l'1 per cento nel placebo.","Un aumento transitorio della pressione sanguigna e una diminuzione della frequenza cardiaca sono stati osservati dopo ogni somministrazione, risolvendosi entro circa 12 ore secondo l'etichetta FDA.","Secondo l'etichetta FDA, Vyleesi è controindicato in ipertensione incontrollata o malattia cardiovascolare nota.","Nei trial RECONNECT, è stata osservata iperpigmentazione cutanea focale in circa l'1 per cento dei partecipanti."],"sicherheit_en":["Nei trial clinici, la nausea si è verificata in circa il 40 per cento dei partecipanti con bremelanotide, rispetto a circa l'1 per cento nel placebo.","Un aumento transitorio della pressione sanguigna e una diminuzione della frequenza cardiaca sono stati osservati dopo ogni somministrazione, risolvendosi entro circa 12 ore secondo l'etichetta FDA.","Secondo l'etichetta FDA, Vyleesi è controindicato in ipertensione incontrollata o malattia cardiovascolare nota.","Nei trial RECONNECT, è stata osservata iperpigmentazione cutanea focale in circa l'1 per cento dei partecipanti."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"Bremelanotide è stato approvato dalla FDA come Vyleesi dal 2019 per l'indicazione di HSDD nelle donne premenopausali. In Germania e nell'UE, non esiste un'approvazione di farmaco e la sostanza è venduta lì esclusivamente come sostanza chimica di ricerca.","rechtsstatus_en":"Bremelanotide è stato approvato dalla FDA come Vyleesi dal 2019 per l'indicazione di HSDD nelle donne premenopausali. In Germania e nell'UE, non esiste un'approvazione di farmaco e la sostanza è venduta lì esclusivamente come sostanza chimica di ricerca.","typischeMg":[10,20],"faq":[{"q":"PT-141 è lo stesso di melanotan II","a":"No. Entrambi risalgono a strutture melanocortin correlate, ma PT-141 (bremelanotide) è stato studiato specificamente per il desiderio sessuale, mentre melanotan II è stato ricercato principalmente per la pigmentazione cutanea. Solo bremelanotide ha raggiunto l'approvazione di mercato negli Stati Uniti, come Vyleesi.","q_en":"PT-141 è lo stesso di melanotan II","a_en":"No. Entrambi risalgono a strutture melanocortin correlate, ma PT-141 (bremelanotide) è stato studiato specificamente per il desiderio sessuale, mentre melanotan II è stato ricercato principalmente per la pigmentazione cutanea. Solo bremelanotide ha raggiunto l'approvazione di mercato negli Stati Uniti, come Vyleesi."},{"q":"Bremelanotide è un farmaco approvato","a":"Negli Stati Uniti, sì: dal 2019 bremelanotide è stato approvato con il nome Vyleesi per l'indicazione di HSDD nelle donne premenopausali. In Germania e nell'UE, non esiste un'approvazione di farmaco e la sostanza è classificata come sostanza chimica di ricerca lì.","q_en":"Bremelanotide è un farmaco approvato","a_en":"Negli Stati Uniti, sì: dal 2019 bremelanotide è stato approvato con il nome Vyleesi per l'indicazione di HSDD nelle donne premenopausali. In Germania e nell'UE, non esiste un'approvazione di farmaco e la sostanza è classificata come sostanza chimica di ricerca lì."},{"q":"Quali effetti collaterali sono stati osservati negli studi","a":"Gli effetti più frequentemente documentati sono nausea, rossore, mal di testa e aumenti transitori della pressione sanguigna dopo l' somministrazione. Secondo l'etichetta della FDA, la sostanza è controindicata in ipertensione incontrollata o malattia cardiovascolare nota.","q_en":"Quali effetti collaterali sono stati osservati negli studi","a_en":"Gli effetti più frequentemente documentati sono nausea, rossore, mal di testa e aumenti transitori della pressione sanguigna dopo l' somministrazione. Secondo l'etichetta della FDA, la sostanza è controindicata in ipertensione incontrollata o malattia cardiovascolare nota."}],"seo":{"title":"Panoramica della ricerca su PT-141 (bremelanotide)","title_en":"Panoramica della ricerca su PT-141 (bremelanotide)","description":"PT-141 (bremelanotide): meccanismo, dati degli studi, profilo di sicurezza e stato di approvazione di questo agonista del recettore della melanocortina in un colpo d'occhio.","description_en":"PT-141 (bremelanotide): meccanismo, dati degli studi, profilo di sicurezza e stato di approvazione di questo agonista del recettore della melanocortina in un colpo d'occhio."},"demo":false,"steckbrief":{"cas":"189691-06-3","molekulargewicht":"1025,2 g/mol","aminosaeuren":7,"halbwertszeit":"≈ 2,7 ore (emivita terminale, informazioni su Vyleesi)","reinheitsstandard":"≥ 99 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 9941379","DailyMed SPL VYLEESI (Bremelanotid), Cosette Pharmaceuticals","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 2,7 ore (emivita terminale, informazioni su Vyleesi)","reinheitsstandard_en":"≥ 99 % (HPLC, standard commerciale)"},"verwandt":["melanotan-2","kisspeptin","kpv"]},{"slug":"ss-31","name":"SS-31 (elamipretide)","synonyme":["Elamipretide","MTP-131","Bendavia"],"kategorie":"Sonstige","studienlage":"klinisch untersucht","kurz":"Un tetrapeptide mirato ai mitocondri studiato in diversi trial clinici per insufficienza cardiaca e malattia mitocondriale, non ancora approvato.","kurz_en":"Un tetrapeptide mirato ai mitocondri studiato in diversi trial clinici per insufficienza cardiaca e malattia mitocondriale, non ancora approvato.","beschreibung":"SS-31, noto anche con il nome generico elamipretide come MTP-131 o Bendavia, è un tetrapeptide sintetico che si lega specificamente alla cardiolina, un lipide nella membrana mitocondriale. È stato studiato in diversi trial clinici di fase 1 a fase 3 per insufficienza cardiaca, miopatia mitocondriale primaria e sindrome di Barth. Nonostante una base di dati clinici comparativamente ampia, nessuno di questi studi ha ancora portato all'approvazione come farmaco.","beschreibung_en":"SS-31, noto anche con il nome generico elamipretide come MTP-131 o Bendavia, è un tetrapeptide sintetico che si lega specificamente alla cardiolina, un lipide nella membrana mitocondriale. È stato studiato in diversi trial clinici di fase 1 a fase 3 per insufficienza cardiaca, miopatia mitocondriale primaria e sindrome di Barth. Nonostante una base di dati clinici comparativamente ampia, nessuno di questi studi ha ancora portato all'approvazione come farmaco.","mechanismus":"SS-31 si lega con alta affinità alla cardiolina sulla membrana mitocondriale interna, un lipide necessario per la struttura dei cristae. Questo è descritto come riducendo le specie reattive dell'ossigeno e stabilizzando la struttura della membrana mitocondriale. Nei modelli preclinici, questo è stato collegato alla protezione contro il danno da ischemia-riperfusione, ad esempio nel muscolo cardiaco.","mechanismus_en":"SS-31 si lega con alta affinità alla cardiolina sulla membrana mitocondriale interna, un lipide necessario per la struttura dei cristae. Questo è descritto come riducendo le specie reattive dell'ossigeno e stabilizzando la struttura della membrana mitocondriale. Nei modelli preclinici, questo è stato collegato alla protezione contro il danno da ischemia-riperfusione, ad esempio nel muscolo cardiaco.","evidenz":[{"art":"clinico","kurz":"Uno studio randomizzato, controllato con placebo di fase 3 in persone con miopatia mitocondriale primaria non ha raggiunto i suoi endpoint primari predefiniti né nel test di deambulazione di 6 minuti né nel punteggio di fatica, sebbene il farmaco dello studio sia stato descritto come ben tollerato.","kurz_en":"Uno studio randomizzato, controllato con placebo di fase 3 in persone con miopatia mitocondriale primaria non ha raggiunto i suoi endpoint primari predefiniti né nel test di deambulazione di 6 minuti né nel punteggio di fatica, sebbene il farmaco dello studio sia stato descritto come ben tollerato.","quelle":"Karaa et al. 2023, Neurology, PMID 37268435"},{"art":"clinico","kurz":"Uno studio di fase 1 controllato con placebo con quantità di infusione progressivamente crescenti in persone con insufficienza cardiaca e frazione di eiezione ridotta ha descritto un'unica infusione di elamipretide come sicura e ben tollerata.","kurz_en":"Uno studio di fase 1 controllato con placebo con quantità di infusione progressivamente crescenti in persone con insufficienza cardiaca e frazione di eiezione ridotta ha descritto un'unica infusione di elamipretide come sicura e ben tollerata.","quelle":"Daubert et al. 2017, Circulation: Heart Failure, PMID 29217757"},{"art":"preclinico","kurz":"Uno studio nei ratti con lesione da ischemia-riperfusione cardiaca ha descritto un'area di infarto significativamente più piccola quando SS-31 è stato somministrato in precedenza rispetto agli animali di controllo.","kurz_en":"Uno studio nei ratti con lesione da ischemia-riperfusione cardiaca ha descritto un'area di infarto significativamente più piccola quando SS-31 è stato somministrato in precedenza rispetto agli animali di controllo.","quelle":"Cho et al. 2007, Coronary Artery Disease, PMID 17429296"}],"sicherheit":["Negli studi clinici fino ad oggi, l'elamipretide è stata descritta prevalentemente come sicura e ben tollerata, con eventi avversi prevalentemente lievi a moderati.","Diversi studi, inclusi quelli sulla miopatia mitocondriale e il sindrome di Barth, non hanno raggiunto i loro endpoint di efficacia primari, motivo per cui una domanda di approvazione negli Stati Uniti non è stata accettata per la revisione dall'agenzia nel 2021.","Dati a lungo termine al di fuori dei programmi di studio controllati non sono disponibili.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"sicherheit_en":["Negli studi clinici fino ad oggi, l'elamipretide è stata descritta prevalentemente come sicura e ben tollerata, con eventi avversi prevalentemente lievi a moderati.","Diversi studi, inclusi quelli sulla miopatia mitocondriale e il sindrome di Barth, non hanno raggiunto i loro endpoint di efficacia primari, motivo per cui una domanda di approvazione negli Stati Uniti non è stata accettata per la revisione dall'agenzia nel 2021.","Dati a lungo termine al di fuori dei programmi di studio controllati non sono disponibili.","I prodotti provenienti da una produzione non controllata presentano un rischio di contaminazione indipendente dalla molecola stessa."],"hinweise":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"hinweise_en":["Esclusivamente a scopo di ricerca, non destinato all’uso umano","Un certificato di analisi non stabilisce idoneità medica"],"rekonstitution":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rekonstitution_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","lagerung_en":"Le condizioni specifiche del prodotto si trovano nella documentazione originale del produttore. Questo portale non fornisce istruzioni per la preparazione o l’uso umano.","rechtsstatus":"SS-31 (elamipretide) non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti. Una domanda di approvazione negli Stati Uniti del 2021 non è stata accettata per la revisione a causa della mancanza di uno studio di efficacia singolo adeguato e ben controllato. Viene venduto esclusivamente come prodotto chimico di ricerca.","rechtsstatus_en":"SS-31 (elamipretide) non è approvato come farmaco in Germania, nell'UE o negli Stati Uniti. Una domanda di approvazione negli Stati Uniti del 2021 non è stata accettata per la revisione a causa della mancanza di uno studio di efficacia singolo adeguato e ben controllato. Viene venduto esclusivamente come prodotto chimico di ricerca.","typischeMg":[],"faq":[{"q":"L'elamipretide è un farmaco approvato?","a":"No. Nonostante diversi studi clinici in insufficienza cardiaca, miopatia mitocondriale e sindrome di Barth, non è stata concessa alcuna approvazione, una domanda di approvazione negli Stati Uniti non è stata accettata per la revisione nel 2021.","q_en":"L'elamipretide è un farmaco approvato?","a_en":"No. Nonostante diversi studi clinici in insufficienza cardiaca, miopatia mitocondriale e sindrome di Barth, non è stata concessa alcuna approvazione, una domanda di approvazione negli Stati Uniti non è stata accettata per la revisione nel 2021."},{"q":"Cosa mira SS-31 nel corpo?","a":"Si lega alla cardiolina nella membrana mitocondriale interna ed è associato a una riduzione delle specie reattive dell'ossigeno e alla stabilizzazione della struttura della membrana.","q_en":"Cosa mira SS-31 nel corpo?","a_en":"Si lega alla cardiolina nella membrana mitocondriale interna ed è associato a una riduzione delle specie reattive dell'ossigeno e alla stabilizzazione della struttura della membrana."},{"q":"Gli studi clinici hanno raggiunto i loro obiettivi?","a":"Diversi studi non hanno raggiunto i loro endpoint di efficacia primari predefiniti, ad esempio nella miopatia mitocondriale e nel sindrome di Barth, mentre la tollerabilità è stata descritta costantemente come buona.","q_en":"Gli studi clinici hanno raggiunto i loro obiettivi?","a_en":"Diversi studi non hanno raggiunto i loro endpoint di efficacia primari predefiniti, ad esempio nella miopatia mitocondriale e nel sindrome di Barth, mentre la tollerabilità è stata descritta costantemente come buona."}],"seo":{"title":"SS-31 (elamipretide): Profilo di Ricerca ed Evidenze","title_en":"SS-31 (elamipretide): Profilo di Ricerca ed Evidenze","description":"Panoramica SS-31/elamipretide: meccanismo mitocondriale, evidenze cliniche nell'insufficienza cardiaca e nella miopatia mitocondriale, e profilo di sicurezza.","description_en":"Panoramica SS-31/elamipretide: meccanismo mitocondriale, evidenze cliniche nell'insufficienza cardiaca e nella miopatia mitocondriale, e profilo di sicurezza."},"demo":false,"steckbrief":{"cas":"736992-21-5","molekulargewicht":"639,8 g/mol","aminosaeuren":4,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard commerciale)","loeslichkeit":null,"sequenzLaenge":4,"quellen":["PubChem CID 11764719","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard commerciale)"},"verwandt":["mots-c","epitalon","dihexa"]}];
